INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们聊着一阵天，就各自回家了。", "corrected_sentence": "我们聊了一阵天，就各自回家了。", "error_description": "体标错误：“着”表示动作正在进行，不能与表示已完成的一段时间的“一阵”搭配，应说“聊了一阵天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
