INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96487, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "放在句尾，表示没想到，是在问。", "primary_collocate": null, "pronunciation": "bù chéng", "ipa": "pu˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "你还想骗我不成？", "target_word": "不成", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "难道你想一个人去不成？", "target_word": "不成", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他这么晚还不回家，难道出事了不成？", "target_word": "不成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么简单的题，你还想问老师不成？", "target_word": "不成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想饿一天不成？", "target_word": "不成", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "难道你喜欢吃冷饭不成？", "target_word": "不成", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天这么黑，你还要出去不成？", "target_word": "不成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想让我替你写作业不成？", "target_word": "不成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直不接电话，难道生气了不成？", "target_word": "不成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "难道我说错了不成？", "target_word": "不成", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "句末语气词，常与“难道”“还”连用，表示反问、不敢相信", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea1004ff-ce31-4d4c-a6ba-01a3019f6955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96487, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "路程", "is_correct": false, "explanation": "lù（第四声）与 bù 的声母不同（l 与 b），意思是路程、距离。"}, {"text": "不成", "is_correct": true, "explanation": "正确答案。bù chéng，句末语气词，表示反问，意思是“难道……吗”。"}, {"text": "不曾", "is_correct": false, "explanation": "céng（第二声）与 chéng 的声母不同（c 与 ch），“不曾”意思是从来没有、还没有。"}, {"text": "不长", "is_correct": false, "explanation": "cháng（第二声）与 chéng 的韵母不同（ang 与 eng），“不长”意思是不长久、不够长。"}, {"text": "不沉", "is_correct": false, "explanation": "chén（第二声）与 chéng 的韵母不同（en 与 eng），“不沉”意思是不下沉。"}], "explanations": {"路程": "lù（第四声）与 bù 的声母不同（l 与 b），意思是路程、距离。", "不成": "正确答案。bù chéng，句末语气词，表示反问，意思是“难道……吗”。", "不曾": "céng（第二声）与 chéng 的声母不同（c 与 ch），“不曾”意思是从来没有、还没有。", "不长": "cháng（第二声）与 chéng 的韵母不同（ang 与 eng），“不长”意思是不长久、不够长。", "不沉": "chén（第二声）与 chéng 的韵母不同（en 与 eng），“不沉”意思是不下沉。"}, "sentence_index": null, "correct_answer": "不成"}, "level_3": {"options": [{"text": "而已", "is_correct": false, "explanation": "语义：「而已」表示“只是如此”，与句中的反问语气不合，句子读不通。"}, {"text": "不成", "is_correct": true, "explanation": "正确答案。「不成」表示反问，意思是“难道你还想骗我吗”。"}, {"text": "罢了", "is_correct": false, "explanation": "语义：「罢了」表示“不过如此”，与“你还想骗我”的反问语境不合。"}, {"text": "来着", "is_correct": false, "explanation": "体貌：「来着」表示回想过去的情况，与句中“还想”表示的当前反问不合。"}], "explanations": {"而已": "语义：「而已」表示“只是如此”，与句中的反问语气不合，句子读不通。", "不成": "正确答案。「不成」表示反问，意思是“难道你还想骗我吗”。", "罢了": "语义：「罢了」表示“不过如此”，与“你还想骗我”的反问语境不合。", "来着": "体貌：「来着」表示回想过去的情况，与句中“还想”表示的当前反问不合。"}, "sentence_index": 0, "correct_answer": "不成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这么大的雨，我们今天去不成了。", "explanation": "这里应该用〈去不了〉。“不成”作补语表示未能去成，并非句末语气词。"}, {"text": "这道题我一个人做不成。", "explanation": "这里应该用〈做不出〉。“不成”作补语表示做不出来，并非句末语气词。"}, {"text": "这门课他这学期考不成了。", "explanation": "这里应该用〈考不过〉。“不成”作补语表示考不过，并非句末语气词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "着呢", "is_correct": false, "explanation": "体貌：「着呢」表示状态持续，与“你还要出去”的动作不合，句子读不通。"}, {"text": "不成", "is_correct": true, "explanation": "正确答案。「不成」表示反问，意思是“你还要出去吗”，带有不以为然的语气。"}, {"text": "也罢", "is_correct": false, "explanation": "语义：「也罢」表示“算了”的让步，句中没有这种语境，句子读不通。"}, {"text": "了", "is_correct": false, "explanation": "体貌：「了」表示已然或变化，不能用于句末的反问语气，句子读不通。"}], "explanations": {"着呢": "体貌：「着呢」表示状态持续，与“你还要出去”的动作不合，句子读不通。", "不成": "正确答案。「不成」表示反问，意思是“你还要出去吗”，带有不以为然的语气。", "也罢": "语义：「也罢」表示“算了”的让步，句中没有这种语境，句子读不通。", "了": "体貌：「了」表示已然或变化，不能用于句末的反问语气，句子读不通。"}, "sentence_index": 6, "correct_answer": "不成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么多的事，我一天做不成。", "explanation": "这里应该用〈做不完〉。“不成”作补语，并非句末语气词。"}, {"text": "这场比赛我们肯定赢不成。", "explanation": "这里应该用〈赢不了〉。“不成”作补语表示赢不了，并非句末语气词。"}, {"text": "今晚吃火锅，不成吃面。", "explanation": "这里应该用〈或者〉。“不成”不能用来表示二择一的选择。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你还想去他家不成吗？", "corrected_sentence": "你还想去他家不成？", "error_description": "错误在于“不成”后面又加了“吗”。“不成”本身已表示反问，两个疑问语气词不能叠用，应说“你还想去他家不成？”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么晚了，你还要出门了不成？", "corrected_sentence": "这么晚了，你还要出门不成？", "error_description": "错误在于“出门”后面加了“了”。反问句中“不成”前的动词后不接“了”，应说“你还要出门不成？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96495, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96495, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96495, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西有多有用，能满足我们什么需要。", "primary_collocate": null, "pronunciation": "shǐ yòng jià zhí", "ipa": "ʂɻ̩˨˩ jʊŋ˥˩ tɕja˥˩ ʈʂɻ̩˧˥", "syllable_count": 4, "sentences": [{"text": "这把旧椅子还有使用价值，别扔。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器太旧，已经没有使用价值了。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买东西以前，我会先想它的使用价值。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小工具使用价值很高，每天都用。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书的使用价值在于读，不在于好看。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个玩具太小，使用价值不大。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本词典使用价值大，学生都爱用。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏了的手机没有使用价值，我把它扔了。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，选工具要看它的使用价值。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个破箱子虽然旧了，但使用价值还在。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西有用的程度，能满足日常需要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06053499-ed7b-46b4-88c1-4bffbe9831f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96495, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使用价值", "is_correct": true, "explanation": "“使用价值”指东西有用、能满足需要的程度，与“还有”和“别扔”的语境相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温只属于活的生物，椅子没有体温，句子不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格指人或动物的特点，椅子不能有性格。"}, {"text": "年纪", "is_correct": false, "explanation": "搭配：“年纪”多用于人，不用于椅子，“还有年纪”不通。"}], "explanations": {"使用价值": "“使用价值”指东西有用、能满足需要的程度，与“还有”和“别扔”的语境相符。", "体温": "语义：体温只属于活的生物，椅子没有体温，句子不通。", "性格": "语义：性格指人或动物的特点，椅子不能有性格。", "年纪": "搭配：“年纪”多用于人，不用于椅子，“还有年纪”不通。"}, "sentence_index": 0, "correct_answer": "使用价值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的使用价值很高，大家都想买。", "explanation": "这里应该用〈艺术价值〉。画的价值在于艺术和欣赏，“使用价值”指物品满足日常需要的效用，不用于画。"}, {"text": "这位同事的使用价值很高，大家都愿意跟他合作。", "explanation": "这里应该用〈利用价值〉。“使用价值”只用于物品，说人有用要用“利用价值”。"}, {"text": "这首歌的使用价值很高，大家都在听。", "explanation": "这里应该用〈欣赏价值〉。歌曲的价值在于欣赏，不在于满足生活需要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96495, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使用价值", "is_correct": true, "explanation": "“使用价值”指词典有用的程度，“这本词典___大”的说法成立。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格的高低说“高”或“低”，不说“大”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型，词典没有身材。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，词典没有脾气，与“学生都爱用”的语境也不合。"}], "explanations": {"使用价值": "“使用价值”指词典有用的程度，“这本词典___大”的说法成立。", "价格": "搭配：价格的高低说“高”或“低”，不说“大”。", "身材": "体貌：“身材”指人的体型，词典没有身材。", "脾气": "语义：“脾气”指人的性情，词典没有脾气，与“学生都爱用”的语境也不合。"}, "sentence_index": 6, "correct_answer": "使用价值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个破箱子的使用价值很有名，人人都知道。", "explanation": "这里应该用〈大〉。“有名”说人或事物出名，不用于“使用价值”。"}, {"text": "这个破箱子的使用价值很沉重，我抬不动。", "explanation": "这里应该用〈大〉。“沉重”形容重量或心情，不用于“使用价值”。"}, {"text": "我把这个破箱子的使用价值搬到了楼上。", "explanation": "这里应该用〈实物〉。使用价值是抽象的效用，不能搬动；能搬动的只能是“实物”本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96495, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种旧工具很使用价值，我们留着吧。", "corrected_sentence": "这种旧工具有使用价值，我们留着吧。", "error_description": "错误：动词“有”被换成副词“很”，“很”不能修饰名词“使用价值”。正确：应为“有使用价值”，表示具有用处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96495, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张旧桌子还使用价值，我们先留着。", "corrected_sentence": "这张旧桌子还有使用价值，我们先留着。", "error_description": "错误：“还使用价值”漏掉了动词“有”。正确：应为“还有使用价值”，表示仍然具有用处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
