INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96496, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96496, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物品能够满足人的某种需要的效用。", "primary_collocate": null, "pronunciation": "shǐ yòng jià zhí", "ipa": "ʂɻ̩˨˩ jʊŋ˥˩ tɕja˥˩ ʈʂɻ̩˧˥", "syllable_count": 4, "sentences": [{"text": "商品要有使用价值，人们才会买。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包的使用价值是让人吃饱。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一件商品有价格，也有使用价值。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水的使用价值很大，因为人人都要喝水。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人需要的东西，就没有使用价值。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济课上，老师讲了商品的使用价值。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一把伞的使用价值是挡雨。", "target_word": "使用价值", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "衣服的使用价值是保暖，也能让人好看。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商品的使用价值不同，价格也会不同。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了这把刀，是看中它的使用价值。", "target_word": "使用价值", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "商品满足人某种需要的效用（经济学）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06053499-ed7b-46b4-88c1-4bffbe9831f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使用价值", "is_correct": true, "explanation": "“使用价值”指商品满足人需要的效用，与“要有”“人们才会买”相符。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指生物的温度，商品没有体温。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”形容人的性情，商品不说脾气。"}, {"text": "气色", "is_correct": false, "explanation": "体貌：“气色”指人的脸色，商品没有气色。"}], "explanations": {"使用价值": "“使用价值”指商品满足人需要的效用，与“要有”“人们才会买”相符。", "体温": "语义：体温指生物的温度，商品没有体温。", "脾气": "语义：“脾气”形容人的性情，商品不说脾气。", "气色": "体貌：“气色”指人的脸色，商品没有气色。"}, "sentence_index": 0, "correct_answer": "使用价值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的使用价值是五十元。", "explanation": "这里应该用〈价格〉。使用价值说的是商品的效用，不是用金额表示的价钱。"}, {"text": "这套邮票的使用价值很高，大家都想买。", "explanation": "这里应该用〈收藏价值〉。邮票的价值在于收藏，不在于满足日常需要。"}, {"text": "这张纸币的使用价值是一百元。", "explanation": "这里应该用〈面值〉。纸币上印的一百元是面值，不是使用价值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使用价值", "is_correct": true, "explanation": "“使用价值”指伞能满足挡雨需要的效用，与“是挡雨”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用来挡雨，与“是挡雨”的说明不符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人或动物的身长，伞没有身高。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能用来挡雨，与“是挡雨”不符。"}], "explanations": {"使用价值": "“使用价值”指伞能满足挡雨需要的效用，与“是挡雨”相符。", "颜色": "语义：“颜色”不能用来挡雨，与“是挡雨”的说明不符。", "身高": "体貌：“身高”指人或动物的身长，伞没有身高。", "价格": "语义：“价格”指钱数，不能用来挡雨，与“是挡雨”不符。"}, "sentence_index": 6, "correct_answer": "使用价值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了这把刀，是看中它的使用价值很温柔。", "explanation": "这里应该用〈大〉。“温柔”形容人的性情，不能用来形容“使用价值”。"}, {"text": "他买了这把刀，是看中它的使用价值很幽默。", "explanation": "这里应该用〈大〉。“幽默”形容人的谈吐，不能用来形容“使用价值”。"}, {"text": "他买了这把刀，是看中它的使用价值的颜色。", "explanation": "使用价值是抽象的效用，没有颜色；应说“看中它的颜色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种新材料很使用价值，工厂都在用。", "corrected_sentence": "这种新材料有使用价值，工厂都在用。", "error_description": "错误：动词“有”被换成副词“很”，“很”不能修饰名词“使用价值”。正确：应为“有使用价值”，表示具有用处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种商品被使用价值，大家都需要。", "corrected_sentence": "这种商品有使用价值，大家都需要。", "error_description": "错误：“被”后应接动词，不能直接接名词“使用价值”。正确：应为“有使用价值”，表示具有用处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "说“我保证他会做到”的人。", "primary_collocate": null, "pronunciation": "bǎo zhèng rén", "ipa": "pɑʊ˨˩˦ ʈʂɤŋ˥˩ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他是我的保证人，我很放心。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王做事靠谱，朋友愿意当他的保证人。", "target_word": "保证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“我是他的保证人。”", "target_word": "保证人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说话算数，我愿意做他的保证人。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人给他当保证人，他很难过。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我相信弟弟，所以做了他的保证人。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的保证人说你一定会来。", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他答应老师不再迟到，班长愿意做他的保证人。", "target_word": "保证人", "complexity_tier": "T3", "furigana": "tā dā yìng lǎo shī bú zài chí dào, bān zhǎng yuàn yì zuò tā de bǎo zhèng rén.", "sentence_source": "generated"}, {"text": "妈妈是我最好的保证人，她知道我不会说谎。", "target_word": "保证人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁愿意给这个孩子当保证人？", "target_word": "保证人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位保证人", "label": "量词（位）"}, {"form": "保證人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为某人的品行或承诺作保、说他一定能做到的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea1004ff-ce31-4d4c-a6ba-01a3019f6955') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：人不能是书包，“他是我的书包”不成立。"}, {"text": "保证人", "is_correct": true, "explanation": "正确：保证人是为他人的品行或承诺作保的人，与“我很放心”相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“我很放心”要依托能让人信赖的人或事，“是……的天气”不是可以托付的对象。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不能用“是我的……”指人，句子不通。"}], "explanations": {"书包": "语义：人不能是书包，“他是我的书包”不成立。", "保证人": "正确：保证人是为他人的品行或承诺作保的人，与“我很放心”相符。", "天气": "搭配：“我很放心”要依托能让人信赖的人或事，“是……的天气”不是可以托付的对象。", "地铁": "语义：地铁是交通工具，不能用“是我的……”指人，句子不通。"}, "sentence_index": 0, "correct_answer": "保证人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "婚礼上，他是新郎的保证人，并在结婚证上签了字。", "explanation": "这里应该用〈见证人〉。见证人只在场证明事情经过，不对承诺负责；保证人要为某人的品行或承诺作保。"}, {"text": "他是这个孩子的保证人，每天负责接送他上学。", "explanation": "这里应该用〈监护人〉。监护人负责照顾未成年人的日常生活，保证人只为某人的承诺作保，不负责照顾。"}, {"text": "他是我的保证人，每天带我练习跑步。", "explanation": "这里应该用〈教练〉。教练指导训练，保证人不做指导，只为别人的承诺作保。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业不会说话，“作业说你一定会来”不成立。"}, {"text": "窗帘", "is_correct": false, "explanation": "配价：“说”的主语必须能说话，窗帘不能充当说话的人。"}, {"text": "保证人", "is_correct": true, "explanation": "正确：保证人为你的承诺作保，可以说“你一定会来”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物品，不能“说”话，与句子的语境不符。"}], "explanations": {"作业": "语义：作业不会说话，“作业说你一定会来”不成立。", "窗帘": "配价：“说”的主语必须能说话，窗帘不能充当说话的人。", "保证人": "正确：保证人为你的承诺作保，可以说“你一定会来”。", "雨伞": "语义：雨伞是物品，不能“说”话，与句子的语境不符。"}, "sentence_index": 6, "correct_answer": "保证人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的保证人在法庭上替我辩护。", "explanation": "这里应该用〈律师〉。律师代理诉讼、替人辩护；保证人只为某人的品行或承诺作保，不在法庭上辩护。"}, {"text": "他是我的保证人，帮我认识了新朋友。", "explanation": "这里应该用〈介绍人〉。介绍人为人牵线、引荐，保证人是为承诺负责的人，不负责介绍。"}, {"text": "我的保证人每天给我下达任务，我要向他汇报工作。", "explanation": "这里应该用〈上司〉。上司对下属下达任务，保证人与工作安排无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我一把保证人，我放心多了。", "corrected_sentence": "他是我的保证人，我放心多了。", "error_description": "量词误用：“保证人”指人，不能用“把”（“把”多用于有柄的物件）；修饰语应为“我的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96499, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子需要一只保证人。", "corrected_sentence": "这个孩子需要一位保证人。", "error_description": "量词错误：“保证人”指人，不能用“只”（“只”多用于动物），应说“一位保证人”或“一个保证人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96500, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04a81064-6c0a-43ab-b1ca-94f2d06affc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
