INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96507, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把东西一行一行写出来的单子。", "primary_collocate": null, "pronunciation": "liè biǎo", "ipa": "liɛ˥˩ piɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我在纸上写了一个购物列表。", "target_word": "列表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把要带的东西写在列表上。", "target_word": "列表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个列表上有五样东西。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈每天都看购物列表。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "列表太长，我买不完。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你先看一下这个列表。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把旅行要带的东西做成了列表。", "target_word": "列表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的列表里没有牛奶。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师给我们一个生词列表。", "target_word": "列表", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买东西时，我会照着列表找。", "target_word": "列表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "购物列表", "label": "复合"}], "register": "中性", "sense_fingerprint": "把要买、要带的东西一行一行写下来的单子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6906149-0c7e-411f-8ebe-5000e4ee9871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96507, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "列表", "is_correct": true, "explanation": "正确：“列表”指按行写出的物品清单，可以用“个”计量，写在纸上。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“购物电话”不是可以写在纸上的东西，句子说不通。"}, {"text": "购物袋", "is_correct": false, "explanation": "语义：购物袋是装东西的袋子，不能写在纸上。"}, {"text": "购物车", "is_correct": false, "explanation": "语义：购物车是推着用的器具，不是能写下来的东西。"}], "explanations": {"列表": "正确：“列表”指按行写出的物品清单，可以用“个”计量，写在纸上。", "电话": "语义：“购物电话”不是可以写在纸上的东西，句子说不通。", "购物袋": "语义：购物袋是装东西的袋子，不能写在纸上。", "购物车": "语义：购物车是推着用的器具，不是能写下来的东西。"}, "sentence_index": 0, "correct_answer": "列表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本菜谱的列表在最前面。", "explanation": "这里应该用〈目录〉。书前面按章节列出页码的部分叫目录；列表指按行写出的清单，不用来指书的前面部分。"}, {"text": "这个月的列表我还没付钱。", "explanation": "这里应该用〈账单〉。要付钱的是账单，列表只是写出来的清单，不能付款。"}, {"text": "这张列表上写满了音符。", "explanation": "这里应该用〈乐谱〉。写满音符、用来演奏的是乐谱，列表只是一行一行的清单，不能说“写满了音符”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96507, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "列表", "is_correct": true, "explanation": "正确：“做成列表”指把要带的东西写成一行行的清单，搭配自然。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声是声音，不能拿来“做成”要带的东西。"}, {"text": "恩泽", "is_correct": false, "explanation": "语域：“恩泽”是书面雅词，用在这种口语叙述里不合语域。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，也不能写成要带的东西的清单。"}], "explanations": {"列表": "正确：“做成列表”指把要带的东西写成一行行的清单，搭配自然。", "歌声": "语义：歌声是声音，不能拿来“做成”要带的东西。", "恩泽": "语域：“恩泽”是书面雅词，用在这种口语叙述里不合语域。", "空气": "语义：空气看不见，也不能写成要带的东西的清单。"}, "sentence_index": 6, "correct_answer": "列表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "列表带我找到了那家店。", "explanation": "这里应该用〈导航〉。能指路、带人找到地方的是导航，列表只是写出来的清单，不能带路。"}, {"text": "我用列表开了门。", "explanation": "这里应该用〈钥匙〉。能开门的是钥匙，列表不能用来开锁。"}, {"text": "这班火车的列表是七点发车。", "explanation": "这里应该用〈时刻表〉。写明车次和发车时间的是时刻表，列表只是一行一行的清单，不能说“这班火车的列表”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96507, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这把购物列表放进了口袋。", "corrected_sentence": "我把这张购物列表放进了口袋。", "error_description": "量词错误：“列表”是写在纸上的东西，应说“这张购物列表”。“把”用于有柄的器具，不能用来计量“列表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96507, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给了我一台购物列表。", "corrected_sentence": "妈妈给了我一张购物列表。", "error_description": "量词错误：“列表”是纸上的内容，应说“一张”；“台”用于机器、电器，不能用来计量“列表”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
