INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96515, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个数比另一个数多。", "primary_collocate": null, "pronunciation": "dà yú", "ipa": "ta˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "八大于五。", "target_word": "大于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "三大于二，所以三比二多。", "target_word": "大于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请写一个大于十的数。", "target_word": "大于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哪个数大于九？", "target_word": "大于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "十二大于十一，也大于十。", "target_word": "大于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一个数大于零，就是正数。", "target_word": "大于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些数字里，有三个大于二十。", "target_word": "大于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "零大于负一。", "target_word": "大于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师问：七是不是大于六？", "target_word": "大于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的得分是九十，大于八十。", "target_word": "大于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大于等于", "label": "复合"}, {"form": "大于号", "label": "复合"}, {"form": "大於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "大于：一个数比另一个数多，数学比较", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '985b8fb7-0352-4226-b681-027abeaba146') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96515, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大于", "is_correct": true, "explanation": "大于 dà yú：一个数比另一个数大。"}, {"text": "大雨", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是大的雨。"}, {"text": "打鱼", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，意思是捕鱼。"}, {"text": "炸鱼", "is_correct": false, "explanation": "zhà 与 dà 声母不同，zh 与 d 不同，意思是油炸的鱼。"}], "explanations": {"大于": "大于 dà yú：一个数比另一个数大。", "大雨": "yǔ（第三声）与 yú（第二声）声调不同，意思是大的雨。", "打鱼": "dǎ（第三声）与 dà（第四声）声调不同，意思是捕鱼。", "炸鱼": "zhà 与 dà 声母不同，zh 与 d 不同，意思是油炸的鱼。"}, "sentence_index": null, "correct_answer": "大于"}, "level_3": {"options": [{"text": "大于", "is_correct": true, "explanation": "大于：八比五多，符合数学事实。"}, {"text": "小于", "is_correct": false, "explanation": "语义：小于表示比较的数更少，“八小于五”与数学事实相反。"}, {"text": "等于", "is_correct": false, "explanation": "语义：等于表示相同，八与五并不相等。"}, {"text": "减去", "is_correct": false, "explanation": "搭配：减去表示运算，不用来表示两数大小的比较。"}], "explanations": {"大于": "大于：八比五多，符合数学事实。", "小于": "语义：小于表示比较的数更少，“八小于五”与数学事实相反。", "等于": "语义：等于表示相同，八与五并不相等。", "减去": "搭配：减去表示运算，不用来表示两数大小的比较。"}, "sentence_index": 0, "correct_answer": "大于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性格大于我的性格。", "explanation": "这里应该用〈比……开朗〉。本义项只用于数的大小比较，性格的程度差别要用“比”加形容词表示。"}, {"text": "红色大于蓝色。", "explanation": "这里应该用〈鲜艳〉。本义项只用于数的大小比较，颜色的鲜艳程度要用形容词表示，如“红色比蓝色鲜艳”。"}, {"text": "这首歌大于那首歌。", "explanation": "这里应该用〈好听〉。本义项只用于数的大小比较，歌曲的优劣要用形容词表示，如“这首歌比那首好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96515, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大于", "is_correct": true, "explanation": "大于 dà yú：一个数比另一个数大。"}, {"text": "带鱼", "is_correct": false, "explanation": "dài（第四声）与 dà（第四声）韵母不同，ai 与 a 不同，意思是一种鱼。"}, {"text": "达于", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）声调不同，意思是到达。"}, {"text": "打鱼", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，意思是捕鱼。"}], "explanations": {"大于": "大于 dà yú：一个数比另一个数大。", "带鱼": "dài（第四声）与 dà（第四声）韵母不同，ai 与 a 不同，意思是一种鱼。", "达于": "dá（第二声）与 dà（第四声）声调不同，意思是到达。", "打鱼": "dǎ（第三声）与 dà（第四声）声调不同，意思是捕鱼。"}, "sentence_index": null, "correct_answer": "大于"}, "level_3": {"options": [{"text": "大于", "is_correct": true, "explanation": "大于：这些数字中有三个数比二十大，符合语境。"}, {"text": "认识", "is_correct": false, "explanation": "语义：认识指知道、了解，数字之间不存在认识关系。"}, {"text": "打败", "is_correct": false, "explanation": "搭配：打败要求有生命的对象，数字不能被打败。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：喜欢是情感，与数字的大小比较无关。"}], "explanations": {"大于": "大于：这些数字中有三个数比二十大，符合语境。", "认识": "语义：认识指知道、了解，数字之间不存在认识关系。", "打败": "搭配：打败要求有生命的对象，数字不能被打败。", "喜欢": "语义：喜欢是情感，与数字的大小比较无关。"}, "sentence_index": 6, "correct_answer": "大于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春天大于冬天。", "explanation": "这里应该用〈暖和〉。本义项只用于数的大小比较，季节的冷暖要用形容词表示，如“春天比冬天暖和”。"}, {"text": "他的得分是九十，大于他的朋友。", "explanation": "这里应该用〈高〉。大于比较两个数的大小，得分和人不能直接比较，要说“他的得分比朋友的高”。"}, {"text": "这部电影大于那部电影。", "explanation": "这里应该用〈精彩〉。本义项只用于数的大小比较，电影的好坏要用形容词表示，如“这部电影比那部精彩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warning