XCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96516, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大于", "is_correct": true, "explanation": "大于 dà yú：数量或程度超过另一方。"}, {"text": "大雨", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是大的雨。"}, {"text": "打鱼", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，意思是捕鱼。"}, {"text": "带鱼", "is_correct": false, "explanation": "dài（第四声）与 dà（第四声）韵母不同，ai 与 a 不同，意思是一种鱼。"}], "explanations": {"大于": "大于 dà yú：数量或程度超过另一方。", "大雨": "yǔ（第三声）与 yú（第二声）声调不同，意思是大的雨。", "打鱼": "dǎ（第三声）与 dà（第四声）声调不同，意思是捕鱼。", "带鱼": "dài（第四声）与 dà（第四声）韵母不同，ai 与 a 不同，意思是一种鱼。"}, "sentence_index": null, "correct_answer": "大于"}, "level_3": {"options": [{"text": "大于", "is_correct": true, "explanation": "大于：数量或程度超过另一方，用于比较面积的大小。"}, {"text": "位于", "is_correct": false, "explanation": "搭配：位于表示处在某处，不能与“面积”构成比较。"}, {"text": "遗忘", "is_correct": false, "explanation": "语义：遗忘指忘记，面积不能被遗忘，与比较无关。"}, {"text": "保存", "is_correct": false, "explanation": "语义：保存指保留下来，与比较面积的大小无关。"}], "explanations": {"大于": "大于：数量或程度超过另一方，用于比较面积的大小。", "位于": "搭配：位于表示处在某处，不能与“面积”构成比较。", "遗忘": "语义：遗忘指忘记，面积不能被遗忘，与比较无关。", "保存": "语义：保存指保留下来，与比较面积的大小无关。"}, "sentence_index": 0, "correct_answer": "大于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于大于了纪录。", "explanation": "这里应该用〈打破〉。大于比较数量或程度，突破纪录要说打破。"}, {"text": "他按时大于了作业。", "explanation": "这里应该用〈完成〉。大于比较数量或程度，作业做完要说完成。"}, {"text": "这种方法大于那种方法。", "explanation": "这里应该用〈优于〉。大于比较的是数量或程度，方法的优劣比较要说优于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96516, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大于", "is_correct": true, "explanation": "大于 dà yú：数量或程度超过另一方。"}, {"text": "炸鱼", "is_correct": false, "explanation": "zhà 与 dà 声母不同，zh 与 d 不同，意思是油炸的鱼。"}, {"text": "达于", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）声调不同，意思是到达。"}, {"text": "打鱼", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）声调不同，意思是捕鱼。"}], "explanations": {"大于": "大于 dà yú：数量或程度超过另一方。", "炸鱼": "zhà 与 dà 声母不同，zh 与 d 不同，意思是油炸的鱼。", "达于": "dá（第二声）与 dà（第四声）声调不同，意思是到达。", "打鱼": "dǎ（第三声）与 dà（第四声）声调不同，意思是捕鱼。"}, "sentence_index": null, "correct_answer": "大于"}, "level_3": {"options": [{"text": "大于", "is_correct": true, "explanation": "大于：难度超过另一次考试，用于比较程度。"}, {"text": "停止", "is_correct": false, "explanation": "搭配：停止后接动作，不能直接带“上一次”这样的时间作宾语。"}, {"text": "仿效", "is_correct": false, "explanation": "语义：仿效指模仿他人，难度不能去仿效别的事物。"}, {"text": "等待", "is_correct": false, "explanation": "语义：等待指停下来等候，难度不能去等待上一次考试。"}], "explanations": {"大于": "大于：难度超过另一次考试，用于比较程度。", "停止": "搭配：停止后接动作，不能直接带“上一次”这样的时间作宾语。", "仿效": "语义：仿效指模仿他人，难度不能去仿效别的事物。", "等待": "语义：等待指停下来等候，难度不能去等待上一次考试。"}, "sentence_index": 6, "correct_answer": "大于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中大于了我。", "explanation": "这里应该用〈领先〉。大于比较数量或程度，比赛中的先后名次要说领先。"}, {"text": "妈妈大于爸爸。", "explanation": "这里应该用〈年长〉。大于比较数量或程度，人的年龄长幼要说“年长”。"}, {"text": "这篇文章大于那篇文章。", "explanation": "这里应该用〈胜于〉。大于比较数量或程度，文章的优劣比较要说胜于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座山的高度比大于那座山。", "corrected_sentence": "这座山的高度大于那座山。", "error_description": "错误形式“比大于”，“大于”本身已含比较义，不能再与“比”合用。正确形式为“高度大于那座山”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个学校的学生数很大于那个学校的学生数。", "corrected_sentence": "这个学校的学生数大于那个学校的学生数。", "error_description": "程度副词“很”不能修饰比较动词“大于”，“大于”本身已表示比较。应去掉“很”，说“这个学校的学生数大于那个学校的学生数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8434301-4280-4f4a-9915-e743c7ff9229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
