INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96523, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "平时大家都这样做的做法。", "primary_collocate": null, "pronunciation": "cháng guī", "ipa": "ʈʂʰɑŋ˧˥ kweɪ˥", "syllable_count": 2, "sentences": [{"text": "在我们家，饭前洗手是常规。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "早起锻炼是他的常规。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "按常规，我们周末去爷爷家吃饭。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样做是这里的常规。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他今天没有按常规上班。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天天跑步已经成了我的常规。", "target_word": "常规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家店周一休息，这是常规。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都照常规办事。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不想再按常规做事了。", "target_word": "常规", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡前看书是我们家的常规。", "target_word": "常规", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "常规武器", "label": "复合"}, {"form": "常规检查", "label": "复合"}], "register": "中性", "sense_fingerprint": "平时大家照例都这样做的习惯做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6906149-0c7e-411f-8ebe-5000e4ee9871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "常规", "is_correct": true, "explanation": "正确：“是常规”指平时大家照例这样做，符合饭前洗手的习惯。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：饭前洗手不是颜色，“是颜色”说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指体型，与洗手无关，属于体貌不合。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：洗手不是蛋糕，句子意思不通。"}], "explanations": {"常规": "正确：“是常规”指平时大家照例这样做，符合饭前洗手的习惯。", "颜色": "语义：饭前洗手不是颜色，“是颜色”说不通。", "身材": "体貌：“身材”指体型，与洗手无关，属于体貌不合。", "蛋糕": "语义：洗手不是蛋糕，句子意思不通。"}, "sentence_index": 0, "correct_answer": "常规"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个数字有一定的常规。", "explanation": "这里应该用〈规律〉。事物反复出现的规则叫规律；常规指平时大家照例的做法，不说“有一定的常规”。"}, {"text": "这位歌手的常规很好听。", "explanation": "这里应该用〈声音〉。能“好听”的是声音或嗓音，常规指平时照例的做法，不说“很好听”。"}, {"text": "这个房间的常规很暖和。", "explanation": "这里应该用〈温度〉。能“暖和”的是温度，常规指平时照例的做法，不说“很暖和”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常规", "is_correct": true, "explanation": "正确：“这是常规”指这家店平时照例周一休息，符合语境。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：周一休息不是眼泪，“这是眼泪”说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：周一休息不是天气，句子意思不通。"}, {"text": "夙愿", "is_correct": false, "explanation": "语域：“夙愿”是书面词，指长久的心愿，用在这种生活叙述里不合语域。"}], "explanations": {"常规": "正确：“这是常规”指这家店平时照例周一休息，符合语境。", "眼泪": "语义：周一休息不是眼泪，“这是眼泪”说不通。", "天气": "语义：周一休息不是天气，句子意思不通。", "夙愿": "语域：“夙愿”是书面词，指长久的心愿，用在这种生活叙述里不合语域。"}, "sentence_index": 6, "correct_answer": "常规"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑的常规很高。", "explanation": "这里应该用〈规格〉。能“高”的是规格或配置，常规指平时照例的做法，不说“很高”。"}, {"text": "这部电影的常规很美。", "explanation": "这里应该用〈场景〉。能“美”的是画面或场景，常规指平时照例的做法，不说“很美”。"}, {"text": "我们家订了一份常规。", "explanation": "这里应该用〈报纸〉。能订阅的是报刊，常规指平时照例的做法，不能订阅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "早睡早起是我们家的一台常规。", "corrected_sentence": "早睡早起是我们家的一种常规。", "error_description": "量词错误：“常规”是做法，不能用“台”（“台”多用于机器、电器），应说“一种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都按常规的练琴。", "corrected_sentence": "他每天都按常规练琴。", "error_description": "结构错误：“按常规”作方式状语修饰动词，后面不能加“的”，应说“按常规练琴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
