INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96531, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "对人对事一心一意，不会变心。", "primary_collocate": null, "pronunciation": "zhōng chéng", "ipa": "ʈʂʊŋ˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这只狗对主人很忠诚。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是一个忠诚的朋友。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她对爱人一直很忠诚。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好朋友应该忠诚。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的小狗非常忠诚。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他对妻子忠诚一辈子。", "target_word": "忠诚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板喜欢忠诚的员工。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他忠诚，也很会照顾人。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不管多难，他都对朋友很忠诚。", "target_word": "忠诚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "忠诚的人不会把秘密告诉别人。", "target_word": "忠诚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忠诚度", "label": "复合"}, {"form": "忠诚地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "对某个人或某件事一心一意、始终不变心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6906149-0c7e-411f-8ebe-5000e4ee9871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96531, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忠诚", "is_correct": true, "explanation": "忠诚 zhōng chéng：对人对事一心一意，不会变心。"}, {"text": "冲程", "is_correct": false, "explanation": "chōng 与 zhōng 声母不同（ch 与 zh），意思是发动机的冲程。"}, {"text": "中层", "is_correct": false, "explanation": "céng 与 chéng 声母不同（c 与 ch），意思是中间的一层。"}, {"text": "忠臣", "is_correct": false, "explanation": "chén 与 chéng 韵尾不同（n 与 ng），意思是忠心的大臣。"}, {"text": "工程", "is_correct": false, "explanation": "gōng 与 zhōng 声母不同（g 与 zh），意思是工程项目。"}], "explanations": {"忠诚": "忠诚 zhōng chéng：对人对事一心一意，不会变心。", "冲程": "chōng 与 zhōng 声母不同（ch 与 zh），意思是发动机的冲程。", "中层": "céng 与 chéng 声母不同（c 与 ch），意思是中间的一层。", "忠臣": "chén 与 chéng 韵尾不同（n 与 ng），意思是忠心的大臣。", "工程": "gōng 与 zhōng 声母不同（g 与 zh），意思是工程项目。"}, "sentence_index": null, "correct_answer": "忠诚"}, "level_3": {"options": [{"text": "忠诚", "is_correct": true, "explanation": "忠诚：对主人一心一意，符合句意。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：“凶狠”表示恶意，与狗对主人亲近的语境相反。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”说智力，不说对人的态度。"}, {"text": "干净", "is_correct": false, "explanation": "体貌：“干净”说外表整洁，不能描述对主人的态度。"}], "explanations": {"忠诚": "忠诚：对主人一心一意，符合句意。", "凶狠": "语义：“凶狠”表示恶意，与狗对主人亲近的语境相反。", "聪明": "搭配：“聪明”说智力，不说对人的态度。", "干净": "体貌：“干净”说外表整洁，不能描述对主人的态度。"}, "sentence_index": 0, "correct_answer": "忠诚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个译本忠诚于原文，读起来很准确。", "explanation": "这里应该用〈忠实〉。忠诚形容人对人或事的专一不变，说译文与原文相符要用忠实。"}, {"text": "他忠诚地回答了老师的问题。", "explanation": "这里应该用〈诚实〉。忠诚表示专一不变，回答问题说真话要用诚实。"}, {"text": "他忠诚地向大家道了歉。", "explanation": "这里应该用〈诚恳〉。忠诚表示对人或事的专一，道歉时的态度要用诚恳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96531, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "忠诚", "is_correct": true, "explanation": "忠诚 zhōng chéng：对人对事一心一意，不会变心。"}, {"text": "章程", "is_correct": false, "explanation": "zhāng 与 zhōng 韵母不同（a 与 o），意思是规章制度。"}, {"text": "征程", "is_correct": false, "explanation": "zhēng 与 zhōng 韵母不同（e 与 o），意思是旅途或历程。"}, {"text": "东城", "is_correct": false, "explanation": "dōng 与 zhōng 声母不同（d 与 zh），是地名，指北京的东城区。"}], "explanations": {"忠诚": "忠诚 zhōng chéng：对人对事一心一意，不会变心。", "章程": "zhāng 与 zhōng 韵母不同（a 与 o），意思是规章制度。", "征程": "zhēng 与 zhōng 韵母不同（e 与 o），意思是旅途或历程。", "东城": "dōng 与 zhōng 声母不同（d 与 zh），是地名，指北京的东城区。"}, "sentence_index": null, "correct_answer": "忠诚"}, "level_3": {"options": [{"text": "忠诚", "is_correct": true, "explanation": "忠诚：对人一心一意，符合“老板喜欢……的员工”的语境。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与老板喜欢的员工形象相反。"}, {"text": "昂贵", "is_correct": false, "explanation": "搭配：“昂贵”说价格，不能修饰人。"}, {"text": "陈旧", "is_correct": false, "explanation": "搭配：“陈旧”说物品或观念，不能修饰员工。"}], "explanations": {"忠诚": "忠诚：对人一心一意，符合“老板喜欢……的员工”的语境。", "懒惰": "语义：“懒惰”与老板喜欢的员工形象相反。", "昂贵": "搭配：“昂贵”说价格，不能修饰人。", "陈旧": "搭配：“陈旧”说物品或观念，不能修饰员工。"}, "sentence_index": 6, "correct_answer": "忠诚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她很忠诚，常请朋友吃饭。", "explanation": "这里应该用〈大方〉。忠诚表示对人或事的专一，形容慷慨请客要用大方。"}, {"text": "他说话很忠诚，从不绕弯子。", "explanation": "这里应该用〈直率〉。忠诚说的是专一不变，形容说话直截了当要用直率。"}, {"text": "我向大家送上忠诚的祝福。", "explanation": "这里应该用〈诚挚〉。忠诚修饰人或事的专一，祝福表达真心要用诚挚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warn