INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96531, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他忠诚的地守护着朋友的秘密。", "corrected_sentence": "他忠诚地守护着朋友的秘密。", "error_description": "“忠诚”作状语修饰动词“守护”时只用“地”；此处又加“的”，“的”“地”重复叠用，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96531, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位忠诚了的老员工从不迟到。", "corrected_sentence": "那位忠诚的老员工从不迟到。", "error_description": "“忠诚”修饰名词“老员工”时后面用“的”，“了”不能加在“忠诚”后面，应说“忠诚的老员工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
