INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96533, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "本来就该有的。", "primary_collocate": null, "pronunciation": "yīng yǒu", "ipa": "iŋ˥ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "这座桥已经失去了应有的作用。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子旧了，没有应有的样子。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩没有达到应有的水平。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，花园又有了应有的生气。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书都放回了应有的位置。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们应有的快乐，一样也不能少。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章缺少应有的内容。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了问题，他却没有应有的反应。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话没有发挥应有的作用。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法没有起到应有的效果。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "应有：事物本来就该有的作用、水平、样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437cb559-6856-4d1f-a96f-ccfdf83827d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应有", "is_correct": true, "explanation": "正确：应有指桥本来应当具有的作用。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”的对象是费用，不说收取作用。"}, {"text": "享有", "is_correct": false, "explanation": "搭配：“享有”的对象是权利、声誉，不说享有桥的作用。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”指主动丢掉，与“失去”所表示的被动丢失语境不合。"}], "explanations": {"应有": "正确：应有指桥本来应当具有的作用。", "收取": "搭配：“收取”的对象是费用，不说收取作用。", "享有": "搭配：“享有”的对象是权利、声誉，不说享有桥的作用。", "放弃": "语义：“放弃”指主动丢掉，与“失去”所表示的被动丢失语境不合。"}, "sentence_index": 0, "correct_answer": "应有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花园里应有几株杂草。", "explanation": "这里应该用〈冒出〉。应有指本来就该有的样子，不用来说明杂草这类不该出现的东西。"}, {"text": "这场火灾应有很多伤痕。", "explanation": "这里应该用〈留下〉。应有指本来应当具有，不能用来说事故留下的伤痕。"}, {"text": "雨季过后，蚊子应有许多。", "explanation": "这里应该用〈增多〉。应有表示本来就该有的，不能用来说雨后蚊子数量增多这种变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应有", "is_correct": true, "explanation": "正确：应有指文章本来应当具备的内容，与“缺少”相呼应。"}, {"text": "免除", "is_correct": false, "explanation": "搭配：“免除”的对象是义务、责任，不说免除内容。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”的对象是费用，不说收取内容。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有”表示已经具备，与“缺少”前后矛盾。"}], "explanations": {"应有": "正确：应有指文章本来应当具备的内容，与“缺少”相呼应。", "免除": "搭配：“免除”的对象是义务、责任，不说免除内容。", "收取": "搭配：“收取”的对象是费用，不说收取内容。", "拥有": "语义：“拥有”表示已经具备，与“缺少”前后矛盾。"}, "sentence_index": 6, "correct_answer": "应有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药应有很多副作用。", "explanation": "这里应该用〈产生〉。应有指本来就该有的，不用于说明药物产生的副作用。"}, {"text": "村子应有洪水的破坏。", "explanation": "这里应该用〈遭受〉。应有只表示本来应有的，不能说村子应有洪水造成的破坏。"}, {"text": "这次事件应有很大的混乱。", "explanation": "这里应该用〈引起〉。应有表示本来应当具有，不用来说事件引起的混乱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器应有了的功能都要保留。", "corrected_sentence": "这台机器应有的功能都要保留。", "error_description": "错误在“应有”之后加了“了”。“应有的”是修饰名词的形式，“了”不能附在“应有”后面；应改为“应有的功能”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇文章应有完整地结构。", "corrected_sentence": "这篇文章应有完整的结构。", "error_description": "错误在“完整地结构”：“完整”是形容词，修饰名词时应用“的”，“地”只用于修饰动词。应改为“应有完整的结构”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
