INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "应当具有的；理应有的。", "primary_collocate": null, "pronunciation": "yīng yǒu", "ipa": "iŋ˥ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们要给孩子应有的尊重。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人应有的照顾，家人要做到。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得到了应有的奖励。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司没有应有的责任感。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作做好了，就能得到应有的回报。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生应有的礼貌，他都做到了。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里缺少应有的安全措施。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我们应有的帮助。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为这件事付出了应有的代价。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生应有的耐心，她一点也不缺。", "target_word": "应有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "应有：按道理、按身份应当具有（尊重、权利、责任等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437cb559-6856-4d1f-a96f-ccfdf83827d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应有", "is_correct": true, "explanation": "正确：应有表示按道理应当具有，此处指孩子应得的尊重。"}, {"text": "索取", "is_correct": false, "explanation": "语义：“索取”是向别人讨要，与“给孩子”的给予方向相反。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”的对象是费用、钱款，不说收取尊重。"}, {"text": "免除", "is_correct": false, "explanation": "搭配：“免除”的对象是义务、责任，不能说免除尊重。"}], "explanations": {"应有": "正确：应有表示按道理应当具有，此处指孩子应得的尊重。", "索取": "语义：“索取”是向别人讨要，与“给孩子”的给予方向相反。", "收取": "搭配：“收取”的对象是费用、钱款，不说收取尊重。", "免除": "搭配：“免除”的对象是义务、责任，不能说免除尊重。"}, "sentence_index": 0, "correct_answer": "应有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故中应有三名伤员。", "explanation": "这里应该用〈出现〉。应有表示按道理本来就该具有的东西，不用来说明伤亡这类不好的结果。"}, {"text": "我家应有一辆汽车，是父亲上周买的。", "explanation": "这里应该用〈拥有〉。应有表示按理本来就该具有，不用于说明刚买到的具体物品。"}, {"text": "他小时候应有一个哥哥，后来去世了。", "explanation": "这里应该用〈曾有〉。应有表示按理本来应当具有，不能用来说过去曾经有过的亲人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应有", "is_correct": true, "explanation": "正确：应有指本来应当具备的安全措施，与“缺少”前后呼应。"}, {"text": "享有", "is_correct": false, "explanation": "搭配：“享有”后接权利、待遇、声誉，不说享有安全措施。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有”表示已经具备，与“缺少”的语境正相反。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”的对象是费用、钱款，不说收取安全措施。"}], "explanations": {"应有": "正确：应有指本来应当具备的安全措施，与“缺少”前后呼应。", "享有": "搭配：“享有”后接权利、待遇、声誉，不说享有安全措施。", "拥有": "语义：“拥有”表示已经具备，与“缺少”的语境正相反。", "收取": "搭配：“收取”的对象是费用、钱款，不说收取安全措施。"}, "sentence_index": 6, "correct_answer": "应有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我应有他的一封信。", "explanation": "这里应该用〈收到〉。应有只表示按理应当具有，不用来陈述实际收到的具体东西。"}, {"text": "她去年应有一家公司，后来倒闭了。", "explanation": "这里应该用〈创办〉。应有表示理应具有，不能用来说某人曾经办过一家公司。"}, {"text": "他在比赛中应有一身的伤，还在休息。", "explanation": "这里应该用〈遭受〉。应有只表示理应具有的东西，不能用来说在比赛中身上遭受了伤害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每个人都应有了做人的尊严。", "corrected_sentence": "每个人都应有做人的尊严。", "error_description": "错误在“应有”后加了“了”。“应有”表示按理应当具有，后面直接接名词短语，不带“了”；应改为“每个人都应有做人的尊严”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作应有地待遇不能少。", "corrected_sentence": "这份工作应有的待遇不能少。", "error_description": "错误在“应有”之后用了“地”。“应有”修饰名词，要用“的”；“地”用于修饰动词。应改为“应有的待遇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "装", "is_correct": true, "explanation": "反义词：装指把零件组合成整体，与拆（分开）相反。"}, {"text": "搬", "is_correct": false, "explanation": "不是反义词：搬表示移动位置，与拆没有对立关系。"}, {"text": "送", "is_correct": false, "explanation": "不是反义词：送表示交付，与拆没有对立关系。"}, {"text": "修", "is_correct": false, "explanation": "不是反义词：修表示修理，与拆没有对立关系。"}], "correct_answer": "装", "explanations": {"装": "反义词：装指把零件组合成整体，与拆（分开）相反。", "搬": "不是反义词：搬表示移动位置，与拆没有对立关系。", "送": "不是反义词：送表示交付，与拆没有对立关系。", "修": "不是反义词：修表示修理，与拆没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "装", "is_correct": true, "explanation": "反义词：装指把零件组合成整体，与拆（分开）相反。"}, {"text": "吃", "is_correct": false, "explanation": "不是反义词：吃指把食物咽下，与拆没有对立关系。"}, {"text": "读", "is_correct": false, "explanation": "不是反义词：读表示看文字并理解，与拆没有对立关系。"}, {"text": "洗", "is_correct": false, "explanation": "不是反义词：洗表示用水去污，与拆没有对立关系。"}], "correct_answer": "装", "explanations": {"装": "反义词：装指把零件组合成整体，与拆（分开）相反。", "吃": "不是反义词：吃指把食物咽下，与拆没有对立关系。", "读": "不是反义词：读表示看文字并理解，与拆没有对立关系。", "洗": "不是反义词：洗表示用水去污，与拆没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个东西分开，一块一块拿下来。", "primary_collocate": null, "pronunciation": "chāi", "ipa": "ʈʂʰai̯˥", "syllable_count": 1, "sentences": [{"text": "他把旧毛衣拆了，重新织了一件。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在拆旧窗帘上的线。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把玩具车拆成了很多小块。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这个书架拆下来，搬到楼上。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把旧桌子一块一块拆下来。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拆着旧衣服上的扣子。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台旧电脑，我从来没拆过。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把坏了的钟拆了，看看里面。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我拆一下这张旧床。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明喜欢拆东西，总想看看里面是什么。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拆了", "label": "体标"}, {"form": "拆过", "label": "体标"}, {"form": "拆开", "label": "复合"}, {"form": "拆掉", "label": "复合"}], "register": "口语", "sense_fingerprint": "把整体的东西分开，一块一块拿下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6906149-0c7e-411f-8ebe-5000e4ee9871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆 chāi：把整体的东西分开，一块一块拿下来。"}, {"text": "柴", "is_correct": false, "explanation": "chái 与 chāi 声调不同，意思是柴火。"}, {"text": "猜", "is_correct": false, "explanation": "cāi 与 chāi 声母不同（c 与 ch），意思是猜测。"}, {"text": "灾", "is_correct": false, "explanation": "zāi 与 chāi 声母不同（z 与 ch），意思是灾难。"}, {"text": "筛", "is_correct": false, "explanation": "shāi 与 chāi 声母不同（sh 与 ch），意思是筛子。"}], "explanations": {"拆": "拆 chāi：把整体的东西分开，一块一块拿下来。", "柴": "chái 与 chāi 声调不同，意思是柴火。", "猜": "cāi 与 chāi 声母不同（c 与 ch），意思是猜测。", "灾": "zāi 与 chāi 声母不同（z 与 ch），意思是灾难。", "筛": "shāi 与 chāi 声母不同（sh 与 ch），意思是筛子。"}, "sentence_index": null, "correct_answer": "拆"}, "level_3": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆：把毛衣拆开重新织，符合句意。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”说移动，不能说把毛衣处理掉后再织。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把东西放进嘴里，与毛衣无关。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚碰撞，不能用于毛衣。"}], "explanations": {"拆": "拆：把毛衣拆开重新织，符合句意。", "搬": "搭配：“搬”说移动，不能说把毛衣处理掉后再织。", "吃": "语义：“吃”指把东西放进嘴里，与毛衣无关。", "踢": "语义：“踢”是用脚碰撞，不能用于毛衣。"}, "sentence_index": 0, "correct_answer": "拆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想把树上的苹果拆下来，带回家。", "explanation": "这里应该用〈摘〉。拆指把整体分开，从树上采果实要用摘。"}, {"text": "我想把衣服从衣架上拆下来，穿走。", "explanation": "这里应该用〈取〉。拆指把整体的部件分开，从衣架上拿下衣服要用取。"}, {"text": "我想把脚上的鞋拆下来，换双拖鞋。", "explanation": "这里应该用〈脱〉。拆指分开整体的部件，脱鞋要用脱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆 chāi：把整体的东西分开，一块一块拿下来。"}, {"text": "叉", "is_correct": false, "explanation": "chā 与 chāi 韵母不同，意思是叉子。"}, {"text": "呆", "is_correct": false, "explanation": "dāi 与 chāi 声母不同（d 与 ch），意思是呆板。"}, {"text": "摘", "is_correct": false, "explanation": "zhāi 与 chāi 声母不同（zh 与 ch），意思是摘下。"}], "explanations": {"拆": "拆 chāi：把整体的东西分开，一块一块拿下来。", "叉": "chā 与 chāi 韵母不同，意思是叉子。", "呆": "dāi 与 chāi 声母不同（d 与 ch），意思是呆板。", "摘": "zhāi 与 chāi 声母不同（zh 与 ch），意思是摘下。"}, "sentence_index": null, "correct_answer": "拆"}, "level_3": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆：表示拆开过、分解过，符合“从来没……过”的语境。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”只用于食物，不能用于电脑。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与电脑无关。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”用于动物或婴儿，不能用于电脑。"}], "explanations": {"拆": "拆：表示拆开过、分解过，符合“从来没……过”的语境。", "煮": "搭配：“煮”只用于食物，不能用于电脑。", "唱": "语义：“唱”指发出歌声，与电脑无关。", "喂": "搭配：“喂”用于动物或婴儿，不能用于电脑。"}, "sentence_index": 6, "correct_answer": "拆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都拆一锅汤，给全家喝。", "explanation": "这里应该用〈煮〉。拆指分开或拆下部件，不能用于汤；做汤要用煮。"}, {"text": "她每天都拆碗，从不偷懒。", "explanation": "这里应该用〈洗〉。拆指分开或拆毁，洗碗要用洗。"}, {"text": "他喜欢拆歌，每天都拆一首新歌。", "explanation": "这里应该用〈唱〉。拆不能用于歌曲，唱歌要用唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸把旧抽屉拆上来，换了新的。", "corrected_sentence": "爸爸把旧抽屉拆下来，换了新的。", "error_description": "“拆”后的趋向补语应为“下来”（表示从整体上分离），用“上来”表示方向错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96541, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没拆了这种旧收音机。", "corrected_sentence": "我从来没拆过这种旧收音机。", "error_description": "“从来没……过”表示经历，“拆”后应用“过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "建", "is_correct": true, "explanation": "反义词：建指建造，与把建筑拆毁相反。"}, {"text": "写", "is_correct": false, "explanation": "不是反义词：写表示书写，与拆没有对立关系。"}, {"text": "买", "is_correct": false, "explanation": "不是反义词：买表示购入，与拆没有对立关系。"}, {"text": "看", "is_correct": false, "explanation": "不是反义词：看表示视觉感知，与拆没有对立关系。"}], "correct_answer": "建", "explanations": {"建": "反义词：建指建造，与把建筑拆毁相反。", "写": "不是反义词：写表示书写，与拆没有对立关系。", "买": "不是反义词：买表示购入，与拆没有对立关系。", "看": "不是反义词：看表示视觉感知，与拆没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "建", "is_correct": true, "explanation": "反义词：建指建造，与把建筑拆毁相反。"}, {"text": "吃", "is_correct": false, "explanation": "不是反义词：吃指把食物咽下，与拆没有对立关系。"}, {"text": "唱", "is_correct": false, "explanation": "不是反义词：唱表示发出歌声，与拆没有对立关系。"}, {"text": "洗", "is_correct": false, "explanation": "不是反义词：洗表示用水去污，与拆没有对立关系。"}], "correct_answer": "建", "explanations": {"建": "反义词：建指建造，与把建筑拆毁相反。", "吃": "不是反义词：吃指把食物咽下，与拆没有对立关系。", "唱": "不是反义词：唱表示发出歌声，与拆没有对立关系。", "洗": "不是反义词：洗表示用水去污，与拆没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把合在一起的东西打开或毁掉。", "primary_collocate": null, "pronunciation": "chāi", "ipa": "ʈʂʰai̯˥", "syllable_count": 1, "sentences": [{"text": "我拆了信，里面有一张照片。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子急着拆礼物。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座旧桥明年要拆了。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把那间旧房子拆了。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递到了，你先拆一下。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈拆过很多信，这封最重要。", "target_word": "拆", "complexity_tier": "T3", "furigana": "mā ma chāi guo hěn duō xìn，zhè fēng zuì zhòng yào。", "sentence_source": "generated"}, {"text": "这条街的老房子都要拆。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁拆了我的信？", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别拆我的礼物，我想自己打开。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人明天来拆这堵旧墙。", "target_word": "拆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拆了", "label": "体标"}, {"form": "拆过", "label": "体标"}, {"form": "拆开", "label": "复合"}, {"form": "拆除", "label": "复合"}], "register": "口语", "sense_fingerprint": "打开封好的东西，或把建筑拆毁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6906149-0c7e-411f-8ebe-5000e4ee9871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆 chāi：打开封好的东西，或把建筑拆毁。"}, {"text": "柴", "is_correct": false, "explanation": "chái 与 chāi 声调不同，意思是柴火。"}, {"text": "猜", "is_correct": false, "explanation": "cāi 与 chāi 声母不同（c 与 ch），意思是猜测。"}, {"text": "叉", "is_correct": false, "explanation": "chā 与 chāi 韵母不同，意思是叉子。"}, {"text": "灾", "is_correct": false, "explanation": "zāi 与 chāi 声母不同（z 与 ch），意思是灾难。"}], "explanations": {"拆": "拆 chāi：打开封好的东西，或把建筑拆毁。", "柴": "chái 与 chāi 声调不同，意思是柴火。", "猜": "cāi 与 chāi 声母不同（c 与 ch），意思是猜测。", "叉": "chā 与 chāi 韵母不同，意思是叉子。", "灾": "zāi 与 chāi 声母不同（z 与 ch），意思是灾难。"}, "sentence_index": null, "correct_answer": "拆"}, "level_3": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆：打开信封取出信件，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧掉信就看不到里面的照片，与句意矛盾。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不用于信件。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把东西放进嘴里，与信件无关。"}], "explanations": {"拆": "拆：打开信封取出信件，符合句意。", "烧": "语义：烧掉信就看不到里面的照片，与句意矛盾。", "洗": "搭配：“洗”不用于信件。", "吃": "语义：“吃”指把东西放进嘴里，与信件无关。"}, "sentence_index": 0, "correct_answer": "拆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房里拆了一个鸡蛋，放进锅里炒。", "explanation": "这里应该用〈打〉。拆指打开封好的东西或拆毁建筑，打鸡蛋要用打。"}, {"text": "他在院子里拆出一口井。", "explanation": "这里应该用〈挖〉。拆指拆开或拆毁，挖井要用挖。"}, {"text": "她从树上拆下一朵花。", "explanation": "这里应该用〈摘〉。拆指分开整体，从树上采花要用摘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆 chāi：打开封好的东西，或把建筑拆毁。"}, {"text": "筛", "is_correct": false, "explanation": "shāi 与 chāi 声母不同（sh 与 ch），意思是筛子。"}, {"text": "呆", "is_correct": false, "explanation": "dāi 与 chāi 声母不同（d 与 ch），意思是呆板。"}, {"text": "摘", "is_correct": false, "explanation": "zhāi 与 chāi 声母不同（zh 与 ch），意思是摘下。"}], "explanations": {"拆": "拆 chāi：打开封好的东西，或把建筑拆毁。", "筛": "shāi 与 chāi 声母不同（sh 与 ch），意思是筛子。", "呆": "dāi 与 chāi 声母不同（d 与 ch），意思是呆板。", "摘": "zhāi 与 chāi 声母不同（zh 与 ch），意思是摘下。"}, "sentence_index": null, "correct_answer": "拆"}, "level_3": {"options": [{"text": "拆", "is_correct": true, "explanation": "拆：把老房子拆毁，符合“都要……”的句意。"}, {"text": "住", "is_correct": false, "explanation": "搭配：“住”指居住，不能和“都要”接在老房子之后表示拆毁的意思。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，与老房子无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与老房子无关。"}], "explanations": {"拆": "拆：把老房子拆毁，符合“都要……”的句意。", "住": "搭配：“住”指居住，不能和“都要”接在老房子之后表示拆毁的意思。", "喝": "语义：“喝”指饮用，与老房子无关。", "唱": "语义：“唱”指发出歌声，与老房子无关。"}, "sentence_index": 6, "correct_answer": "拆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都拆这盆花。", "explanation": "这里应该用〈浇〉。拆指拆开或拆毁，给花浇水要用浇。"}, {"text": "孩子们在操场上拆球。", "explanation": "这里应该用〈踢〉。拆不能用于球类，踢球要用踢。"}, {"text": "厨房里正在拆水。", "explanation": "这里应该用〈烧〉。拆不能用于水，烧水要用烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拆了开那封信，读了起来。", "corrected_sentence": "他拆开了那封信，读了起来。", "error_description": "“开”是“拆”的结果补语，应说“拆开了”，“了”不能放在“开”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座旧楼上个月已经拆着了。", "corrected_sentence": "这座旧楼上个月已经拆了。", "error_description": "“拆”表示已完成的动作，应用“了”，“着”表示动作持续，不能在这里用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
