INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96546, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自愿拿出钱款以支持公益或救助。", "primary_collocate": null, "pronunciation": "juān kuǎn", "ipa": "tɕyɛn˥ kʰuan˨˩˦", "syllable_count": 2, "sentences": [{"text": "地震后，很多人为灾区捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司向学校捐款一百万元。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在网上为救灾捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校组织学生为贫困地区捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们愿意为公益活动捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水来了，全国人民都在捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以在这里为灾区捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人每年都为山区学校捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定为医院捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为受伤的小动物捐款。", "target_word": "捐款", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捐款了", "label": "体标"}, {"form": "捐了款", "label": "体标"}, {"form": "捐款人", "label": "复合"}], "register": "中性", "sense_fingerprint": "自愿出钱支持公益事业或灾后救助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6906149-0c7e-411f-8ebe-5000e4ee9871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96546, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "捐款", "is_correct": true, "explanation": "正确。“捐款”是为灾区自愿出钱，与“地震后”的语境相合。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：“罚款”是因违规而被处罚交钱，与救灾无关。"}, {"text": "欠款", "is_correct": false, "explanation": "语义：“欠款”是欠别人的钱，不是为灾区出钱。"}, {"text": "赔款", "is_correct": false, "explanation": "语义：“赔款”是因损害而赔偿，地震不是某人造成的损害，不能说“为灾区赔款”。"}], "explanations": {"捐款": "正确。“捐款”是为灾区自愿出钱，与“地震后”的语境相合。", "罚款": "语义：“罚款”是因违规而被处罚交钱，与救灾无关。", "欠款": "语义：“欠款”是欠别人的钱，不是为灾区出钱。", "赔款": "语义：“赔款”是因损害而赔偿，地震不是某人造成的损害，不能说“为灾区赔款”。"}, "sentence_index": 0, "correct_answer": "捐款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校在操场上捐款，请大家来收钱。", "explanation": "这里应该用〈募捐〉。捐款是出钱的一方，向大家征集钱要用募捐。"}, {"text": "他把邻居家的玻璃打碎了，要捐款五十元。", "explanation": "这里应该用〈赔款〉。捐款是自愿给予，因损坏而必须付的钱要用赔款。"}, {"text": "妈妈在超市捐款买了菜。", "explanation": "这里应该用〈付款〉。捐款用于公益，在超市买菜要用付款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "捐款", "is_correct": true, "explanation": "正确。“捐款”是自愿出钱支持灾区，与“你可以在这里”的语境相合。"}, {"text": "罢工", "is_correct": false, "explanation": "配价：“罢工”是不及物动词，不能带“为灾区”这样的受益对象。"}, {"text": "失业", "is_correct": false, "explanation": "配价：“失业”是不及物动词，不能带“为灾区”这样的受益对象。"}, {"text": "休学", "is_correct": false, "explanation": "语义：“休学”是暂停上学，与“为灾区”的帮助意思无关。"}], "explanations": {"捐款": "正确。“捐款”是自愿出钱支持灾区，与“你可以在这里”的语境相合。", "罢工": "配价：“罢工”是不及物动词，不能带“为灾区”这样的受益对象。", "失业": "配价：“失业”是不及物动词，不能带“为灾区”这样的受益对象。", "休学": "语义：“休学”是暂停上学，与“为灾区”的帮助意思无关。"}, "sentence_index": 6, "correct_answer": "捐款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我向银行捐款买了一辆车。", "explanation": "这里应该用〈借款〉。捐款是自愿送给公益的钱，不能用来向银行借钱买车。"}, {"text": "他把积蓄拿去捐款，想赚更多钱。", "explanation": "这里应该用〈投资〉。捐款不是为了赚钱，想赚钱要用投资。"}, {"text": "我昨天往老家的账户上捐款两千元。", "explanation": "这里应该用〈汇款〉。捐款是无偿给公益或救助对象的钱，往家人的账户转钱要用汇款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂给医院捐款五个。", "corrected_sentence": "这家工厂给医院捐款五次。", "error_description": "量词错误：“捐款”计次要用动量词“次”，错误形式“五个”，正确形式“五次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司把灾区捐了款。", "corrected_sentence": "这家公司给灾区捐了款。", "error_description": "介词错误：错误形式“把灾区捐了款”，正确形式“给灾区捐了款”。表示捐给谁要用“给”，不能用“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
