INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96547, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西拿走，或者人离开。", "primary_collocate": null, "pronunciation": "chè", "ipa": "ʈʂʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "吃完饭，服务员来撤盘子。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把桌子上的杯子撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人走了，我们把菜撤下去。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大了，工人们先撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把屋里的椅子都撤了出去。", "target_word": "撤", "complexity_tier": "T3", "furigana": "tā bǎ wūlǐ de yǐzi dōu chè le chūqù。", "sentence_source": "generated"}, {"text": "比赛结束，他们把桌椅都撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火太大，人都往外撤。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先把这些书撤走，桌子太乱了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，大家都撤吧。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员已经把碗撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撤了", "label": "体标"}, {"form": "撤掉", "label": "复合"}, {"form": "撤走", "label": "复合"}, {"form": "撤退", "label": "复合"}], "register": "中性", "sense_fingerprint": "把东西拿走，或人从某处离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6906149-0c7e-411f-8ebe-5000e4ee9871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96547, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "撤", "is_correct": true, "explanation": "正确。“撤”（chè，第四声）意思是把东西拿走或离开。"}, {"text": "车", "is_correct": false, "explanation": "车（chē，第一声）与撤（chè，第四声）声调不同，意思是车辆。"}, {"text": "扯", "is_correct": false, "explanation": "扯（chě，第三声）与撤（chè，第四声）声调不同，意思是拉、扯。"}, {"text": "舍", "is_correct": false, "explanation": "舍（shè）与撤（chè）声母不同（sh 与 ch），意思是房屋或舍弃。"}, {"text": "册", "is_correct": false, "explanation": "册（cè）与撤（chè）声母不同（c 与 ch），意思是书册。"}], "explanations": {"撤": "正确。“撤”（chè，第四声）意思是把东西拿走或离开。", "车": "车（chē，第一声）与撤（chè，第四声）声调不同，意思是车辆。", "扯": "扯（chě，第三声）与撤（chè，第四声）声调不同，意思是拉、扯。", "舍": "舍（shè）与撤（chè）声母不同（sh 与 ch），意思是房屋或舍弃。", "册": "册（cè）与撤（chè）声母不同（c 与 ch），意思是书册。"}, "sentence_index": null, "correct_answer": "撤"}, "level_3": {"options": [{"text": "撤", "is_correct": true, "explanation": "正确。“撤盘子”是把吃完的盘子拿走，与“吃完饭”相合。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是打破，与收拾盘子的意思不符。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能用于盘子。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌，不能用于盘子。"}], "explanations": {"撤": "正确。“撤盘子”是把吃完的盘子拿走，与“吃完饭”相合。", "砸": "语义：“砸”是打破，与收拾盘子的意思不符。", "写": "搭配：“写”的对象是文字，不能用于盘子。", "唱": "搭配：“唱”的对象是歌，不能用于盘子。"}, "sentence_index": 0, "correct_answer": "撤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服务员把菜撤上桌。", "explanation": "这里应该用〈摆〉。撤表示拿走，不能表示把东西放上去。"}, {"text": "他们准备撤去旅游。", "explanation": "这里应该用〈出发〉。撤多指撤退或拿走，一般外出旅游要用出发。"}, {"text": "他把垃圾撤到了桶里。", "explanation": "这里应该用〈扔〉。撤表示拿走，把垃圾放进桶里要用扔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96547, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "撤", "is_correct": true, "explanation": "正确。“撤”（chè，第四声）意思是把东西拿走或离开。"}, {"text": "测", "is_correct": false, "explanation": "测（cè）与撤（chè）声母不同（c 与 ch），意思是测量。"}, {"text": "策", "is_correct": false, "explanation": "策（cè）与撤（chè）声母不同（c 与 ch），意思是计策。"}, {"text": "射", "is_correct": false, "explanation": "射（shè）与撤（chè）声母不同（sh 与 ch），意思是发射。"}, {"text": "设", "is_correct": false, "explanation": "设（shè）与撤（chè）声母不同（sh 与 ch），意思是设置。"}], "explanations": {"撤": "正确。“撤”（chè，第四声）意思是把东西拿走或离开。", "测": "测（cè）与撤（chè）声母不同（c 与 ch），意思是测量。", "策": "策（cè）与撤（chè）声母不同（c 与 ch），意思是计策。", "射": "射（shè）与撤（chè）声母不同（sh 与 ch），意思是发射。", "设": "设（shè）与撤（chè）声母不同（sh 与 ch），意思是设置。"}, "sentence_index": null, "correct_answer": "撤"}, "level_3": {"options": [{"text": "撤", "is_correct": true, "explanation": "正确。“人都往外撤”表示人往外走、撤离，与“火太大”相合。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是燃烧，与人往外走的意思不符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象是食物，不能说人往外煮。"}, {"text": "织", "is_correct": false, "explanation": "搭配：“织”是编织，不能用于人往外走。"}], "explanations": {"撤": "正确。“人都往外撤”表示人往外走、撤离，与“火太大”相合。", "烧": "语义：“烧”是燃烧，与人往外走的意思不符。", "煮": "搭配：“煮”的对象是食物，不能说人往外煮。", "织": "搭配：“织”是编织，不能用于人往外走。"}, "sentence_index": 6, "correct_answer": "撤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员把地板撤干净了。", "explanation": "这里应该用〈擦〉。撤表示拿走或离开，擦地板要用擦。"}, {"text": "他在台上撤了一口气。", "explanation": "这里应该用〈呼〉。撤表示拿走或离开，呼气要用呼。"}, {"text": "他把书撤给了同学。", "explanation": "这里应该用〈送〉。撤表示拿走或离开，不能表示把东西送给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "服务员把菜走撤了。", "corrected_sentence": "服务员把菜撤走了。", "error_description": "补语语序错误：错误形式“走撤了”，正确形式“撤走了”。“撤走”是动补结构，补语“走”要紧跟“撤”，不能放在前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把桌上的书撤了走。", "corrected_sentence": "他把桌上的书撤走了。", "error_description": "补语位置错误：错误形式“撤了走”，正确形式“撤走了”。“撤走”是动补结构，“走”要紧跟“撤”，“了”放在最后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
