INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96548, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "取消；拿掉；向后退走。", "primary_collocate": null, "pronunciation": "chè", "ipa": "ʈʂʰɤ˥˩", "syllable_count": 1, "sentences": [{"text": "公司把他的职务撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理决定撤这个广告。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板撤了他的职。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把这条旧规定撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察慢慢往后撤。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们发现不对，马上撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这条消息撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队今晚就要撤。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家快点往后撤。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站已经把那张图片撤了。", "target_word": "撤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "撤了", "label": "体标"}, {"form": "撤掉", "label": "复合"}, {"form": "撤走", "label": "复合"}, {"form": "撤退", "label": "复合"}], "register": "中性", "sense_fingerprint": "取消职务或内容，或向后退走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6906149-0c7e-411f-8ebe-5000e4ee9871') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96548, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "撤", "is_correct": true, "explanation": "正确。“撤”（chè，第四声）意思是撤走、取消或后退。"}, {"text": "车", "is_correct": false, "explanation": "车（chē，第一声）与撤（chè，第四声）声调不同，意思是车辆。"}, {"text": "扯", "is_correct": false, "explanation": "扯（chě，第三声）与撤（chè，第四声）声调不同，意思是拉、扯。"}, {"text": "舍", "is_correct": false, "explanation": "舍（shè）与撤（chè）声母不同（sh 与 ch），意思是房屋或舍弃。"}, {"text": "册", "is_correct": false, "explanation": "册（cè）与撤（chè）声母不同（c 与 ch），意思是书册。"}], "explanations": {"撤": "正确。“撤”（chè，第四声）意思是撤走、取消或后退。", "车": "车（chē，第一声）与撤（chè，第四声）声调不同，意思是车辆。", "扯": "扯（chě，第三声）与撤（chè，第四声）声调不同，意思是拉、扯。", "舍": "舍（shè）与撤（chè）声母不同（sh 与 ch），意思是房屋或舍弃。", "册": "册（cè）与撤（chè）声母不同（c 与 ch），意思是书册。"}, "sentence_index": null, "correct_answer": "撤"}, "level_3": {"options": [{"text": "撤", "is_correct": true, "explanation": "正确。“撤了”表示取消职务，与“职务”搭配。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”的对象是房屋、器物等具体的东西，“职务”不能拆。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”要挂在某处，不能说“挂了他的职务”。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”是咽下，与取消职务的意思不符。"}], "explanations": {"撤": "正确。“撤了”表示取消职务，与“职务”搭配。", "拆": "搭配：“拆”的对象是房屋、器物等具体的东西，“职务”不能拆。", "挂": "搭配：“挂”要挂在某处，不能说“挂了他的职务”。", "吞": "语义：“吞”是咽下，与取消职务的意思不符。"}, "sentence_index": 0, "correct_answer": "撤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天的会议往后撤了一个小时。", "explanation": "这里应该用〈推迟〉。撤是向后退走或取消，会议延后一小时要用推迟。"}, {"text": "他一直向前撤，走出了房间。", "explanation": "这里应该用〈进〉。撤是向后退，不能说向前撤。"}, {"text": "他的手机突然撤了，只好去买一部新的。", "explanation": "这里应该用〈坏〉。撤表示取消、拿走或后退，不能说手机撤了，手机坏了要说坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96548, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "撤", "is_correct": true, "explanation": "正确。“撤”（chè，第四声）意思是撤走、取消或后退。"}, {"text": "测", "is_correct": false, "explanation": "测（cè）与撤（chè）声母不同（c 与 ch），意思是测量。"}, {"text": "策", "is_correct": false, "explanation": "策（cè）与撤（chè）声母不同（c 与 ch），意思是计策。"}, {"text": "射", "is_correct": false, "explanation": "射（shè）与撤（chè）声母不同（sh 与 ch），意思是发射。"}, {"text": "设", "is_correct": false, "explanation": "设（shè）与撤（chè）声母不同（sh 与 ch），意思是设置。"}], "explanations": {"撤": "正确。“撤”（chè，第四声）意思是撤走、取消或后退。", "测": "测（cè）与撤（chè）声母不同（c 与 ch），意思是测量。", "策": "策（cè）与撤（chè）声母不同（c 与 ch），意思是计策。", "射": "射（shè）与撤（chè）声母不同（sh 与 ch），意思是发射。", "设": "设（shè）与撤（chè）声母不同（sh 与 ch），意思是设置。"}, "sentence_index": null, "correct_answer": "撤"}, "level_3": {"options": [{"text": "撤", "is_correct": true, "explanation": "正确。“撤”表示取消或拿掉消息，与“请把这条消息”相合。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒”用于液体或容器里的东西，“消息”不能倒。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：“扛”要扛着有形的东西，“消息”不能扛。"}, {"text": "叠", "is_correct": false, "explanation": "语义：“叠”是把东西折起来，与取消消息的意思不符。"}], "explanations": {"撤": "正确。“撤”表示取消或拿掉消息，与“请把这条消息”相合。", "倒": "搭配：“倒”用于液体或容器里的东西，“消息”不能倒。", "扛": "搭配：“扛”要扛着有形的东西，“消息”不能扛。", "叠": "语义：“叠”是把东西折起来，与取消消息的意思不符。"}, "sentence_index": 6, "correct_answer": "撤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把钱撤给了希望小学。", "explanation": "这里应该用〈送〉。撤是取消或拿走，不能用来把钱送给别人。"}, {"text": "他向大家撤了一个笑容。", "explanation": "这里应该用〈露〉。撤表示取消或拿掉，露出笑容要用露。"}, {"text": "他把脸撤干净了，然后出门了。", "explanation": "这里应该用〈洗〉。撤表示拿走或取消，洗脸要用洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们慢慢往前撤。", "corrected_sentence": "士兵们慢慢往后撤。", "error_description": "方向错误：错误形式“往前撤”，正确形式“往后撤”。“撤”表示向后退，不能说往前撤。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把旧规定撤了掉。", "corrected_sentence": "他们把旧规定撤掉了。", "error_description": "补语位置错误：错误形式“撤了掉”，正确形式“撤掉了”。“撤掉”是动补结构，“掉”要紧跟动词，之后再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '900a71e9-77ee-4930-ada7-098919563067') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“既有”与“新”相对：既有指原来就有的，新指后来出现的。"}, {"text": "陌生", "is_correct": false, "explanation": "“陌生”指不熟悉，与“既有”的“原已拥有”义没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”指不复杂，与“既有”无反义关系。"}, {"text": "重要", "is_correct": false, "explanation": "“重要”指作用大，与“既有”的意思没有反义关系。"}], "correct_answer": "新", "explanations": {"新": "“既有”与“新”相对：既有指原来就有的，新指后来出现的。", "陌生": "“陌生”指不熟悉，与“既有”的“原已拥有”义没有反义关系。", "简单": "“简单”指不复杂，与“既有”无反义关系。", "重要": "“重要”指作用大，与“既有”的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“既有”与“新”相对：既有指原本就有，新指后来新增的。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音或不吵闹，与“既有”无反义关系。"}, {"text": "方便", "is_correct": false, "explanation": "“方便”指便于做事，与“既有”的意思没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”指不复杂，与“既有”无反义关系。"}], "correct_answer": "新", "explanations": {"新": "“既有”与“新”相对：既有指原本就有，新指后来新增的。", "安静": "“安静”指没有声音或不吵闹，与“既有”无反义关系。", "方便": "“方便”指便于做事，与“既有”的意思没有反义关系。", "简单": "“简单”指不复杂，与“既有”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "已经有了的。", "primary_collocate": null, "pronunciation": "jì yǒu", "ipa": "tɕi˥˩ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们先用既有的材料做这件事。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把既有的问题先解决好。", "target_word": "既有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想放弃既有的成绩。", "target_word": "既有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司想用既有的人手完成工作。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先看看既有的资料。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书只写了既有的研究结果。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，先复习既有的知识，再学新的。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "既有的钱不够，我们还要再借一点。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠着既有的经验，很快找到了办法。", "target_word": "既有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院要在既有的条件下多帮病人。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "已经拥有、现成存在的（材料、资料、条件、经验等），常与新的相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a3d0eb-aa1b-412d-998a-e461b91734c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "既有", "is_correct": true, "explanation": "正确。既有表示原来已经有的，修饰“材料”，符合句意。"}, {"text": "善良", "is_correct": false, "explanation": "语义：材料不能是善良的，“善良”只用于形容人。"}, {"text": "焦急", "is_correct": false, "explanation": "语义：材料没有情绪，“焦急”描述人的心情，不能修饰材料。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰材料。"}], "explanations": {"既有": "正确。既有表示原来已经有的，修饰“材料”，符合句意。", "善良": "语义：材料不能是善良的，“善良”只用于形容人。", "焦急": "语义：材料没有情绪，“焦急”描述人的心情，不能修饰材料。", "清脆": "搭配：“清脆”形容声音，不能修饰材料。"}, "sentence_index": 0, "correct_answer": "既有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司想招既有的人手完成工作。", "explanation": "这里应该用〈新〉。既有指原来就已经有的，招人要找新加入的人，不能招已经在公司的人。"}, {"text": "工厂要设计既有的设备，好尽快投产。", "explanation": "这里应该用〈新〉。设计要的是新的设备，既有指原来就有，不能用于要设计出来的东西。"}, {"text": "他们研制了既有的药，还没有人用过。", "explanation": "这里应该用〈新型〉。研制出来的药还没有人用过，不能说既有，既有指原来就有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "既有", "is_correct": true, "explanation": "正确。复习的是原已学过的知识，既有指原来就有，符合句意。"}, {"text": "全新", "is_correct": false, "explanation": "语义：复习的内容必须是学过的，“全新”的知识无法复习，与“复习”矛盾。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“高兴”描述人的情绪，不修饰“知识”。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“遥远”指空间或时间距离大，不能修饰“知识”，与“复习”的语境不合。"}], "explanations": {"既有": "正确。复习的是原已学过的知识，既有指原来就有，符合句意。", "全新": "语义：复习的内容必须是学过的，“全新”的知识无法复习，与“复习”矛盾。", "高兴": "搭配：“高兴”描述人的情绪，不修饰“知识”。", "遥远": "语义：“遥远”指空间或时间距离大，不能修饰“知识”，与“复习”的语境不合。"}, "sentence_index": 6, "correct_answer": "既有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是我们今天早上刚研发出来的既有产品。", "explanation": "这里应该用〈最新〉。既有指原来就有，今天早上刚研发出来的产品是最新的，不能说既有。"}, {"text": "这个活动是下个月才策划的，已经是既有的安排。", "explanation": "这里应该用〈新近〉。既有指原来就有，下个月才策划的安排是新近的，不能说既有。"}, {"text": "这座楼是去年刚盖的，却是既有的楼。", "explanation": "这里应该用〈崭新〉。既有指原来就有，去年刚盖好的楼是崭新的，不能说既有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们决定沿用既有地方案。", "corrected_sentence": "我们决定沿用既有的方案。", "error_description": "“既有”修饰名词时应用“的”，不能用“地”。应为“沿用既有的方案”，“既有地方案”误用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
