INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96558, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "新", "is_correct": true, "explanation": "“既有”与“新”相对：既有指原本就有，新指后来新增的。"}, {"text": "陌生", "is_correct": false, "explanation": "“陌生”指不熟悉，与“既有”无反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白，与“既有”的意思没有反义关系。"}, {"text": "重要", "is_correct": false, "explanation": "“重要”指作用大，与“既有”无反义关系。"}], "correct_answer": "新", "explanations": {"新": "“既有”与“新”相对：既有指原本就有，新指后来新增的。", "陌生": "“陌生”指不熟悉，与“既有”无反义关系。", "清楚": "“清楚”指明白，与“既有”的意思没有反义关系。", "重要": "“重要”指作用大，与“既有”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
