INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96558, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "原来就有的。", "primary_collocate": null, "pronunciation": "jì yǒu", "ipa": "tɕi˥˩ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "新路修好后，既有的小路还会留着。", "target_word": "既有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新地铁会连上既有的线路。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校在既有的老楼旁边建了新楼。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新规定不会改变既有的做法。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政府决定保留既有的老街。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把新桌子放在既有的桌子旁边。", "target_word": "既有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新公园保留了既有的老树。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的老师没有改变班里既有的习惯。", "target_word": "既有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人先检查既有的水管，再装新的。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新软件可以和既有的系统一起用。", "target_word": "既有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "原本就存在的（制度、设施、做法、习惯等），与后来新增的相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a3d0eb-aa1b-412d-998a-e461b91734c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "既有", "is_correct": true, "explanation": "正确。既有表示原本就有的小路，与“新路”对照，符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：小路不能是聪明的，“聪明”只用于形容人或动物。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的态度，不能修饰小路。"}, {"text": "嫩", "is_correct": false, "explanation": "搭配：“嫩”多用于植物或食物的质地，一般不说嫩的小路。"}], "explanations": {"既有": "正确。既有表示原本就有的小路，与“新路”对照，符合句意。", "聪明": "语义：小路不能是聪明的，“聪明”只用于形容人或动物。", "热情": "语义：“热情”形容人的态度，不能修饰小路。", "嫩": "搭配：“嫩”多用于植物或食物的质地，一般不说嫩的小路。"}, "sentence_index": 0, "correct_answer": "既有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校要建立既有的制度，以改进教学。", "explanation": "这里应该用〈新〉。建立要的是新的制度，既有指原来就有，不能用于建立。"}, {"text": "工厂今天刚建好一条生产线，我们计划引入既有的那条。", "explanation": "这里应该用〈全新〉。既有指原来就有，今天刚建好的生产线应说全新的，不能说既有。"}, {"text": "我们研发既有的机器，帮助员工减少工作量。", "explanation": "这里应该用〈新型〉。研发要的是新型机器，既有指原来就有，研发出来的东西不能说既有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "既有", "is_correct": true, "explanation": "正确。既有表示原来就有的老树，符合“保留”的语境。"}, {"text": "新", "is_correct": false, "explanation": "语义：“新”与“老树”矛盾，保留下来的老树不能说新的。"}, {"text": "愤怒", "is_correct": false, "explanation": "语义：树不会愤怒，“愤怒”只用于形容人的情绪。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰树。"}], "explanations": {"既有": "正确。既有表示原来就有的老树，符合“保留”的语境。", "新": "语义：“新”与“老树”矛盾，保留下来的老树不能说新的。", "愤怒": "语义：树不会愤怒，“愤怒”只用于形容人的情绪。", "清脆": "搭配：“清脆”形容声音，不能修饰树。"}, "sentence_index": 6, "correct_answer": "既有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个系统是上个月刚开发的，却是既有的系统。", "explanation": "这里应该用〈最新〉。既有指原来就有，上个月刚开发的系统是最新的，不能说既有。"}, {"text": "这座桥是今年才通车的，却是既有的桥。", "explanation": "这里应该用〈崭新〉。既有指原来就有，今年才通车的桥是崭新的，不能说既有。"}, {"text": "这条规定是刚刚颁布的，早就是既有的做法了。", "explanation": "这里应该用〈新近〉。既有指原来就有，刚颁布的规定是新近的，不能说早就既有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
