INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有益", "is_correct": true, "explanation": "“有害”与“有益”相对：有害指有坏处，有益指有好处。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音，与“有害”的意思无关。"}, {"text": "顺利", "is_correct": false, "explanation": "“顺利”指进展没有障碍，与“有害”无反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白，与“有害”无反义关系。"}], "correct_answer": "有益", "explanations": {"有益": "“有害”与“有益”相对：有害指有坏处，有益指有好处。", "安静": "“安静”指没有声音，与“有害”的意思无关。", "顺利": "“顺利”指进展没有障碍，与“有害”无反义关系。", "清楚": "“清楚”指明白，与“有害”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有益", "is_correct": true, "explanation": "“有害”与“有益”相对：有害指有坏处，有益指有好处。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”指不复杂，与“有害”无反义关系。"}, {"text": "辛苦", "is_correct": false, "explanation": "“辛苦”指费力或劳累，与“有害”无反义关系。"}, {"text": "新鲜", "is_correct": false, "explanation": "“新鲜”指刚出现或没有变质，与“有害”无反义关系。"}], "correct_answer": "有益", "explanations": {"有益": "“有害”与“有益”相对：有害指有坏处，有益指有好处。", "简单": "“简单”指不复杂，与“有害”无反义关系。", "辛苦": "“辛苦”指费力或劳累，与“有害”无反义关系。", "新鲜": "“新鲜”指刚出现或没有变质，与“有害”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "会让人或东西变坏、受伤。", "primary_collocate": null, "pronunciation": "yǒu hài", "ipa": "joʊ˨˩˦ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "抽烟对身体有害。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种药水对小鱼有害，别倒进河里。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太多糖对牙齿有害。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂的黑烟对空气有害。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种虫子对树有害，要快点处理。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有害的气体会让人头疼。", "target_word": "有害", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "长时间玩手机对眼睛有害。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些有害的东西不能放在孩子身边。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳太大时，晒太久对皮肤有害。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "塑料袋对海里的动物有害。", "target_word": "有害", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "对身体、动植物、空气等造成伤害，使其变坏或受伤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a3d0eb-aa1b-412d-998a-e461b91734c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有害", "is_correct": true, "explanation": "正确。有害指对身体造成伤害，与“抽烟”的危害相符。"}, {"text": "健康", "is_correct": false, "explanation": "语义：抽烟若对身体健康，与“有害”所表达的危害相反，句意不通。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不用来形容对身体的影响。"}, {"text": "强壮", "is_correct": false, "explanation": "语义：抽烟不会让身体强壮，“强壮”与吸烟的危害方向相反。"}], "explanations": {"有害": "正确。有害指对身体造成伤害，与“抽烟”的危害相符。", "健康": "语义：抽烟若对身体健康，与“有害”所表达的危害相反，句意不通。", "甜": "搭配：“甜”形容味道，不用来形容对身体的影响。", "强壮": "语义：抽烟不会让身体强壮，“强壮”与吸烟的危害方向相反。"}, "sentence_index": 0, "correct_answer": "有害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种运动对身体很有害，经常做能增强体质。", "explanation": "这里应该用〈有益〉。有害指造成伤害，对身体有好处应说有益，不能说有害。"}, {"text": "这种方法对学习很有害，成绩提高得很快。", "explanation": "这里应该用〈有利〉。有害指造成伤害，能促进学习、提高成绩应说有利，不能说有害。"}, {"text": "这个方法对提高成绩很有害，老师很推荐。", "explanation": "这里应该用〈有帮助〉。有害指造成伤害，对提高成绩有帮助应说有帮助，不能说有害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有害", "is_correct": true, "explanation": "正确。长时间玩手机会伤害眼睛，有害符合句意。"}, {"text": "凶狠", "is_correct": false, "explanation": "语义：“凶狠”用于形容人的态度，句意不通。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或眼神，“对眼睛明亮”不成立。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”形容气味，不用于形容眼睛。"}], "explanations": {"有害": "正确。长时间玩手机会伤害眼睛，有害符合句意。", "凶狠": "语义：“凶狠”用于形容人的态度，句意不通。", "明亮": "搭配：“明亮”形容光线或眼神，“对眼睛明亮”不成立。", "香": "搭配：“香”形容气味，不用于形容眼睛。"}, "sentence_index": 6, "correct_answer": "有害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药对治疗感冒很有害，吃了两天就好了。", "explanation": "这里应该用〈有效〉。有害指造成伤害；药能治好病应说有效，与“好了”矛盾。"}, {"text": "这个工具对修理机器很有害，所以师傅们每天都用它。", "explanation": "这里应该用〈有用〉。有害指造成伤害，好用的修理工具应说有用，与“每天都用”矛盾。"}, {"text": "这笔资金对项目很有害，因为它帮助项目顺利完成。", "explanation": "这里应该用〈必要〉。有害指造成伤害，资金对项目来说应说必要，不能说有害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种化学品向河水有害。", "corrected_sentence": "这种化学品对河水有害。", "error_description": "“有害”引出的对象应用介词“对”，不能用“向”。应为“对河水有害”，“向河水有害”用错介词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96563, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吸烟向身体非常有害。", "corrected_sentence": "吸烟对身体非常有害。", "error_description": "“有害”引出的对象应用介词“对”，不能用“向”。应为“对身体非常有害”，“向身体非常有害”用错介词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
