INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96571, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大家都玩得很开心的好地方。", "primary_collocate": null, "pronunciation": "lè yuán", "ipa": "lɤ˥˩ yɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个公园是孩子们的乐园。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小河边是小朋友的乐园，大家都爱去。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对爱玩的人来说，海边就是乐园。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草地上有很多小狗，这里是它们的乐园。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末的游泳池成了孩子的乐园。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雪过后，院子成了孩子们的乐园。", "target_word": "乐园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对小朋友来说，奶奶家的院子就是乐园。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他小时候，树林是他和朋友的乐园。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店里玩具很多，是孩子的乐园。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片海滩是小朋友玩沙子的乐园。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "儿童乐园", "label": "复合"}, {"form": "樂園", "label": "繁体"}], "register": "通用", "sense_fingerprint": "比喻义：让人（尤其是孩子）玩得开心的好去处，如孩子的乐园", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a3d0eb-aa1b-412d-998a-e461b91734c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96571, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐园", "is_correct": true, "explanation": "“乐园”指供人玩得开心的好地方，与“这个公园是孩子们的……”的语境相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，公园不是做饭的场所，与句中的“公园”不符。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“公园”是场所，不能说成孩子们的玩具，二者不搭配。"}, {"text": "医院", "is_correct": false, "explanation": "语义：“医院”是看病的地方，公园不是看病的场所，与句意不符。"}], "explanations": {"乐园": "“乐园”指供人玩得开心的好地方，与“这个公园是孩子们的……”的语境相符。", "厨房": "语义：“厨房”是做饭的地方，公园不是做饭的场所，与句中的“公园”不符。", "玩具": "搭配：“公园”是场所，不能说成孩子们的玩具，二者不搭配。", "医院": "语义：“医院”是看病的地方，公园不是看病的场所，与句意不符。"}, "sentence_index": 0, "correct_answer": "乐园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天去乐园借书。", "explanation": "这里应该用〈图书馆〉。乐园是供人玩耍的快乐场所，借书应去图书馆。"}, {"text": "奶奶在乐园里看病，很快就好了。", "explanation": "这里应该用〈医院〉。乐园是游玩的地方，看病要去医院。"}, {"text": "他每天在乐园里做晚饭。", "explanation": "这里应该用〈厨房〉。乐园不是做饭的地方，做晚饭应在厨房进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96571, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐园", "is_correct": true, "explanation": "“乐园”指小朋友玩得开心的地方，与“奶奶家的院子就是……”的句意相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：“银行”是办理金融业务的地方，院子不是银行，与句意不符。"}, {"text": "坟地", "is_correct": false, "explanation": "语义：墓地不是小朋友快乐玩耍的地方，与句子的快乐语气相反。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“奶奶家的院子”是家庭居所，不能说成“工厂”，二者不搭配。"}], "explanations": {"乐园": "“乐园”指小朋友玩得开心的地方，与“奶奶家的院子就是……”的句意相符。", "银行": "语义：“银行”是办理金融业务的地方，院子不是银行，与句意不符。", "坟地": "语义：墓地不是小朋友快乐玩耍的地方，与句子的快乐语气相反。", "工厂": "搭配：“奶奶家的院子”是家庭居所，不能说成“工厂”，二者不搭配。"}, "sentence_index": 6, "correct_answer": "乐园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们每天在乐园里生产零件，很辛苦。", "explanation": "这里应该用〈工厂〉。乐园是供人游玩的快乐场所，生产零件应在工厂进行。"}, {"text": "我下班后去乐园办理银行卡。", "explanation": "这里应该用〈银行〉。乐园是游玩的地方，办理银行卡要去银行。"}, {"text": "汽车在乐园里加油，然后继续上路。", "explanation": "这里应该用〈加油站〉。乐园不是加油的地方，给汽车加油要去加油站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片树林对松鼠来说是一只乐园。", "corrected_sentence": "这片树林对松鼠来说是一座乐园。", "error_description": "量词错误：“乐园”的量词应用“座”，“只”用于小动物等，不能修饰乐园。应改为“一座乐园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条小河是鸭子们乐园。", "corrected_sentence": "那条小河是鸭子们的乐园。", "error_description": "漏词错误：“鸭子们”修饰“乐园”时要加“的”，应说“鸭子们的乐园”，这里漏掉了“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
