INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96572, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "快乐的地方；游乐场所。", "primary_collocate": null, "pronunciation": "lè yuán", "ipa": "lɤ˥˩ yɛn˧˥", "syllable_count": 2, "sentences": [{"text": "周末我们带孩子去乐园玩。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个乐园有很多好玩的游戏。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乐园门口有很多人在买票。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在乐园里坐了三次过山车。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乐园里的小火车很受孩子喜欢。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个乐园晚上七点关门。", "target_word": "乐园", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们坐地铁去乐园，只要二十分钟。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乐园里有吃的，也有玩的。", "target_word": "乐园", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新开的乐园离我家很近。", "target_word": "乐园", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他第一次去乐园，高兴得不想回家。", "target_word": "乐园", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "儿童乐园", "label": "复合"}, {"form": "樂園", "label": "繁体"}], "register": "通用", "sense_fingerprint": "本义：有游戏设施、供人游玩的场所，如游乐园", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a3d0eb-aa1b-412d-998a-e461b91734c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96572, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐园", "is_correct": true, "explanation": "“乐园”指供人游玩的场所，与“周末我们带孩子去……玩”的句意相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理金融业务的地方，不是可以带孩子去游玩的地方。"}, {"text": "监狱", "is_correct": false, "explanation": "语义：监狱不是供人游玩的地方，与“带孩子去玩”的句意不符。"}, {"text": "墓地", "is_correct": false, "explanation": "搭配：“玩”不能与墓地搭配，墓地不是能游玩的场所。"}], "explanations": {"乐园": "“乐园”指供人游玩的场所，与“周末我们带孩子去……玩”的句意相符。", "银行": "语义：银行是办理金融业务的地方，不是可以带孩子去游玩的地方。", "监狱": "语义：监狱不是供人游玩的地方，与“带孩子去玩”的句意不符。", "墓地": "搭配：“玩”不能与墓地搭配，墓地不是能游玩的场所。"}, "sentence_index": 0, "correct_answer": "乐园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在乐园里看病。", "explanation": "这里应该用〈医院〉。乐园是供人游玩的场所，看病应去医院。"}, {"text": "我们每天去乐园买菜。", "explanation": "这里应该用〈超市〉。乐园是游玩的地方，买菜应去超市。"}, {"text": "工人在乐园里生产汽车。", "explanation": "这里应该用〈工厂〉。乐园不是生产场所，生产汽车应在工厂进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96572, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐园", "is_correct": true, "explanation": "“乐园”是供人游玩的场所，可以作为坐地铁前往的目的地，与句意相符。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“去”后接的应是地点，“玩具”是物品，不能作为坐地铁前往的目的地。"}, {"text": "炉子", "is_correct": false, "explanation": "语义：炉子是做饭取暖的设备，不是可以乘地铁前往的地方。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是穿在脚上的东西，不能作为坐地铁前往的地点。"}], "explanations": {"乐园": "“乐园”是供人游玩的场所，可以作为坐地铁前往的目的地，与句意相符。", "玩具": "搭配：“去”后接的应是地点，“玩具”是物品，不能作为坐地铁前往的目的地。", "炉子": "语义：炉子是做饭取暖的设备，不是可以乘地铁前往的地方。", "鞋子": "语义：鞋子是穿在脚上的东西，不能作为坐地铁前往的地点。"}, "sentence_index": 6, "correct_answer": "乐园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下班后去乐园办理银行卡。", "explanation": "这里应该用〈银行〉。乐园是游玩的地方，办理银行卡要去银行。"}, {"text": "汽车在乐园里加油，然后继续上路。", "explanation": "这里应该用〈加油站〉。乐园不是加油的地方，给汽车加油要去加油站。"}, {"text": "我今天去乐园寄了一个包裹。", "explanation": "这里应该用〈邮局〉。乐园是游玩的地方，寄包裹要去邮局。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96572, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暑假我和朋友一起去了一只乐园。", "corrected_sentence": "暑假我和朋友一起去了一座乐园。", "error_description": "量词错误：“乐园”的量词应用“座”，“只”不能修饰乐园。应改为“一座乐园”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们乐园里玩得很开心。", "corrected_sentence": "孩子们在乐园里玩得很开心。", "error_description": "漏词错误：表示地点的“乐园里”前要加介词“在”，应说“在乐园里玩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有意思", "is_correct": true, "explanation": "“有意思”与“没有意思”构成反义，表示好玩、有趣。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”与“没有意思”无反义关系，指事情繁多或难懂。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”与“没有意思”无反义关系，指明白、分明。"}, {"text": "坚硬", "is_correct": false, "explanation": "“坚硬”与“没有意思”无反义关系，指质地硬。"}], "correct_answer": "有意思", "explanations": {"有意思": "“有意思”与“没有意思”构成反义，表示好玩、有趣。", "复杂": "“复杂”与“没有意思”无反义关系，指事情繁多或难懂。", "清楚": "“清楚”与“没有意思”无反义关系，指明白、分明。", "坚硬": "“坚硬”与“没有意思”无反义关系，指质地硬。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有意思", "is_correct": true, "explanation": "“有意思”与“没有意思”构成反义，表示好玩、有趣。"}, {"text": "陡峭", "is_correct": false, "explanation": "“陡峭”与“没有意思”无反义关系，指坡度很大。"}, {"text": "沉重", "is_correct": false, "explanation": "“沉重”与“没有意思”无反义关系，指重量大或心情压抑。"}, {"text": "潮湿", "is_correct": false, "explanation": "“潮湿”与“没有意思”无反义关系，指含水分多。"}], "correct_answer": "有意思", "explanations": {"有意思": "“有意思”与“没有意思”构成反义，表示好玩、有趣。", "陡峭": "“陡峭”与“没有意思”无反义关系，指坡度很大。", "沉重": "“沉重”与“没有意思”无反义关系，指重量大或心情压抑。", "潮湿": "“潮湿”与“没有意思”无反义关系，指含水分多。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不好玩，让人觉得没趣。", "primary_collocate": null, "pronunciation": "méi yǒu yì si", "ipa": "meɪ˧˥ joʊ˨˩ i˥˩ sɹ̩", "syllable_count": 4, "sentences": [{"text": "这个游戏太没有意思了。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我觉得这部电影没有意思。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人在家玩，真没有意思。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书没有意思，我不想看。", "target_word": "没有意思", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天的足球比赛没有意思，没人看。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们都走了，我一个人觉得没有意思。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看了一个小时电视，越看越没有意思。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课太长了，大家都觉得没有意思。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个节目没有意思，我关电视了。", "target_word": "没有意思", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的笑话一点也没有意思。", "target_word": "没有意思", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不好玩、让人觉得无聊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06053499-ed7b-46b4-88c1-4bffbe9831f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没有意思", "is_correct": true, "explanation": "“没有意思”表示不好玩，与“太……了”搭配，评价游戏，句意通顺。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体型，游戏不说高大。"}, {"text": "烫", "is_correct": false, "explanation": "语义：“烫”指温度高，游戏不能说烫。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，游戏不能用咸来形容。"}], "explanations": {"没有意思": "“没有意思”表示不好玩，与“太……了”搭配，评价游戏，句意通顺。", "高大": "体貌：“高大”形容人或物的体型，游戏不说高大。", "烫": "语义：“烫”指温度高，游戏不能说烫。", "咸": "语义：“咸”指味道，游戏不能用咸来形容。"}, "sentence_index": 0, "correct_answer": "没有意思"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜很没有意思，我一口都没吃。", "explanation": "这里应该用〈没味道〉。“没有意思”说活动、节目等无趣，不用来形容菜的滋味。"}, {"text": "他这次考试的成绩很没有意思。", "explanation": "这里应该用〈不理想〉。“没有意思”评价活动或事情的趣味，不用来评价成绩的好坏。"}, {"text": "我今天身体没有意思，不想出门。", "explanation": "这里应该用〈没劲〉。“没劲”形容身体无力，“没有意思”只评价活动或事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没有意思", "is_correct": true, "explanation": "“没有意思”表示不好玩，与“越看越”搭配，说的是看电视的感受，句意通顺。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容人或物的高度，电视不会越看越矮。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”形容形状，与“越看越”的感受无关。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”形容物体的厚度，看电视不会越看越厚。"}], "explanations": {"没有意思": "“没有意思”表示不好玩，与“越看越”搭配，说的是看电视的感受，句意通顺。", "矮": "体貌：“矮”形容人或物的高度，电视不会越看越矮。", "圆": "语义：“圆”形容形状，与“越看越”的感受无关。", "厚": "语义：“厚”形容物体的厚度，看电视不会越看越厚。"}, "sentence_index": 6, "correct_answer": "没有意思"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被当众批评，觉得很没有意思。", "explanation": "这里应该用〈没面子〉。“没有意思”说事情无趣，不用来形容被批评后的难堪。"}, {"text": "我的手机没有意思，已经送人了。", "explanation": "这里应该用〈没用〉。“没有意思”评价活动或作品的趣味，手机失去功能应说“没用”。"}, {"text": "他最近很忙，没有意思吃饭。", "explanation": "这里应该用〈没心思〉。“没有意思”说事情或活动无趣，不用来说人的心思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我觉得这部片子没有意思很，就走了。", "corrected_sentence": "我觉得这部片子没有意思，就走了。", "error_description": "错误：程度副词“很”放在了形容词“没有意思”后面，程度副词要放在形容词前。正确：应删去“很”，说“我觉得这部片子没有意思，就走了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96577, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天看了一场没有意思地演出，观众都走了。", "corrected_sentence": "我昨天看了一场没有意思的演出，观众都走了。", "error_description": "错误：“地”用在名词“演出”前，应为结构助词“的”。正确：修饰名词要用“的”，应为“没有意思的演出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a704dd41-623e-44e9-8b48-d1a704de2e07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
