INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96589, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "慢慢变小，最后没有了。", "primary_collocate": null, "pronunciation": "xiāo", "ipa": "ɕjau̯˥", "syllable_count": 1, "sentences": [{"text": "过了两天，脚上的肿慢慢消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停以后，水慢慢消下去了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳出来，路上的雪消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的气过一会儿就消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，药吃完肿就会消。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天亮了，我的担心才慢慢消。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脸上的红印还没消。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药吃了以后，热也慢慢消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药，嗓子的痛一点一点消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间长了，他心里的难过也就消了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消了", "label": "体标"}, {"form": "消下去", "label": "复合"}], "register": "中性", "sense_fingerprint": "肿、气、痛等慢慢变小直到没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a3d0eb-aa1b-412d-998a-e461b91734c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96589, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "消", "is_correct": true, "explanation": "目标词，读 xiāo（第一声），意思是慢慢变小直到没有。"}, {"text": "小", "is_correct": false, "explanation": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是小。"}, {"text": "笑", "is_correct": false, "explanation": "xiào（第四声）与 xiāo（第一声）声调不同，意思是笑。"}, {"text": "香", "is_correct": false, "explanation": "xiāng 与 xiāo 韵母不同（ang / ao），声调相同，意思是香。"}, {"text": "修", "is_correct": false, "explanation": "xiū 与 xiāo 韵母不同（iu / ao），声调相同，意思是修理。"}], "explanations": {"消": "目标词，读 xiāo（第一声），意思是慢慢变小直到没有。", "小": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是小。", "笑": "xiào（第四声）与 xiāo（第一声）声调不同，意思是笑。", "香": "xiāng 与 xiāo 韵母不同（ang / ao），声调相同，意思是香。", "修": "xiū 与 xiāo 韵母不同（iu / ao），声调相同，意思是修理。"}, "sentence_index": null, "correct_answer": "消"}, "level_3": {"options": [{"text": "消", "is_correct": true, "explanation": "“消”表示肿慢慢变小直到没有，与“脚上的肿慢慢……了”相符。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指写字，肿不能被写，与句意不符。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”要接可以穿戴的东西，不能与“肿”搭配。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”指说话，肿不能用说话的方式消失，与句意不符。"}], "explanations": {"消": "“消”表示肿慢慢变小直到没有，与“脚上的肿慢慢……了”相符。", "写": "语义：“写”指写字，肿不能被写，与句意不符。", "戴": "搭配：“戴”要接可以穿戴的东西，不能与“肿”搭配。", "说": "语义：“说”指说话，肿不能用说话的方式消失，与句意不符。"}, "sentence_index": 0, "correct_answer": "消"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察很快就消了这伙坏人。", "explanation": "这里应该用〈消灭〉。此处是人为歼灭坏人，“消”单用不表示这一意思，应用双音节“消灭”。"}, {"text": "他把钱消在了箱子里。", "explanation": "这里应该用〈藏〉。“消”表示慢慢变小直到没有，不表示把东西收起来，“藏”才是这个意思。"}, {"text": "农民用药水消了田里的害虫。", "explanation": "这里应该用〈消灭〉。用药杀死害虫要说“消灭”，“消”单用不表示这一意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96589, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "消", "is_correct": true, "explanation": "目标词，读 xiāo（第一声），意思是慢慢变小直到没有。"}, {"text": "效", "is_correct": false, "explanation": "xiào（第四声）与 xiāo（第一声）声调不同，意思是效果。"}, {"text": "休", "is_correct": false, "explanation": "xiū 与 xiāo 韵母不同（iu / ao），声调相同，意思是休息。"}, {"text": "乡", "is_correct": false, "explanation": "xiāng 与 xiāo 韵母不同（ang / ao），声调相同，意思是乡村。"}, {"text": "晓", "is_correct": false, "explanation": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是知道、懂得。"}], "explanations": {"消": "目标词，读 xiāo（第一声），意思是慢慢变小直到没有。", "效": "xiào（第四声）与 xiāo（第一声）声调不同，意思是效果。", "休": "xiū 与 xiāo 韵母不同（iu / ao），声调相同，意思是休息。", "乡": "xiāng 与 xiāo 韵母不同（ang / ao），声调相同，意思是乡村。", "晓": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是知道、懂得。"}, "sentence_index": null, "correct_answer": "消"}, "level_3": {"options": [{"text": "消", "is_correct": true, "explanation": "“消”表示红印慢慢变淡直到没有，与“脸上的红印还没……”相符。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指发光或明亮，红印不能用“亮”来描述消失的过程。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”要接衣物等，不能与“红印”搭配。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指用气流推动，红印不能被吹掉，与句意不符。"}], "explanations": {"消": "“消”表示红印慢慢变淡直到没有，与“脸上的红印还没……”相符。", "亮": "语义：“亮”指发光或明亮，红印不能用“亮”来描述消失的过程。", "穿": "搭配：“穿”要接衣物等，不能与“红印”搭配。", "吹": "语义：“吹”指用气流推动，红印不能被吹掉，与句意不符。"}, "sentence_index": 6, "correct_answer": "消"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生很快就消了这种病毒。", "explanation": "这里应该用〈消灭〉。病毒被彻底杀死要说“消灭”，“消”单用不表示这一意思。"}, {"text": "他用湿布消了桌子上的灰。", "explanation": "这里应该用〈擦〉。用湿布去掉灰尘是擦拭的动作，“消”单用不表示这一意思，应说“擦”。"}, {"text": "厨房的蟑螂被他一晚上消了。", "explanation": "这里应该用〈消灭〉。蟑螂被杀死要说“消灭”，“消”单用不表示这一意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96589, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "第二天，他脸上的肿就消起来了。", "corrected_sentence": "第二天，他脸上的肿就消下去了。", "error_description": "补语错误：“消”表示慢慢减少直至没有，应接“下去”，不能接“起来”。应改为“消下去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96589, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的伤口还没完全消了。", "corrected_sentence": "他的伤口还没完全消。", "error_description": "体标错误：“没”表示尚未发生，与“了”不能同用，应去掉“了”，说“还没完全消”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
