INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96590, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使减少或除去。", "primary_collocate": null, "pronunciation": "xiāo", "ipa": "ɕjau̯˥", "syllable_count": 1, "sentences": [{"text": "喝杯茶，消消气吧。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭后走一走，可以消消食。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用冰敷一下，能消消肿。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点钱消不了他的怒气。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的话消了我心里的火。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃点冰的东西，能消一消嗓子的痛。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯凉茶能消一消暑气。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的怒火一时消不了。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡一觉，能消一消身上的疲劳。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑了笑，就消了我心里的气。", "target_word": "消", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消了", "label": "体标"}, {"form": "消消", "label": "重叠"}], "register": "中性", "sense_fingerprint": "使气、肿、食等减少或除去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a3d0eb-aa1b-412d-998a-e461b91734c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96590, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "消", "is_correct": true, "explanation": "目标词，读 xiāo（第一声），意思是使减少或除去。"}, {"text": "小", "is_correct": false, "explanation": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是小。"}, {"text": "笑", "is_correct": false, "explanation": "xiào（第四声）与 xiāo（第一声）声调不同，意思是笑。"}, {"text": "香", "is_correct": false, "explanation": "xiāng 与 xiāo 韵母不同（ang / ao），声调相同，意思是香。"}, {"text": "修", "is_correct": false, "explanation": "xiū 与 xiāo 韵母不同（iu / ao），声调相同，意思是修理。"}], "explanations": {"消": "目标词，读 xiāo（第一声），意思是使减少或除去。", "小": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是小。", "笑": "xiào（第四声）与 xiāo（第一声）声调不同，意思是笑。", "香": "xiāng 与 xiāo 韵母不同（ang / ao），声调相同，意思是香。", "修": "xiū 与 xiāo 韵母不同（iu / ao），声调相同，意思是修理。"}, "sentence_index": null, "correct_answer": "消"}, "level_3": {"options": [{"text": "消", "is_correct": true, "explanation": "“消消气”是重叠形式，第一个“消”为动词，表示减去怒气，与句意相符。"}, {"text": "散", "is_correct": false, "explanation": "语义：“散”指分开、散开，“散消气”不通，与“消气”的意思不符。"}, {"text": "放", "is_correct": false, "explanation": "搭配：“放”不能带“消气”这样的动宾结构，不能说“放消气”。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，与平息怒气无关，句子说的是喝茶消气。"}], "explanations": {"消": "“消消气”是重叠形式，第一个“消”为动词，表示减去怒气，与句意相符。", "散": "语义：“散”指分开、散开，“散消气”不通，与“消气”的意思不符。", "放": "搭配：“放”不能带“消气”这样的动宾结构，不能说“放消气”。", "写": "语义：“写”指书写，与平息怒气无关，句子说的是喝茶消气。"}, "sentence_index": 0, "correct_answer": "消"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在饭店消了一把伞。", "explanation": "这里应该用〈借〉。“消”不表示借出，借伞要用“借”。"}, {"text": "他把旧书消在了桌子底下。", "explanation": "这里应该用〈放〉。“消”表示使减少或除去，不表示把东西放到某处，“放”才是这个意思。"}, {"text": "他把桌子消到了客厅。", "explanation": "这里应该用〈搬〉。“消”不表示搬运，把桌子挪到别处要用“搬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96590, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "消", "is_correct": true, "explanation": "目标词，读 xiāo（第一声），意思是使减少或除去。"}, {"text": "效", "is_correct": false, "explanation": "xiào（第四声）与 xiāo（第一声）声调不同，意思是效果。"}, {"text": "休", "is_correct": false, "explanation": "xiū 与 xiāo 韵母不同（iu / ao），声调相同，意思是休息。"}, {"text": "乡", "is_correct": false, "explanation": "xiāng 与 xiāo 韵母不同（ang / ao），声调相同，意思是乡村。"}, {"text": "晓", "is_correct": false, "explanation": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是知道、懂得。"}], "explanations": {"消": "目标词，读 xiāo（第一声），意思是使减少或除去。", "效": "xiào（第四声）与 xiāo（第一声）声调不同，意思是效果。", "休": "xiū 与 xiāo 韵母不同（iu / ao），声调相同，意思是休息。", "乡": "xiāng 与 xiāo 韵母不同（ang / ao），声调相同，意思是乡村。", "晓": "xiǎo（第三声）与 xiāo（第一声）声调不同，意思是知道、懂得。"}, "sentence_index": null, "correct_answer": "消"}, "level_3": {"options": [{"text": "消", "is_correct": true, "explanation": "“消一消”是重叠形式，第一个“消”为动词，表示去掉暑气，与句意相符。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”要接可以穿戴的东西，不能说“戴暑气”。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”指说话，与去除暑气无关，句意不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”要接衣物等，不能说“穿暑气”，二者不搭配。"}], "explanations": {"消": "“消一消”是重叠形式，第一个“消”为动词，表示去掉暑气，与句意相符。", "戴": "搭配：“戴”要接可以穿戴的东西，不能说“戴暑气”。", "说": "语义：“说”指说话，与去除暑气无关，句意不通。", "穿": "搭配：“穿”要接衣物等，不能说“穿暑气”，二者不搭配。"}, "sentence_index": 6, "correct_answer": "消"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天消了一件新衣服出门。", "explanation": "这里应该用〈穿〉。“消”不表示穿戴衣物，“穿”才是这个意思。"}, {"text": "他去超市消了一台冰箱。", "explanation": "这里应该用〈买〉。“消”不表示购买，买冰箱要用“买”。"}, {"text": "他在抽屉里消了那把钥匙。", "explanation": "这里应该用〈找〉。“消”不表示寻找，找到钥匙要用“找”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她喝了口水，才把心里的火消起来。", "corrected_sentence": "她喝了口水，才把心里的火消下去。", "error_description": "补语错误：“消”表示使火气减少直至除去，应接“下去”，不能接“起来”。应改为“消下去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他心里的怨气还没消了。", "corrected_sentence": "他心里的怨气还没消。", "error_description": "体标错误：“没”表示尚未发生，与“了”不能同用，应去掉“了”，说“还没消”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
