INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96653, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让马慢慢往前走。", "primary_collocate": null, "pronunciation": "zǒu mǎ", "ipa": "tsou̯˨˩ ma˨˩", "syllable_count": 2, "sentences": [{"text": "他牵着马，在河边慢慢走马。", "target_word": "走马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地很软，我们可以走马。", "target_word": "走马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，他先在场上走马一圈。", "target_word": "走马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每天早上在草原上走马。", "target_word": "走马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太热，我们别跑了，走马吧。", "target_word": "走马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在院子里走马，让马休息一下。", "target_word": "走马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时常在山路上走马。", "target_word": "走马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先走马，再小跑，马才不会累。", "target_word": "走马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看着牧人在湖边走马。", "target_word": "走马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路不平，他只好慢慢走马。", "target_word": "走马", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "骑手让马缓步前行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a3d0eb-aa1b-412d-998a-e461b91734c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96653, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走马", "is_correct": true, "explanation": "走马：牵着马慢慢往前走，与“牵着马”“慢慢”相符。"}, {"text": "骑马", "is_correct": false, "explanation": "语义：“牵着马”说明人在马旁边走，骑马则人在马背上，与上句矛盾。"}, {"text": "跑马", "is_correct": false, "explanation": "搭配：“慢慢”与“跑”不搭配，跑马是快速奔跑，不能慢慢跑马。"}, {"text": "赛马", "is_correct": false, "explanation": "语义：赛马是竞技比赛，与“在河边慢慢”的悠闲场景不符。"}], "explanations": {"走马": "走马：牵着马慢慢往前走，与“牵着马”“慢慢”相符。", "骑马": "语义：“牵着马”说明人在马旁边走，骑马则人在马背上，与上句矛盾。", "跑马": "搭配：“慢慢”与“跑”不搭配，跑马是快速奔跑，不能慢慢跑马。", "赛马": "语义：赛马是竞技比赛，与“在河边慢慢”的悠闲场景不符。"}, "sentence_index": 0, "correct_answer": "走马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们催马快跑，兴奋地走马。", "explanation": "这里应该用〈跑马〉。走马指牵着马慢慢往前走，与“催马快跑”矛盾。"}, {"text": "他一声吆喝，我们便走马冲过了草原。", "explanation": "这里应该用〈飞驰〉。走马是慢慢牵马而行，与“冲过了草原”的急速奔跑矛盾。"}, {"text": "骏马在草原上走马，四蹄生风，眨眼间就消失在远方。", "explanation": "这里应该用〈奔驰〉。走马是慢慢牵马而行，与“四蹄生风、眨眼间消失”的急速奔跑矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96653, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走马", "is_correct": true, "explanation": "走马：牵马慢慢而行，与“山路上”“常”的生活场景相符。"}, {"text": "上网", "is_correct": false, "explanation": "语义：年轻时的山路上没有网络，“上网”与语境不符。"}, {"text": "冲浪", "is_correct": false, "explanation": "语义：冲浪需要海浪，山路上不可能进行，与语境矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：游泳需要水域，不说“在山路上游泳”。"}], "explanations": {"走马": "走马：牵马慢慢而行，与“山路上”“常”的生活场景相符。", "上网": "语义：年轻时的山路上没有网络，“上网”与语境不符。", "冲浪": "语义：冲浪需要海浪，山路上不可能进行，与语境矛盾。", "游泳": "搭配：游泳需要水域，不说“在山路上游泳”。"}, "sentence_index": 6, "correct_answer": "走马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "马受惊了，他在路上走马，飞快地追了过去。", "explanation": "这里应该用〈飞奔〉。走马是慢慢而行，与“飞快地追”矛盾。"}, {"text": "骑兵一声号令，纷纷走马扬蹄冲向敌阵，尘土飞扬。", "explanation": "这里应该用〈疾驰〉。走马是慢慢而行，与“扬蹄冲向敌阵、尘土飞扬”的急速冲锋矛盾。"}, {"text": "他一拍马背，骏马便走马狂奔而去。", "explanation": "这里应该用〈驰骋〉。走马是慢慢而行，与“狂奔而去”的急速不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96653, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在河边飞快地走马，马很听话。", "corrected_sentence": "他在河边慢慢走马，马很听话。", "error_description": "错误：飞快地走马；正确：慢慢走马。走马指牵着马慢慢而行，不能用“飞快地”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96653, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在山路上急急地走马，马很稳。", "corrected_sentence": "他在山路上慢慢走马，马很稳。", "error_description": "错误：急急地走马；正确：慢慢走马。走马指牵马慢慢而行，不能用“急急地”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
