INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96661, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96661, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "比平常的东西小很多，很小巧。", "primary_collocate": null, "pronunciation": "mí nǐ", "ipa": "mi˧˥ ni˨˩", "syllable_count": 2, "sentences": [{"text": "这只小狗很迷你，才一斤重。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子太迷你了，只能装一口水。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的厨房非常迷你。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这个蛋糕多迷你啊！", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子很迷你，大人坐不下。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的手机比我的迷你多了。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间虽然迷你，但是很干净。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猫长得特别迷你。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩具店里的小火车都很迷你。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盆花迷你得像一颗糖。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迷你型", "label": "复合"}], "register": "口语", "sense_fingerprint": "比平常小很多、小巧（作谓语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a3d0eb-aa1b-412d-998a-e461b91734c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96661, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迷你", "is_correct": true, "explanation": "迷你：比平常小很多，与“才一斤重”相符。"}, {"text": "肥胖", "is_correct": false, "explanation": "语义：肥胖说明体形大，与“才一斤重”矛盾。"}, {"text": "庞大", "is_correct": false, "explanation": "语义：庞大说明体积很大，与“才一斤重”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：高大用于形容身材，不用于形容才一斤重的小狗。"}], "explanations": {"迷你": "迷你：比平常小很多，与“才一斤重”相符。", "肥胖": "语义：肥胖说明体形大，与“才一斤重”矛盾。", "庞大": "语义：庞大说明体积很大，与“才一斤重”矛盾。", "高大": "体貌：高大用于形容身材，不用于形容才一斤重的小狗。"}, "sentence_index": 0, "correct_answer": "迷你"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你看，这头大象多迷你啊！", "explanation": "这里应该用〈庞大〉。迷你是比平常小很多的意思，与大象的体型矛盾。"}, {"text": "你看，这片大海多迷你啊！", "explanation": "这里应该用〈浩瀚〉。迷你是比平常小很多的意思，与大海的广阔相反。"}, {"text": "你看，这座摩天大楼多迷你啊！", "explanation": "这里应该用〈高耸〉。迷你是比平常小很多的意思，与摩天大楼的高大不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96661, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迷你", "is_correct": true, "explanation": "迷你：很小，与“虽然……但是很干净”的转折相符。"}, {"text": "脏乱", "is_correct": false, "explanation": "语义：脏乱与“很干净”相反，不能构成转折。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”形容分量，不能用来形容房间的大小或状态。"}, {"text": "饥饿", "is_correct": false, "explanation": "搭配：“饥饿”形容人的感受，不能用来形容房间。"}], "explanations": {"迷你": "迷你：很小，与“虽然……但是很干净”的转折相符。", "脏乱": "语义：脏乱与“很干净”相反，不能构成转折。", "沉重": "语义：“沉重”形容分量，不能用来形容房间的大小或状态。", "饥饿": "搭配：“饥饿”形容人的感受，不能用来形容房间。"}, "sentence_index": 6, "correct_answer": "迷你"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那棵大树很迷你，枝叶遮住了半个天空。", "explanation": "这里应该用〈高大〉。迷你是比平常小很多的意思，与“枝叶遮住了半个天空”的高大矛盾。"}, {"text": "这块石头很迷你，压得他抬不起头。", "explanation": "这里应该用〈巨大〉。迷你是很小的意思，与“压得他抬不起头”矛盾。"}, {"text": "草原迷你无边，牛羊成群。", "explanation": "这里应该用〈广阔〉。迷你是很小的意思，与“无边”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只仓鼠非常很迷你，手掌就能托住。", "corrected_sentence": "这只仓鼠很迷你，手掌就能托住。", "error_description": "错误：非常很迷你；正确：很迷你。两个程度副词不能叠用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盆仙人掌长地很迷你，适合放在书桌上。", "corrected_sentence": "这盆仙人掌长得很迷你，适合放在书桌上。", "error_description": "错误：长地很迷你；正确：长得很迷你。“长”后接补语须用“得”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
