INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96662, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "小型的；袖珍的。", "primary_collocate": null, "pronunciation": "mí nǐ", "ipa": "mi˧˥ ni˨˩", "syllable_count": 2, "sentences": [{"text": "他买了一台全新的迷你风扇。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个迷你音箱，能放进口袋。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店房间里有一台迷你冰箱。", "target_word": "迷你", "complexity_tier": "T3", "furigana": "jiǔ diàn fáng jiān lǐ yǒu yì tái mí nǐ bīng xiāng", "sentence_source": "generated"}, {"text": "她给女儿买了一条迷你裙。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一台迷你电脑。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种迷你相机很方便带着。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在家里种了一个迷你花园。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送了我一辆迷你汽车。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迷你书只有手掌那么大。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，我带了迷你洗发水。", "target_word": "迷你", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迷你裙", "label": "复合"}, {"form": "迷你风扇", "label": "复合"}], "register": "口语", "sense_fingerprint": "小型的、袖珍的（修饰物品）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48a3d0eb-aa1b-412d-998a-e461b91734c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迷你", "is_correct": true, "explanation": "迷你：小型的，与“买了一台”“风扇”相符。"}, {"text": "破旧", "is_correct": false, "explanation": "语义：“买了”的东西通常是新的，与“破旧”矛盾。"}, {"text": "报废", "is_correct": false, "explanation": "搭配：“报废”的东西不能说“买了一台”。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：陈旧表示用了很久，与刚买的语境矛盾。"}], "explanations": {"迷你": "迷你：小型的，与“买了一台”“风扇”相符。", "破旧": "语义：“买了”的东西通常是新的，与“破旧”矛盾。", "报废": "搭配：“报废”的东西不能说“买了一台”。", "陈旧": "语义：陈旧表示用了很久，与刚买的语境矛盾。"}, "sentence_index": 0, "correct_answer": "迷你"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座迷你大楼共有一百层，俯瞰全城。", "explanation": "这里应该用〈高耸〉。迷你是小型的意思，与“一百层、俯瞰全城”的高大不符。"}, {"text": "这架迷你客机能载三百名乘客。", "explanation": "这里应该用〈大型〉。迷你是小型的意思，与“能载三百名乘客”的规模矛盾。"}, {"text": "这个迷你城市人口超过一千万。", "explanation": "这里应该用〈庞大〉。迷你是小型的意思，与“人口超过一千万”的规模矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迷你", "is_correct": true, "explanation": "迷你：小型的，与“在家里种”的小花园相符。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：遥远指距离远，与“在家里”矛盾。"}, {"text": "公共", "is_correct": false, "explanation": "语义：家里的花园不是公共的，与“在家里”矛盾。"}, {"text": "荒芜", "is_correct": false, "explanation": "搭配：“荒芜”形容土地、景色，与“种了”不搭配。"}], "explanations": {"迷你": "迷你：小型的，与“在家里种”的小花园相符。", "遥远": "语义：遥远指距离远，与“在家里”矛盾。", "公共": "语义：家里的花园不是公共的，与“在家里”矛盾。", "荒芜": "搭配：“荒芜”形容土地、景色，与“种了”不搭配。"}, "sentence_index": 6, "correct_answer": "迷你"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那棵树很迷你，遮住了整个院子。", "explanation": "这里应该用〈高大〉。迷你是小型的意思，与“遮住了整个院子”矛盾。"}, {"text": "这条迷你河蜿蜒流淌了三百公里，灌溉了两岸的农田。", "explanation": "这里应该用〈绵长〉。迷你是小型的意思，与“蜿蜒流淌了三百公里”的漫长不符。"}, {"text": "这座迷你山脉连绵千里，横贯整个大陆。", "explanation": "这里应该用〈绵延〉。迷你是小型的意思，与“连绵千里、横贯大陆”的广阔不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹送我一条迷你音箱，很实用。", "corrected_sentence": "妹妹送我一台迷你音箱，很实用。", "error_description": "错误：一条迷你音箱；正确：一台迷你音箱。“条”用于细长的东西，不能用于“音箱”，应用量词“台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈在厨房里买了一台迷你了烤箱。", "corrected_sentence": "妈妈在厨房里买了一台迷你烤箱。", "error_description": "错误：迷你了烤箱；正确：迷你烤箱。“了”不能插在修饰语和名词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4488e1fa-8956-4911-b3ff-96f03def3fa5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
