INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96670, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指病症等持续发展、逐渐加重的性质。", "primary_collocate": null, "pronunciation": "jìn xíng xìng", "ipa": "t͡ɕin˥˩ ɕiŋ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种病的进行性很明显，症状会一直加重。", "target_word": "进行性", "complexity_tier": "T3", "furigana": "jìn xíng xìng", "sentence_source": "generated"}, {"text": "这种病的特点是进行性，症状会逐渐加重。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检查结果显示，他的肾病有进行性的特点。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进行性的症状需要长期观察和治疗。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把这种病分为进行性和稳定性两类。", "target_word": "进行性", "complexity_tier": "T3", "furigana": "jìn xíng xìng", "sentence_source": "generated"}, {"text": "病人的骨头问题是进行性的，每年都要拍片。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进行性疾病的病人需要家人长期照顾。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位患者的病情有明显的进行性。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为进行性的变化很慢，一开始很难发现。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，该病具有进行性，不能完全治好。", "target_word": "进行性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "病症持续发展逐渐加重的医学性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1c25cd-5d00-4606-913c-a46535a794fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "进行性", "is_correct": true, "explanation": "正确：“进行性”指病症持续加重的性质，与“症状会一直加重”一致。"}, {"text": "稳定性", "is_correct": false, "explanation": "语义：“稳定性”指不变化的性质，与“症状会一直加重”矛盾。"}, {"text": "自愈性", "is_correct": false, "explanation": "语义：“自愈性”指病症可自行好转，与“症状会一直加重”矛盾。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“亮度”指光线的明暗，不能用来描述病症的发展。"}], "explanations": {"进行性": "正确：“进行性”指病症持续加重的性质，与“症状会一直加重”一致。", "稳定性": "语义：“稳定性”指不变化的性质，与“症状会一直加重”矛盾。", "自愈性": "语义：“自愈性”指病症可自行好转，与“症状会一直加重”矛盾。", "亮度": "搭配：“亮度”指光线的明暗，不能用来描述病症的发展。"}, "sentence_index": 0, "correct_answer": "进行性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种病是进行性的，多年没有加重。", "explanation": "这里应该用〈慢性〉。慢性指病程长、病情基本不变；进行性指病情不断加重，与“多年没有加重”矛盾。"}, {"text": "这种病是进行性的，每年冬天发作一次。", "explanation": "这里应该用〈周期性〉。周期性指间歇发作；进行性指病情持续加重，不指间歇发作。"}, {"text": "这篇文章是进行性的，只有三段。", "explanation": "这里误把“进行性”当成了“逐步推进、有条理地展开”的意思。进行性专指病症持续加重的性质，不能用来说文章的结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进行性", "is_correct": true, "explanation": "正确：“进行性疾病”指病情持续加重的疾病，需要家人长期照顾。"}, {"text": "自限性", "is_correct": false, "explanation": "语义：“自限性”指病程会自行终止，与“需要家人长期照顾”矛盾。"}, {"text": "一过性", "is_correct": false, "explanation": "语义：“一过性”指暂时出现、很快消失，与“长期照顾”冲突。"}, {"text": "健康", "is_correct": false, "explanation": "搭配：“健康”形容身体状态，不能用来修饰“疾病”。"}], "explanations": {"进行性": "正确：“进行性疾病”指病情持续加重的疾病，需要家人长期照顾。", "自限性": "语义：“自限性”指病程会自行终止，与“需要家人长期照顾”矛盾。", "一过性": "语义：“一过性”指暂时出现、很快消失，与“长期照顾”冲突。", "健康": "搭配：“健康”形容身体状态，不能用来修饰“疾病”。"}, "sentence_index": 6, "correct_answer": "进行性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "该病的好转是进行性的，每周都有改善。", "explanation": "这里应该用〈渐进性〉。进行性指病情不断加重，不能用来说病情在好转。"}, {"text": "她的甲状腺是进行性的，多年没有变化。", "explanation": "这里应该用〈稳定〉。进行性指病情不断加重，与“多年没有变化”矛盾。"}, {"text": "这个人的性格是进行性的，一直很开朗。", "explanation": "这里误把“进行性”当成了“性格始终如一”的意思。进行性专指病症逐渐加重，不能用来形容人的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
