INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96681, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "选人时分好的一块地方，这里的人选同一个人。", "primary_collocate": null, "pronunciation": "xuǎn qū", "ipa": "ɕɥɛn˨˩˦ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "我家在这个选区，明天要去投票。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个选区的居民选出了一位代表。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个选区只能选一个人。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在城东，属于第三选区。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们选区的人都支持老李。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次选举，全市分成了十个选区。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想参加选举，所以搬到了那个选区。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选区里的人今天都去投票站了。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个选区很小，只有两千个人。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在自己的选区里认识很多人。", "target_word": "选区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "選區", "label": "繁体"}], "register": "正式", "sense_fingerprint": "选举时分好的一块地方，同一地方的人选同一个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1c25cd-5d00-4606-913c-a46535a794fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96681, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "选区", "is_correct": true, "explanation": "正确：“选区”指选举时划分的区域，与“明天要去投票”相符。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是治病的地方，不是居住的区域，与“我家在这里”冲突。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站是交通场所，不是居住的区域，与“我家在”冲突。"}, {"text": "问题", "is_correct": false, "explanation": "搭配：“问题”不能用来指居住的地方，“我家在这个问题”不成立。"}], "explanations": {"选区": "正确：“选区”指选举时划分的区域，与“明天要去投票”相符。", "医院": "语义：医院是治病的地方，不是居住的区域，与“我家在这里”冲突。", "车站": "语义：车站是交通场所，不是居住的区域，与“我家在”冲突。", "问题": "搭配：“问题”不能用来指居住的地方，“我家在这个问题”不成立。"}, "sentence_index": 0, "correct_answer": "选区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个选区的气候很潮湿。", "explanation": "这里应该用〈地区〉。选区指选举时划分的区域，不指自然地理上的范围。"}, {"text": "他在城东买了一个选区。", "explanation": "选区是选举时划分出来的区域，不是可以买卖的房产或物品。"}, {"text": "我把选区寄给了朋友。", "explanation": "选区是抽象的划分，不是可以寄送的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96681, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选区", "is_correct": true, "explanation": "正确：“选区”是选举时划分的区域，可以搬去居住，与“想参加选举”一致。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理业务的场所，不是可以搬去居住的区域，与语境矛盾。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产的场所，不是人搬去居住的区域，与“想参加选举”无关。"}, {"text": "政策", "is_correct": false, "explanation": "搭配：“搬到”需要地点作宾语，“政策”不是地点，不能与“搬到”搭配。"}], "explanations": {"选区": "正确：“选区”是选举时划分的区域，可以搬去居住，与“想参加选举”一致。", "银行": "语义：银行是办理业务的场所，不是可以搬去居住的区域，与语境矛盾。", "工厂": "语义：工厂是生产的场所，不是人搬去居住的区域，与“想参加选举”无关。", "政策": "搭配：“搬到”需要地点作宾语，“政策”不是地点，不能与“搬到”搭配。"}, "sentence_index": 6, "correct_answer": "选区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个选区有三十层，很高。", "explanation": "选区是选举时划分的区域，不是有楼层的建筑，不能说有几层。"}, {"text": "这个选区很好吃。", "explanation": "这里误把“选区”当成了可以入口的食物。选区指选举时划分的区域，没有味道，不能用“好吃”来形容。"}, {"text": "小王的选区很聪明。", "explanation": "选区是区域，不是人，不能用来形容智力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96681, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只选区新建了一个投票站。", "corrected_sentence": "这个选区新建了一个投票站。", "error_description": "“选区”的量词应为“个”，“只”用于动物等，不能用于选区。正确为“这个选区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96681, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是我们选区地候选人。", "corrected_sentence": "他是我们选区的候选人。", "error_description": "“选区”修饰名词“候选人”时应用“的”，不能用“地”（“地”用于修饰动词或形容词）。正确句为“我们选区的候选人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96682, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
