INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96695, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "比赛得第一名时得到的金色奖牌。", "primary_collocate": null, "pronunciation": "jīn pái", "ipa": "tɕin˥ pʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他在游泳比赛中拿到了金牌。", "target_word": "金牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐的脖子上挂着一块金牌。", "target_word": "金牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把我的金牌放在桌子上。", "target_word": "金牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是她第一次得到金牌。", "target_word": "金牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛得第一名，就能拿金牌。", "target_word": "金牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金牌在灯下闪闪发光。", "target_word": "金牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明很高兴，因为他赢了一块金牌。", "target_word": "金牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把金牌送给了爷爷。", "target_word": "金牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块金牌是跑步比赛的奖品。", "target_word": "金牌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥的房间里有三块金牌。", "target_word": "金牌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "枚", "label": "量词"}, {"form": "金牌得主", "label": "复合"}], "register": "中性", "sense_fingerprint": "比赛得第一名时拿到的金色奖牌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1c25cd-5d00-4606-913c-a46535a794fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96695, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金牌", "is_correct": true, "explanation": "金牌：比赛得第一名时获得的金色奖牌，与“在游泳比赛中拿到”相符。"}, {"text": "学位", "is_correct": false, "explanation": "语义：比赛中不颁发学位，学位是学历资格，与句中语境不符。"}, {"text": "宿舍", "is_correct": false, "explanation": "搭配：“拿到”的对象应是奖品，宿舍是场所，不能被拿到。"}, {"text": "教练", "is_correct": false, "explanation": "配价：“拿到”的宾语须是可获得的物件，教练是人，不能作宾语。"}], "explanations": {"金牌": "金牌：比赛得第一名时获得的金色奖牌，与“在游泳比赛中拿到”相符。", "学位": "语义：比赛中不颁发学位，学位是学历资格，与句中语境不符。", "宿舍": "搭配：“拿到”的对象应是奖品，宿舍是场所，不能被拿到。", "教练": "配价：“拿到”的宾语须是可获得的物件，教练是人，不能作宾语。"}, "sentence_index": 0, "correct_answer": "金牌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位选手拿了一根金牌。", "explanation": "这里应该用〈枚〉或〈块〉。“根”用于细长条状的东西，金牌不能这样计量。"}, {"text": "他比赛赢了一大笔金牌。", "explanation": "这里应该用〈奖金〉。“一大笔”用于计量钱款，金牌是奖牌，不能这样计量。"}, {"text": "他在比赛中拿了亚军，得到了一块金牌。", "explanation": "这里应该用〈银牌〉。亚军只能得到银牌，金牌只授予第一名，句中“亚军”与“金牌”互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96695, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金牌", "is_correct": true, "explanation": "金牌：比赛获得第一名的奖牌，与“赢了一块”相符。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：“赢”的对象应是奖项、比赛或利益，玻璃不能被赢。"}, {"text": "肥皂", "is_correct": false, "explanation": "搭配：“赢”通常不与肥皂这类日用品搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以赢得的奖励，句子的语境不通。"}], "explanations": {"金牌": "金牌：比赛获得第一名的奖牌，与“赢了一块”相符。", "玻璃": "语义：“赢”的对象应是奖项、比赛或利益，玻璃不能被赢。", "肥皂": "搭配：“赢”通常不与肥皂这类日用品搭配。", "石头": "语义：石头不是可以赢得的奖励，句子的语境不通。"}, "sentence_index": 6, "correct_answer": "金牌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直想当金牌。", "explanation": "这里应该用〈冠军〉。金牌指奖牌，不指获奖的人，“当金牌”不成立。"}, {"text": "他获得了博士金牌。", "explanation": "这里应该用〈学位〉。博士是学位，不是奖牌，句中应指学位。"}, {"text": "他这次拿到了一笔金牌。", "explanation": "这里应该用〈奖学金〉。“一笔”用于计量钱款，金牌是奖牌，不能这样计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96695, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在决赛中得到了一条金牌。", "corrected_sentence": "他在决赛中得到了一块金牌。", "error_description": "量词错误：金牌应用量词“枚”或“块”，“条”用于细长的东西，不能修饰金牌。正确说法是“一块金牌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96695, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这根金牌送给了妹妹。", "corrected_sentence": "他把这枚金牌送给了妹妹。", "error_description": "量词错误：金牌应用量词“枚”或“块”，“根”用于细长条状的东西，不能修饰金牌。正确说法是“这枚金牌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
