INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96718, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "高尚；文雅；不粗俗。", "primary_collocate": null, "pronunciation": "yǎ", "ipa": "ja˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个名字取得很雅，我很喜欢。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢读诗，说话也很雅。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家茶馆的名字起得真雅。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爱好很雅，平时不是写字就是画画。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里挂着字画，布置得很雅。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗用词很雅，不像平时说的话。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的品味很雅，不喜欢太花的东西。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同样是喝茶，在书房里喝更雅一些。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开的书店很雅，客人都是爱读书的人。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词太雅了，朋友聊天时很少用。", "target_word": "雅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高雅", "label": "复合"}, {"form": "雅致", "label": "复合"}], "register": "书面", "sense_fingerprint": "情趣品味高尚文雅不俗气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1c25cd-5d00-4606-913c-a46535a794fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96718, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "雅", "is_correct": true, "explanation": "正确：雅（yǎ），指情趣品味高尚、文雅、不俗气。"}, {"text": "压", "is_correct": false, "explanation": "压（yā，第一声）与雅（yǎ，第三声）声调不同，意思是用力向下按。"}, {"text": "牙", "is_correct": false, "explanation": "牙（yá，第二声）与雅（yǎ，第三声）声调不同，意思是牙齿。"}, {"text": "眼", "is_correct": false, "explanation": "眼（yǎn）与雅（yǎ）韵母不同，雅是 a，眼是 an，意思是眼睛。"}, {"text": "鸭", "is_correct": false, "explanation": "鸭（yā，第一声）与雅（yǎ，第三声）声调不同，意思是鸭子。"}], "explanations": {"雅": "正确：雅（yǎ），指情趣品味高尚、文雅、不俗气。", "压": "压（yā，第一声）与雅（yǎ，第三声）声调不同，意思是用力向下按。", "牙": "牙（yá，第二声）与雅（yǎ，第三声）声调不同，意思是牙齿。", "眼": "眼（yǎn）与雅（yǎ）韵母不同，雅是 a，眼是 an，意思是眼睛。", "鸭": "鸭（yā，第一声）与雅（yǎ，第三声）声调不同，意思是鸭子。"}, "sentence_index": null, "correct_answer": "雅"}, "level_3": {"options": [{"text": "雅", "is_correct": true, "explanation": "正确：“雅”形容名字的取法文雅有品味，与后句“我很喜欢”一致。"}, {"text": "难听", "is_correct": false, "explanation": "语义：“难听”与后句“我很喜欢”矛盾。"}, {"text": "冷", "is_correct": false, "explanation": "搭配：“冷”不用来形容名字的取法。"}, {"text": "土", "is_correct": false, "explanation": "语域：“土”是口语，与书面语体的“雅”不一致，且与“我很喜欢”矛盾。"}], "explanations": {"雅": "正确：“雅”形容名字的取法文雅有品味，与后句“我很喜欢”一致。", "难听": "语义：“难听”与后句“我很喜欢”矛盾。", "冷": "搭配：“冷”不用来形容名字的取法。", "土": "语域：“土”是口语，与书面语体的“雅”不一致，且与“我很喜欢”矛盾。"}, "sentence_index": 0, "correct_answer": "雅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子布置得很雅，墙上挂满了花花绿绿的广告。", "explanation": "这里应该用〈花哨〉。“雅”指情趣文雅，墙上挂满花花绿绿的广告要用“花哨”来形容。"}, {"text": "他的爱好很雅，整天只想着赌钱。", "explanation": "这里应该用〈庸俗〉。“雅”指情趣高尚、文雅，整天只想着赌钱的爱好要用“庸俗”来形容。"}, {"text": "他的爱好很雅，就是爱骂人。", "explanation": "这里应该用〈粗俗〉。“雅”指情趣高尚、文雅，以骂人为爱好要用“粗俗”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96718, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "雅", "is_correct": true, "explanation": "正确：雅（yǎ），指情趣品味高尚、文雅、不俗气。"}, {"text": "亚", "is_correct": false, "explanation": "亚（yà，第四声）与雅（yǎ，第三声）声调不同，意思是次一等、亚洲。"}, {"text": "演", "is_correct": false, "explanation": "演（yǎn）与雅（yǎ）韵母不同，雅是 a，演是 an，意思是表演。"}, {"text": "押", "is_correct": false, "explanation": "押（yā，第一声）与雅（yǎ，第三声）声调不同，意思是抵押、按压。"}, {"text": "养", "is_correct": false, "explanation": "养（yǎng）与雅（yǎ）韵母不同，雅是 a，养是 ang，意思是饲养。"}], "explanations": {"雅": "正确：雅（yǎ），指情趣品味高尚、文雅、不俗气。", "亚": "亚（yà，第四声）与雅（yǎ，第三声）声调不同，意思是次一等、亚洲。", "演": "演（yǎn）与雅（yǎ）韵母不同，雅是 a，演是 an，意思是表演。", "押": "押（yā，第一声）与雅（yǎ，第三声）声调不同，意思是抵押、按压。", "养": "养（yǎng）与雅（yǎ）韵母不同，雅是 a，养是 ang，意思是饲养。"}, "sentence_index": null, "correct_answer": "雅"}, "level_3": {"options": [{"text": "雅", "is_correct": true, "explanation": "正确：“雅”形容品味文雅，与后句“不喜欢太花的东西”一致。"}, {"text": "张扬", "is_correct": false, "explanation": "语义：“张扬”与后句“不喜欢太花的东西”矛盾。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人的体型，不能用来形容品味。"}, {"text": "粗壮", "is_correct": false, "explanation": "搭配：“粗壮”形容身体或体型，不用来形容品味。"}], "explanations": {"雅": "正确：“雅”形容品味文雅，与后句“不喜欢太花的东西”一致。", "张扬": "语义：“张扬”与后句“不喜欢太花的东西”矛盾。", "胖": "体貌：“胖”形容人的体型，不能用来形容品味。", "粗壮": "搭配：“粗壮”形容身体或体型，不用来形容品味。"}, "sentence_index": 6, "correct_answer": "雅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个笑话很雅，全是粗话。", "explanation": "这里应该用〈低俗〉。“雅”指文雅、不粗俗，全是粗话的笑话要用“低俗”来形容。"}, {"text": "这个消息很雅，大家都很激动。", "explanation": "这里应该用〈重大〉。“雅”形容情趣、品味和品德，不能用来形容消息，描述消息要用“重大”。"}, {"text": "他的人品很雅，经常在街上打架。", "explanation": "这里应该用〈卑劣〉。“雅”指高尚、文雅，经常在街上打架的人品要用“卑劣”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首诗写很雅，用词很讲究。", "corrected_sentence": "这首诗写得很雅，用词很讲究。", "error_description": "“得”脱落：“写”之后的补语“很雅”需要用“得”连接，应说“写得很雅”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个茶馆的名字雅很，大家都记得住。", "corrected_sentence": "这个茶馆的名字很雅，大家都记得住。", "error_description": "语序错误：程度副词“很”应放在“雅”前面，说“很雅”，不能说“雅很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
