INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96725, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "钱用了以后，剩下的还有多少。", "primary_collocate": null, "pronunciation": "yú é", "ipa": "y˧˥ ɤ˧˥", "syllable_count": 2, "sentences": [{"text": "买完书以后，我的余额只有十块。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的钱用完了，余额不多。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我今天花钱后的余额。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "付了房租以后，余额还有两千元。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把余额存起来，准备下个月用。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我算了一下，余额还够买一件衣服。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行结束后，我们算了算余额。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸问我这次花钱后还有多少余额。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买菜以后余额很少，晚上只能吃面条。", "target_word": "余额", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月底算账时，我发现余额只剩五十元。", "target_word": "余额", "complexity_tier": "T3", "furigana": "yú''é", "sentence_source": "generated"}], "morphological_forms": [{"form": "账户余额", "label": "复合词"}, {"form": "余额不足", "label": "复合词"}, {"form": "餘額", "label": "繁体"}], "register": "中性", "sense_fingerprint": "花钱以后手里剩下的钱数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9270201a-b63b-40e2-a626-90b783a78e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96725, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "余额", "is_correct": true, "explanation": "余额：花钱后剩下的钱，与“买完书以后，我的余额只有十块”相符。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”不能说“只有十块”，与数量表达搭配不上。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是人的岁数，不能用钱的数量来说。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是身体的高度，与“十块”的金额不符。"}], "explanations": {"余额": "余额：花钱后剩下的钱，与“买完书以后，我的余额只有十块”相符。", "心情": "搭配：“心情”不能说“只有十块”，与数量表达搭配不上。", "年龄": "语义：年龄是人的岁数，不能用钱的数量来说。", "身高": "语义：身高是身体的高度，与“十块”的金额不符。"}, "sentence_index": 0, "correct_answer": "余额"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我还没花钱，房东就要收我三千元余额。", "explanation": "这里应该用〈押金〉。余额是花钱后剩下的钱，交给房东的钱要说押金。"}, {"text": "我看了菜单，这道菜的余额是一百元。", "explanation": "这里应该用〈价格〉。余额是花钱后剩下的钱，菜品的标价要说价格。"}, {"text": "这次比赛我得了一千元余额。", "explanation": "这里应该用〈奖金〉。余额是钱用了以后剩下的钱，比赛获得的钱要说奖金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96725, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "余额", "is_correct": true, "explanation": "余额：花钱后剩下的钱，可以计算，与“旅行结束后，我们算了算余额”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“算”不能用于“颜色”，不能说“算了算颜色”。"}, {"text": "情绪", "is_correct": false, "explanation": "语义：情绪是心理状态，不是可以计算的数目。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是感官感受，与“算”的对象不符。"}], "explanations": {"余额": "余额：花钱后剩下的钱，可以计算，与“旅行结束后，我们算了算余额”相符。", "颜色": "搭配：“算”不能用于“颜色”，不能说“算了算颜色”。", "情绪": "语义：情绪是心理状态，不是可以计算的数目。", "味道": "语义：味道是感官感受，与“算”的对象不符。"}, "sentence_index": 6, "correct_answer": "余额"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "余额陪我逛了一下午街。", "explanation": "这里应该用〈朋友〉作主语。余额是钱用了以后剩下的钱，不是人，不能做陪伴的动作。"}, {"text": "这次考试的余额只有五分。", "explanation": "这里应该用〈分数〉。余额只指钱，考试得分要说分数。"}, {"text": "我们在余额里玩了一下午。", "explanation": "这里应该用〈公园〉。余额是数额，不是地方，不能说“在……里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我余额算了一下，还有两百元。", "corrected_sentence": "我把余额算了一下，还有两百元。", "error_description": "错误：“我余额算了一下”。正确：“我把余额算了一下”。“余额”作“算”的宾语，前面须用“把”提到动词前，不能直接放在主语后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅行结束后，我们余额算清楚了。", "corrected_sentence": "旅行结束后，我们把余额算清楚了。", "error_description": "错误：“我们余额算清楚了”。正确：“我们把余额算清楚了”。“余额”作“算清楚”的宾语，要用“把”提到动词前，不能直接放在主语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
