INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96743, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "归某个人管的人。", "primary_collocate": null, "pronunciation": "xià shǔ", "ipa": "ɕia˥˩ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "王经理对他的下属很好。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我是他的下属，每天听他的安排。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让下属明天早点来。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有五个下属，工作很忙。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好领导会帮助自己的下属。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张主任请下属一起吃了饭。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我的下属，不是我的朋友。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把工作分给了几个下属。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下属做错了事，他没有生气。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前是我的下属，现在是我的老板。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "下屬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "归某个领导管的人，指在他手下工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1c25cd-5d00-4606-913c-a46535a794fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96743, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下属", "is_correct": true, "explanation": "下属：归某个领导管的人，与“对……很好”的对象相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“对……很好”的对象应是人，窗户不是人，句意不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“对……很好”的对象应是人，闹钟不能作为对象，句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“对……很好”不与手机搭配，句子语境不通。"}], "explanations": {"下属": "下属：归某个领导管的人，与“对……很好”的对象相符。", "窗户": "语义：“对……很好”的对象应是人，窗户不是人，句意不通。", "闹钟": "语义：“对……很好”的对象应是人，闹钟不能作为对象，句意不通。", "手机": "搭配：“对……很好”不与手机搭配，句子语境不通。"}, "sentence_index": 0, "correct_answer": "下属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和他是多年的下属，平时在一个办公室工作。", "explanation": "这里应该用〈同事〉。下属指受某位上级管理的人，“我”和“他”是平级关系，不能互称下属。"}, {"text": "他有五把下属，工作很忙。", "explanation": "这里应该用〈个〉或〈位〉。下属指人，〈把〉用于有柄的器物，不能修饰人。"}, {"text": "老师每天都要帮助下属做作业。", "explanation": "这里应该用〈学生〉。做作业是学生的事，下属指受上级管理的人，不能说“下属做作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96743, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下属", "is_correct": true, "explanation": "下属：受上级管理的人，与“她是我的……，不是我的朋友”相符。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“她是我的……”需指人，鞋子不是人，与语境不符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“她是我的……”需指人，课本不能与“不是我的朋友”形成对比。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“她是我的”后接的人际关系词不与钢笔这类物件搭配。"}], "explanations": {"下属": "下属：受上级管理的人，与“她是我的……，不是我的朋友”相符。", "鞋子": "语义：“她是我的……”需指人，鞋子不是人，与语境不符。", "课本": "语义：“她是我的……”需指人，课本不能与“不是我的朋友”形成对比。", "钢笔": "搭配：“她是我的”后接的人际关系词不与钢笔这类物件搭配。"}, "sentence_index": 6, "correct_answer": "下属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下属要求大家按时上班。", "explanation": "这里应该用〈领导〉。下属不能向大家提出要求，“要求”应由领导发出。"}, {"text": "下属决定明天放假。", "explanation": "这里应该用〈老板〉。下属不能决定全体安排，“决定”的主语应是上级。"}, {"text": "下属给公司定下了明年的目标。", "explanation": "这里应该用〈管理层〉。下属不能为公司定目标，制定目标的应是上层管理者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96743, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他手下有三把下属，都很能干。", "corrected_sentence": "他手下有三名下属，都很能干。", "error_description": "量词错误：指人的下属应用“名”或“个”，“把”用于有柄的器物，不能修饰人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96743, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他带着这只下属完成了任务。", "corrected_sentence": "他带着这几个下属完成了任务。", "error_description": "量词错误：指人的下属应用“个”或“名”，“只”用于动物或成对物中的一个，不能修饰人。正确说法是“这几个下属”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96744, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96744, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96744, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "受上级领导、管理的人员。", "primary_collocate": null, "pronunciation": "xià shǔ", "ipa": "ɕia˥˩ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "局长开会时，下属都认真地听。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下属要听上级的话。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上级给下属布置了新任务。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位校长常常去看望下属。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下属有问题，可以直接找他。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里的下属都很尊敬他。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长要求下属每天写工作报告。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对上级很客气，对下属也一样。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上级批评了下属，但没有大声说话。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想当好领导，就要关心下属。", "target_word": "下属", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "下屬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "受上级领导和管理的工作人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1c25cd-5d00-4606-913c-a46535a794fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下属", "is_correct": true, "explanation": "下属：受上级领导、管理的人员，与“开会时认真地听”相符。"}, {"text": "盆栽", "is_correct": false, "explanation": "语义：盆栽不能听讲，与“认真地听”的主语不符。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不能作为“认真地听”的主语。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“认真地听”不搭配手机，句子语境不通。"}], "explanations": {"下属": "下属：受上级领导、管理的人员，与“开会时认真地听”相符。", "盆栽": "语义：盆栽不能听讲，与“认真地听”的主语不符。", "沙发": "语义：沙发是家具，不能作为“认真地听”的主语。", "手机": "搭配：“认真地听”不搭配手机，句子语境不通。"}, "sentence_index": 0, "correct_answer": "下属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位校长和老张是多年的下属，常常一起吃饭。", "explanation": "这里应该用〈同事〉。下属指受某位上级管理的人，“校长”与“老张”之间没有上下级关系，不能互称下属。"}, {"text": "这位校长有五把下属。", "explanation": "这里应该用〈个〉或〈位〉。下属指人，〈把〉用于有柄的器物。"}, {"text": "这位校长常常检查下属的作业，还给他们打分。", "explanation": "这里应该用〈学生〉。作业和打分属于学生，下属指受上级管理的人，不能说“下属的作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下属", "is_correct": true, "explanation": "下属：受上级管理的人员，与“要求……写工作报告”相符。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不能写工作报告，与句意不符。"}, {"text": "书架", "is_correct": false, "explanation": "配价：“要求”的对象应是能执行任务的人，书架不能作为这一动作的执行者。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不能写工作报告，句子语境不通。"}], "explanations": {"下属": "下属：受上级管理的人员，与“要求……写工作报告”相符。", "电视": "语义：电视不能写工作报告，与句意不符。", "书架": "配价：“要求”的对象应是能执行任务的人，书架不能作为这一动作的执行者。", "猫": "语义：猫不能写工作报告，句子语境不通。"}, "sentence_index": 6, "correct_answer": "下属"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下属要求大家按时上班。", "explanation": "这里应该用〈领导〉。下属不能向大家提出要求，“要求”应由领导发出。"}, {"text": "下属决定明天放假。", "explanation": "这里应该用〈老板〉。下属不能决定全体安排，“决定”的主语应是上级。"}, {"text": "下属给公司定下了明年的目标。", "explanation": "这里应该用〈管理层〉。下属不能为公司定目标，制定目标的应是上层管理者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校长手下有两把下属，都很能干。", "corrected_sentence": "校长手下有两位下属，都很能干。", "error_description": "量词错误：指人的下属应用“位”或“个”，“把”用于有柄的器物，不能修饰人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "部长带着这只下属去了工厂。", "corrected_sentence": "部长带着这几个下属去了工厂。", "error_description": "量词错误：指人的下属应用“个”或“名”，“只”用于动物或成对物中的一个，不能修饰人。正确说法是“这几个下属”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
