INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96753, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个接一个地做过很多工作或职位。", "primary_collocate": null, "pronunciation": "lì rèn", "ipa": "li˥˩ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "他历任球队的队长、教练和经理。", "target_word": "历任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她历任报社的记者、编辑和主编。", "target_word": "历任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位厨师历任三家大饭店的主厨。", "target_word": "历任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在公司历任销售、市场和人事部门的经理。", "target_word": "历任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陈老师历任小学、中学和大学的语文老师。", "target_word": "历任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时历任工人、司机和仓库管理员。", "target_word": "历任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位演员历任电影学院的老师和系主任。", "target_word": "历任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周先生历任公司的财务、销售和运营总监。", "target_word": "历任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院的院长历任科室主任和副院长。", "target_word": "历任", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他历任协会的秘书、理事和会长。", "target_word": "历任", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "歷任", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "一个接一个地做过很多工作或职位（工作经历）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437cb559-6856-4d1f-a96f-ccfdf83827d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96753, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历任", "is_correct": true, "explanation": "正确：历任指先后担任多个职务，与队长、教练、经理相符。"}, {"text": "指挥", "is_correct": false, "explanation": "搭配：“指挥”的对象是队伍、部队，不说指挥队长、教练这类职务。"}, {"text": "训练", "is_correct": false, "explanation": "搭配：“训练”的对象是队员，不说训练队长、教练等职务。"}, {"text": "驱逐", "is_correct": false, "explanation": "语义：“驱逐”指赶走，与“他”担任职务的语境不合。"}], "explanations": {"历任": "正确：历任指先后担任多个职务，与队长、教练、经理相符。", "指挥": "搭配：“指挥”的对象是队伍、部队，不说指挥队长、教练这类职务。", "训练": "搭配：“训练”的对象是队员，不说训练队长、教练等职务。", "驱逐": "语义：“驱逐”指赶走，与“他”担任职务的语境不合。"}, "sentence_index": 0, "correct_answer": "历任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他历任一个小时的讲座。", "explanation": "这里应该用〈主讲〉。历任指先后担任多个职务，不用于一次性的讲课活动。"}, {"text": "他历任一次会议的主持人，效果很好。", "explanation": "这里应该用〈主持〉。历任指先后担任多个职务，只担任一次会议的职务时不能说历任。"}, {"text": "他历任人事部工作。", "explanation": "这里应该用〈曾在〉。历任用于担任的职务，不用于一般的工作地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96753, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历任", "is_correct": true, "explanation": "正确：历任指先后担任过老师、系主任等职务，与演员的经历相符。"}, {"text": "招聘", "is_correct": false, "explanation": "语义：“招聘”是招收人员，句中“那位演员”是任职者，不能说他招聘老师和系主任。"}, {"text": "录取", "is_correct": false, "explanation": "搭配：“录取”的对象是考生、学生，不说录取老师和系主任。"}, {"text": "讲授", "is_correct": false, "explanation": "搭配：“讲授”的对象是课程、知识，不说讲授系主任。"}], "explanations": {"历任": "正确：历任指先后担任过老师、系主任等职务，与演员的经历相符。", "招聘": "语义：“招聘”是招收人员，句中“那位演员”是任职者，不能说他招聘老师和系主任。", "录取": "搭配：“录取”的对象是考生、学生，不说录取老师和系主任。", "讲授": "搭配：“讲授”的对象是课程、知识，不说讲授系主任。"}, "sentence_index": 6, "correct_answer": "历任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他历任北京分公司的一次调查。", "explanation": "这里应该用〈进行〉。历任指担任职务，调查是活动而非职务，应说进行。"}, {"text": "她历任协会的一次宣传。", "explanation": "这里应该用〈开展〉。历任指担任职务，宣传活动应说开展。"}, {"text": "她历任许多磨难。", "explanation": "这里应该用〈经历〉。历任指担任职务，不用于说经历磨难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他历任在三家俱乐部的教练和领队。", "corrected_sentence": "他历任三家俱乐部的教练和领队。", "error_description": "错误在“历任”后插入了“在”。“历任”后直接接职务名称，应改为“历任三家俱乐部的教练和领队”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她历任着两家杂志社的编辑和记者。", "corrected_sentence": "她历任两家杂志社的编辑和记者。", "error_description": "错误在“历任”后加了“着”。“历任”表示已经完成的经历，不带“着”；应改为“历任两家杂志社的编辑和记者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
