INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96755, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "友谊", "is_correct": true, "explanation": "正确：友谊与“仇恨”构成反义，指朋友之间友好的感情。"}, {"text": "利润", "is_correct": false, "explanation": "利润是经济收益，与“仇恨”没有反义关系。"}, {"text": "地图", "is_correct": false, "explanation": "地图是具体的物品，与“仇恨”没有反义关系。"}, {"text": "花朵", "is_correct": false, "explanation": "花朵是植物的一部分，与“仇恨”没有反义关系。"}], "correct_answer": "友谊", "explanations": {"友谊": "正确：友谊与“仇恨”构成反义，指朋友之间友好的感情。", "利润": "利润是经济收益，与“仇恨”没有反义关系。", "地图": "地图是具体的物品，与“仇恨”没有反义关系。", "花朵": "花朵是植物的一部分，与“仇恨”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96755, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因为被伤害，心里对人很生气，一直忘不了。", "primary_collocate": null, "pronunciation": "chóu hèn", "ipa": "ʈʂʰoʊ˧˥ xən˥˩", "syllable_count": 2, "sentences": [{"text": "朋友骗了她，她心里一直留着仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对那个人的仇恨，十年了还没有消失。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话时，声音里全是仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想把仇恨带到明天，今天就原谅你。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受过很大的伤，却没有一点仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人伤害了她的家人，她一直记着这份仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈劝我放下过去，别让仇恨毁了生活。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看那个人的眼神里有仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间一天天过去，她心里的仇恨慢慢变淡了。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，仇恨让人睡不好觉，也吃不下饭。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "受伤害后对人长久不忘的怨恨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1c25cd-5d00-4606-913c-a46535a794fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96755, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仇恨", "is_correct": true, "explanation": "正确：“仇恨”指受伤害后长久不忘的怨恨，与“朋友骗了她”相符。"}, {"text": "好感", "is_correct": false, "explanation": "语义：“好感”与“朋友骗了她”引起的心情矛盾。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“礼物”是实物，不能说“心里留着礼物”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是身体的数值，不能说“心里留着体重”。"}], "explanations": {"仇恨": "正确：“仇恨”指受伤害后长久不忘的怨恨，与“朋友骗了她”相符。", "好感": "语义：“好感”与“朋友骗了她”引起的心情矛盾。", "礼物": "搭配：“礼物”是实物，不能说“心里留着礼物”。", "体重": "搭配：“体重”是身体的数值，不能说“心里留着体重”。"}, "sentence_index": 0, "correct_answer": "仇恨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她心里养着一只仇恨，十几年没放下。", "explanation": "这里应该用〈股〉。“仇恨”是抽象的情感，量词要用“股”，“只”多用于动物或成对的东西。"}, {"text": "我很感激他，所以把仇恨送给他做礼物。", "explanation": "仇恨是负面情感，不能当作礼物送人，与“感激”相矛盾。"}, {"text": "听到好消息，她心里充满了仇恨，高兴得跳了起来。", "explanation": "这里应该用〈欢喜〉。“仇恨”是负面情感，听到好消息后的开心要用“欢喜”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96755, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仇恨", "is_correct": true, "explanation": "正确：“仇恨”指长久不忘的怨恨，与“妈妈劝我放下过去”的语境相符。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：“温暖”与“毁了生活”矛盾。"}, {"text": "粮食", "is_correct": false, "explanation": "搭配：“粮食”是实物，不能用来“毁了生活”这样的情感描述。"}, {"text": "钟声", "is_correct": false, "explanation": "搭配：“钟声”是声音，不能说“毁了生活”。"}], "explanations": {"仇恨": "正确：“仇恨”指长久不忘的怨恨，与“妈妈劝我放下过去”的语境相符。", "温暖": "语义：“温暖”与“毁了生活”矛盾。", "粮食": "搭配：“粮食”是实物，不能用来“毁了生活”这样的情感描述。", "钟声": "搭配：“钟声”是声音，不能说“毁了生活”。"}, "sentence_index": 6, "correct_answer": "仇恨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸说，他心里有一把仇恨，让人睡不好觉。", "explanation": "这里应该用〈股〉。“仇恨”是抽象的情感，量词要用“股”，“把”用于有柄的器具。"}, {"text": "爸爸说，仇恨让人睡得很香，吃得很好。", "explanation": "这里应该用〈爱〉。仇恨与“睡得很香，吃得很好”相矛盾，换成“爱”才符合语境。"}, {"text": "这个孩子唱歌很好听，大家都喜欢听他的仇恨。", "explanation": "这里应该用〈歌声〉。“仇恨”是情感，不能被听到，大家喜欢听的应该是“歌声”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96755, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朋友骗了她，她心里一直留着一只仇恨。", "corrected_sentence": "朋友骗了她，她心里一直留着一股仇恨。", "error_description": "量词错误：“仇恨”是抽象情感，应用量词“股”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
