INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96756, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因利益冲突或受到伤害而产生的强烈憎恨。", "primary_collocate": null, "pronunciation": "chóu hèn", "ipa": "ʈʂʰoʊ˧˥ xən˥˩", "syllable_count": 2, "sentences": [{"text": "两家公司争了多年，彼此心里都有仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争留下的仇恨，需要很多年才能化解。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心中的仇恨越来越深，最后做出了错事。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个村子因为抢水，结下了很深的仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仇恨不能解决问题，只会带来更多伤害。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人说，他已经放下了对邻居的仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了土地的事，兄弟俩多年来一直怀着仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的眼里充满了仇恨，让人不敢靠近。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要把上一代的仇恨传给孩子。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生意上的竞争有时会变成个人之间的仇恨。", "target_word": "仇恨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "利益冲突或伤害引起的强烈憎恨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1c25cd-5d00-4606-913c-a46535a794fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仇恨", "is_correct": true, "explanation": "正确：“仇恨”指利益冲突产生的憎恨，与“争了多年”相符。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：“友谊”与“争了多年”矛盾。"}, {"text": "好感", "is_correct": false, "explanation": "语义：“好感”与“争了多年”矛盾。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“成绩”不能放在“心里都有”之后，心里不会有成绩。"}], "explanations": {"仇恨": "正确：“仇恨”指利益冲突产生的憎恨，与“争了多年”相符。", "友谊": "语义：“友谊”与“争了多年”矛盾。", "好感": "语义：“好感”与“争了多年”矛盾。", "成绩": "搭配：“成绩”不能放在“心里都有”之后，心里不会有成绩。"}, "sentence_index": 0, "correct_answer": "仇恨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个村子因为抢水，结下了一只仇恨。", "explanation": "这里应该用〈股〉。“仇恨”是抽象的情感，量词要用“股”，“只”多用于动物或成对的东西。"}, {"text": "两个村子因为抢水，互相帮忙，结下了很深的仇恨。", "explanation": "这里应该用〈友谊〉。“结下仇恨”表示敌对，与“互相帮忙”相矛盾，两村互相帮忙应说“结下友谊”。"}, {"text": "他对妻子的仇恨很深，两人结婚三十年，恩爱如初。", "explanation": "这里应该用〈感情〉。“仇恨”指强烈憎恨，夫妻之间的深厚关系要用“感情”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仇恨", "is_correct": true, "explanation": "正确：“仇恨”指利益冲突产生的憎恨，与“为了土地的事”相符。"}, {"text": "友情", "is_correct": false, "explanation": "语义：“友情”与“为了土地的事”引起的争执矛盾。"}, {"text": "利润", "is_correct": false, "explanation": "搭配：“利润”是经济收益，不能说“怀着利润”。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：“地图”是具体的物品，不能说“怀着地图”。"}], "explanations": {"仇恨": "正确：“仇恨”指利益冲突产生的憎恨，与“为了土地的事”相符。", "友情": "语义：“友情”与“为了土地的事”引起的争执矛盾。", "利润": "搭配：“利润”是经济收益，不能说“怀着利润”。", "地图": "搭配：“地图”是具体的物品，不能说“怀着地图”。"}, "sentence_index": 6, "correct_answer": "仇恨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "生意上的竞争有时会变成个人之间的一把仇恨。", "explanation": "这里应该用〈股〉。“仇恨”是抽象的情感，量词要用“股”，“把”用于有柄的器具。"}, {"text": "两家商店一直合作得很好，彼此之间有很深的仇恨。", "explanation": "这里应该用〈信任〉。“仇恨”指敌对的强烈憎恨，合作得很好的两家店之间要用“信任”来形容。"}, {"text": "这笔生意做成了，两个商人之间只剩下仇恨，却又一起庆祝。", "explanation": "这里应该用〈默契〉。“仇恨”指敌对的强烈憎恨，做成生意后一起庆祝的关系要用“默契”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对那个人心里还有一只仇恨。", "corrected_sentence": "他对那个人心里还有一股仇恨。", "error_description": "量词错误：“仇恨”是抽象情感，应用量词“股”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对那个人的一只仇恨很深。", "corrected_sentence": "他对那个人的一股仇恨很深。", "error_description": "量词错误：“仇恨”是抽象情感，应用量词“股”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '610cbc2e-3903-4291-819e-7cd27a2b8550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
