INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96761, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "每一个人。", "primary_collocate": null, "pronunciation": "měi rén", "ipa": "meɪ̯˨˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "每人都有自己的梦想。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这里，每人都可以说话。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每人都应该遵守规则。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每人都喜欢听好听的话。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事，每人都知道。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每人的想法都不一样。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得每人都应该有休息的时间。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公司里，每人都很忙。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每人都会遇到困难。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，每人都要认真听。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "泛指所有人中的每一个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9270201a-b63b-40e2-a626-90b783a78e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96761, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "每人", "is_correct": true, "explanation": "每人：指每一个人，是本题要听辨的目标词。"}, {"text": "媒人", "is_correct": false, "explanation": "媒人 méi rén 与 每人 měi rén 第一个音节声调不同（第二声与第三声），意思是替人说合婚事的人。"}, {"text": "媚人", "is_correct": false, "explanation": "媚人 mèi rén 与 每人 měi rén 第一个音节声调不同（第四声与第三声），意思是讨人喜欢。"}, {"text": "北人", "is_correct": false, "explanation": "北人 běi rén 与 每人 měi rén 声母不同（b 与 m），意思是北方人。"}], "explanations": {"每人": "每人：指每一个人，是本题要听辨的目标词。", "媒人": "媒人 méi rén 与 每人 měi rén 第一个音节声调不同（第二声与第三声），意思是替人说合婚事的人。", "媚人": "媚人 mèi rén 与 每人 měi rén 第一个音节声调不同（第四声与第三声），意思是讨人喜欢。", "北人": "北人 běi rén 与 每人 měi rén 声母不同（b 与 m），意思是北方人。"}, "sentence_index": null, "correct_answer": "每人"}, "level_3": {"options": [{"text": "每人", "is_correct": true, "explanation": "每人：指每个人，与“都有自己的梦想”的个体含义相合。"}, {"text": "彼此", "is_correct": false, "explanation": "语义：“彼此”表示相互，与“都有自己的梦想”指个人的含义不符。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”不指人，不能作“有自己的梦想”的主语。"}, {"text": "这", "is_correct": false, "explanation": "配价：“这”指代事物，“有自己的梦想”要求人作主语，“这都有自己的梦想”不成立。"}], "explanations": {"每人": "每人：指每个人，与“都有自己的梦想”的个体含义相合。", "彼此": "语义：“彼此”表示相互，与“都有自己的梦想”指个人的含义不符。", "什么": "语义：“什么”不指人，不能作“有自己的梦想”的主语。", "这": "配价：“这”指代事物，“有自己的梦想”要求人作主语，“这都有自己的梦想”不成立。"}, "sentence_index": 0, "correct_answer": "每人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上每人都摆着一盆花。", "explanation": "这里应该用〈每个〉。“每人”只指人，不能指桌子上的物品；指物品要用“每个”。"}, {"text": "我们每人一起唱了一首歌。", "explanation": "这里应该用〈大家〉。“每人”强调各人分别行动，与“一起”这种集体行动相矛盾。"}, {"text": "每人合力抬起了那张桌子。", "explanation": "这里应该用〈大家〉。“每人”强调各人分别行动，与“合力”这种共同行动相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96761, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每人", "is_correct": true, "explanation": "每人：指每个人，与“应该有休息的时间”的语境相合。"}, {"text": "那", "is_correct": false, "explanation": "配价：“那”指代事物，“应该有休息的时间”要求人作主语，“他觉得那都应该有休息的时间”不成立。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“早饭”是食物，不能休息，与句意不符。"}, {"text": "其中", "is_correct": false, "explanation": "语义：“其中”指前文已提到的一部分，句中没有先行语，且与“每人”的全体义冲突。"}], "explanations": {"每人": "每人：指每个人，与“应该有休息的时间”的语境相合。", "那": "配价：“那”指代事物，“应该有休息的时间”要求人作主语，“他觉得那都应该有休息的时间”不成立。", "早饭": "语义：“早饭”是食物，不能休息，与句意不符。", "其中": "语义：“其中”指前文已提到的一部分，句中没有先行语，且与“每人”的全体义冲突。"}, "sentence_index": 6, "correct_answer": "每人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的妹妹每人都愿意帮忙。", "explanation": "这里应该去掉〈每人〉，直接说“我的妹妹愿意帮忙”。“每人”指一组人中的每一个，不能用于单独一人。"}, {"text": "我们班每人中有一些人没认真听。", "explanation": "这里应该去掉〈每人〉，说“我们班中有一些人没认真听”。“每人”指全体中的每一个，不能与表示部分的“一些”搭配。"}, {"text": "老师说，我每人都要认真听。", "explanation": "这里应该去掉〈每人〉，说“老师说，我都要认真听”。“每人”指一组人中的每一个，不能用于单独一人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96761, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每人都都有一把伞。", "corrected_sentence": "每人都有一把伞。", "error_description": "“都”只能用一次，紧跟在“每人”之后表示全体；这里重复了“都”，错误。正确说法是“每人都有一把伞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96761, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每人要都交一份报告。", "corrected_sentence": "每人都要交一份报告。", "error_description": "“都”应紧跟在“每人”之后表示全体，放在“要”之后位置错误。正确说法是“每人都要交一份报告”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
