INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96762, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "每个人；各人。", "primary_collocate": null, "pronunciation": "měi rén", "ipa": "meɪ̯˨˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "老师给每人发了一本书。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的作业，每人写一篇短文。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些苹果，每人两个。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每人付了五十块钱。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请每人拿一张纸。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给每人倒了一杯茶。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，每人得到一个小礼物。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有三个盘子，每人一个。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每人每天走一万步。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小组每人负责一部分。", "target_word": "每人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每个人各自分到或承担的份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9270201a-b63b-40e2-a626-90b783a78e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96762, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "每人", "is_correct": true, "explanation": "每人：指每个人，是本题要听辨的目标词。"}, {"text": "没人", "is_correct": false, "explanation": "没人 méi rén 与 每人 měi rén 第一个音节声调不同（第二声与第三声），意思是没有人。"}, {"text": "媚人", "is_correct": false, "explanation": "媚人 mèi rén 与 每人 měi rén 第一个音节声调不同（第四声与第三声），意思是讨人喜欢。"}, {"text": "北人", "is_correct": false, "explanation": "北人 běi rén 与 每人 měi rén 声母不同（b 与 m），意思是北方人。"}], "explanations": {"每人": "每人：指每个人，是本题要听辨的目标词。", "没人": "没人 méi rén 与 每人 měi rén 第一个音节声调不同（第二声与第三声），意思是没有人。", "媚人": "媚人 mèi rén 与 每人 měi rén 第一个音节声调不同（第四声与第三声），意思是讨人喜欢。", "北人": "北人 běi rén 与 每人 měi rén 声母不同（b 与 m），意思是北方人。"}, "sentence_index": null, "correct_answer": "每人"}, "level_3": {"options": [{"text": "每人", "is_correct": true, "explanation": "每人：指每个人各得一本，与“给每人发了一本书”的分配语境相合。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，陈述句中不能指不定的某个人，“老师给谁发了一本书”需要疑问语境才成立。"}, {"text": "彼此", "is_correct": false, "explanation": "搭配：“彼此”表示相互，老师把书发给学生是单向的，不能说“老师给彼此发了一本书”。"}, {"text": "对方", "is_correct": false, "explanation": "语义：“对方”指对立或交往中的另一方，不能用来指班上的学生。"}], "explanations": {"每人": "每人：指每个人各得一本，与“给每人发了一本书”的分配语境相合。", "谁": "语义：“谁”是疑问代词，陈述句中不能指不定的某个人，“老师给谁发了一本书”需要疑问语境才成立。", "彼此": "搭配：“彼此”表示相互，老师把书发给学生是单向的，不能说“老师给彼此发了一本书”。", "对方": "语义：“对方”指对立或交往中的另一方，不能用来指班上的学生。"}, "sentence_index": 0, "correct_answer": "每人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书架上每人都放着一本书。", "explanation": "这里应该用〈每个〉。“每人”只指人，不能指书架上的物品；指物品要用“每个”。"}, {"text": "我们每人一起吃了一顿火锅。", "explanation": "这里应该用〈大家〉。“每人”强调各人分别行动，与“一起”这种集体行动相矛盾。"}, {"text": "每人合力搬起了那个大箱子。", "explanation": "这里应该用〈大家〉。“每人”强调各人分别行动，与“合力”这种共同行动相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96762, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每人", "is_correct": true, "explanation": "每人：指比赛后每个人各得一个礼物，与句意相合。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”是疑问代词，陈述句中不能作“得到礼物”的主语，“什么得到一个小礼物”不成立。"}, {"text": "这", "is_correct": false, "explanation": "配价：“这”指代事物，不能作“得到礼物”的主语，句中需要指人的主语。"}, {"text": "那", "is_correct": false, "explanation": "配价：“那”指代远处的事物，无法得到礼物，与句中指人的语境不符。"}], "explanations": {"每人": "每人：指比赛后每个人各得一个礼物，与句意相合。", "什么": "语义：“什么”是疑问代词，陈述句中不能作“得到礼物”的主语，“什么得到一个小礼物”不成立。", "这": "配价：“这”指代事物，不能作“得到礼物”的主语，句中需要指人的主语。", "那": "配价：“那”指代远处的事物，无法得到礼物，与句中指人的语境不符。"}, "sentence_index": 6, "correct_answer": "每人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的弟弟每人都喜欢打篮球。", "explanation": "这里应该去掉〈每人〉，直接说“我的弟弟喜欢打篮球”。“每人”指一组人中的每一个，不能用于单独一人。"}, {"text": "我们小组每人中有一些人没交作业。", "explanation": "这里应该去掉〈每人〉，说“我们小组中有一些人没交作业”。“每人”指全体中的每一个，不能与表示部分的“一些”搭配。"}, {"text": "我每人负责了一部分工作。", "explanation": "这里应该去掉〈每人〉，说“我负责了一部分工作”。“每人”指一组人中的每一个，不能用于单独一人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96762, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们每人拿到着一个红包。", "corrected_sentence": "孩子们每人拿到了一个红包。", "error_description": "“拿到”表示动作已经完成，后面要用“了”，不能用“着”表示持续；“拿到着”错误。正确说法是“孩子们每人拿到了一个红包”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96762, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每人都都带了一瓶水。", "corrected_sentence": "我们每人都带了一瓶水。", "error_description": "“都”只能用一次，紧跟在“每人”之后表示全体；这里重复使用了“都”，多出一个“都”。正确说法是“我们每人都带了一瓶水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
