INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96763, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "时间或事情到了。", "primary_collocate": null, "pronunciation": "lái lín", "ipa": "laɪ̯˧˥ lin˧˥", "syllable_count": 2, "sentences": [{"text": "考试的日子终于来临了。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新学期来临，同学们很高兴。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业的时刻来临了。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们等着春节来临。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的时间来临，大家都很紧张。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好机会来临时，要马上抓住。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他盼着假期来临。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离别的时刻来临，她哭了。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当考试来临，我就睡不好。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸福的日子来临了。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "来临了", "label": "体标"}], "register": "书面", "sense_fingerprint": "某个时刻或时机到了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9270201a-b63b-40e2-a626-90b783a78e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96763, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来临", "is_correct": true, "explanation": "来临：指考试的日子到来，与句意相合。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”需要能主动移动的人或物作主语，“日子出发”不成立。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是人的生理动作，与“考试的日子”的到来无关。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”需要人在水中活动，与“日子”不搭配。"}], "explanations": {"来临": "来临：指考试的日子到来，与句意相合。", "出发": "配价：“出发”需要能主动移动的人或物作主语，“日子出发”不成立。", "咳嗽": "语义：“咳嗽”是人的生理动作，与“考试的日子”的到来无关。", "游泳": "语义：“游泳”需要人在水中活动，与“日子”不搭配。"}, "sentence_index": 0, "correct_answer": "来临"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "欢迎您来临我的生日派对。", "explanation": "这里应该用〈光临〉。来临不用于对客人的敬称，迎接客人应说“光临”。"}, {"text": "我们的火车来临了北京。", "explanation": "这里应该用〈抵达〉。来临不带处所宾语，火车应说“抵达北京”。"}, {"text": "我们等着春节来临三个小时。", "explanation": "这里应该用〈临近〉。来临指事情到来的那一刻，不能与“三个小时”这样的时长搭配；表示快要到来才可用“临近”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96763, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来临", "is_correct": true, "explanation": "来临：指假期到来，与“盼着”表达的期待语境相合。"}, {"text": "下课", "is_correct": false, "explanation": "配价：“下课”以课堂为语境，“假期下课”不成立。"}, {"text": "发言", "is_correct": false, "explanation": "语义：“发言”指在会议或课堂上讲话，与假期无关。"}, {"text": "理发", "is_correct": false, "explanation": "语义：“理发”是人的具体动作，不能用来指“假期”。"}], "explanations": {"来临": "来临：指假期到来，与“盼着”表达的期待语境相合。", "下课": "配价：“下课”以课堂为语境，“假期下课”不成立。", "发言": "语义：“发言”指在会议或课堂上讲话，与假期无关。", "理发": "语义：“理发”是人的具体动作，不能用来指“假期”。"}, "sentence_index": 6, "correct_answer": "来临"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家快来临！", "explanation": "来临不用于叫人过来，叫人过来应说“来”或“过来”，这里的用法不对。"}, {"text": "快递来临了。", "explanation": "这里应该用〈送到〉。来临多指事情或时间到来，快递到来应说“送到”。"}, {"text": "妈妈来临了。", "explanation": "这里应该用〈到了〉。来临多指时间或事情到了，不用于指人到达，妈妈到达应说“到了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96763, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛的日子被来临了。", "corrected_sentence": "比赛的日子来临了。", "error_description": "“来临”是不及物动词，不能用“被”字句表示被动；“比赛的日子被来临了”错误。正确说法是“比赛的日子来临了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96763, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新年马上就要要来临了。", "corrected_sentence": "新年马上就要来临了。", "error_description": "“要”只能用一次，放在“来临”之前表示将要发生；这里重复了“要”，错误。正确说法是“新年马上就要来临了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
