INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96764, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "来到；到来。", "primary_collocate": null, "pronunciation": "lái lín", "ipa": "laɪ̯˧˥ lin˧˥", "syllable_count": 2, "sentences": [{"text": "夜幕慢慢来临了。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来临，花都开了。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日来临前，街上很热闹。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨来临之前，天很黑。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天来临，大家都穿上了厚衣服。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年来临，家家都挂起红灯笼。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "危险来临时，他一点也不怕。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜晚来临，星星出来了。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴风雪来临前，人们都回家了。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑夜来临，山里变得很安静。", "target_word": "来临", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "来临了", "label": "体标"}], "register": "书面", "sense_fingerprint": "季节、夜晚、天气或危险等来到面前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9270201a-b63b-40e2-a626-90b783a78e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96764, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来临", "is_correct": true, "explanation": "来临：指夜幕逐渐到来，与句意相合。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”要求能主动移动的人或物作主语，“夜幕慢慢出发了”不成立。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”指人缔结婚姻，与“夜幕”无关，句意不通。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”要求会说话的人作主语，“夜幕慢慢说了”不成立。"}], "explanations": {"来临": "来临：指夜幕逐渐到来，与句意相合。", "出发": "配价：“出发”要求能主动移动的人或物作主语，“夜幕慢慢出发了”不成立。", "结婚": "语义：“结婚”指人缔结婚姻，与“夜幕”无关，句意不通。", "说": "配价：“说”要求会说话的人作主语，“夜幕慢慢说了”不成立。"}, "sentence_index": 0, "correct_answer": "来临"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "欢迎您来临本店。", "explanation": "这里应该用〈光临〉。来临不用于对客人的敬称，迎接客人应说“光临”。"}, {"text": "列车已经来临车站了。", "explanation": "这里应该用〈到达〉。来临不带处所宾语，列车应说“到达车站”。"}, {"text": "他每天早上都来临公司上班。", "explanation": "这里应该用〈来到〉。来临多指季节、时间、灾害等来到，不用于人去某地，应说“来到公司”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来临", "is_correct": true, "explanation": "来临：指危险到来，与句中“危险来临时”的语境相合。"}, {"text": "唱歌", "is_correct": false, "explanation": "配价：“唱歌”需要人作施事，“危险唱歌时”不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是人的生理活动，与危险到来的语境不符。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要书写者和书写对象，“危险写时”不成立。"}], "explanations": {"来临": "来临：指危险到来，与句中“危险来临时”的语境相合。", "唱歌": "配价：“唱歌”需要人作施事，“危险唱歌时”不成立。", "睡觉": "语义：“睡觉”是人的生理活动，与危险到来的语境不符。", "写": "配价：“写”需要书写者和书写对象，“危险写时”不成立。"}, "sentence_index": 6, "correct_answer": "来临"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈，快来临！", "explanation": "来临不用于叫人过来，叫人过来应说“来”或“过来”，这里的用法不对。"}, {"text": "游客们今天来临北京。", "explanation": "这里应该用〈抵达〉。来临不带处所宾语，游客应说“抵达北京”。"}, {"text": "包裹来临了。", "explanation": "这里应该用〈送到〉。来临多指季节、时间、事情等到来，包裹到来应说“送到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天被来临了。", "corrected_sentence": "春天来临了。", "error_description": "“来临”是不及物动词，不能用“被”字句表示被动；“春天被来临了”错误。正确说法是“春天来临了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
