INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96765, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "concrete", "definition": "每一个地方。", "primary_collocate": null, "pronunciation": "měi chù", "ipa": "meɪ˨˩˦ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "这座公园有三处入口，每处都有保安。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每处风景都很美。", "target_word": "每处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房间里有两处漏水，我们每处都修好了。", "target_word": "每处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，书上每处错误都要改。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路上有五处停车场，每处都很大。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在地图上每处都画了红圈。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上有几处小店，每处都卖热茶。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这三处房子我都看过，每处都不错。", "target_word": "每处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身上有几处伤，每处都不深。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几处景点我们每处都玩了一天。", "target_word": "每处", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "每處", "label": "繁体"}], "register": "中性", "sense_fingerprint": "几个地方中的每一个地方（逐一）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '437cb559-6856-4d1f-a96f-ccfdf83827d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96765, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每处", "is_correct": true, "explanation": "正确。每处指公园三个入口中的每一处，与“都有保安”相呼应。"}, {"text": "每间", "is_correct": false, "explanation": "搭配：量词“间”用于房屋，入口不用“间”计数，不能说每间都有保安。"}, {"text": "每台", "is_correct": false, "explanation": "搭配：量词“台”用于机器、车辆等，入口不用“台”计数，不能说每台都有保安。"}, {"text": "每位", "is_correct": false, "explanation": "语义：“位”指人，入口不是人，不能说每位都有保安。"}], "explanations": {"每处": "正确。每处指公园三个入口中的每一处，与“都有保安”相呼应。", "每间": "搭配：量词“间”用于房屋，入口不用“间”计数，不能说每间都有保安。", "每台": "搭配：量词“台”用于机器、车辆等，入口不用“台”计数，不能说每台都有保安。", "每位": "语义：“位”指人，入口不是人，不能说每位都有保安。"}, "sentence_index": 0, "correct_answer": "每处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每处考试我都很紧张。", "explanation": "这里应该用〈每次〉。每处指每一个地方，说考试的次数要用每次。"}, {"text": "每处客人都有一个座位。", "explanation": "这里应该用〈每位〉。每处只用于地方，指人要用每位。"}, {"text": "每处衣服都很贵。", "explanation": "这里应该用〈每件〉。衣服要用“件”计数，每处只用于地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96765, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每处", "is_correct": true, "explanation": "正确。每处指山上几处小店中的每一处，与“都卖热茶”相呼应。"}, {"text": "每台", "is_correct": false, "explanation": "搭配：量词“台”用于机器、车辆等，小店不用“台”计数，不能说每台都卖热茶。"}, {"text": "每架", "is_correct": false, "explanation": "搭配：量词“架”用于飞机、机器等，小店不用“架”计数。"}, {"text": "每队", "is_correct": false, "explanation": "语义：“队”指团体，小店不是队伍，不能说每队都卖热茶。"}], "explanations": {"每处": "正确。每处指山上几处小店中的每一处，与“都卖热茶”相呼应。", "每台": "搭配：量词“台”用于机器、车辆等，小店不用“台”计数，不能说每台都卖热茶。", "每架": "搭配：量词“架”用于飞机、机器等，小店不用“架”计数。", "每队": "语义：“队”指团体，小店不是队伍，不能说每队都卖热茶。"}, "sentence_index": 6, "correct_answer": "每处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每处歌都很好听。", "explanation": "这里应该用〈每首〉。歌曲要用“首”计数，每处只用于地方。"}, {"text": "每处菜都很香。", "explanation": "这里应该用〈每道〉。菜要用“道”计数，每处只用于地方。"}, {"text": "每处信都写得很长。", "explanation": "这里应该用〈每封〉。信件要用“封”计数，每处只用于地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96765, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个车站有四处出口，一每处都挂着地图。", "corrected_sentence": "这个车站有四处出口，每处都挂着地图。", "error_description": "“每处”前面不能加数词“一”，“每”本身已经表示“每一”的意思；应说“每处都挂着地图”，不说“一每处”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96765, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个湖边有三处码头，每处很都热闹。", "corrected_sentence": "这个湖边有三处码头，每处都很热闹。", "error_description": "错误在“都”的位置。“都”须位于“很”之前，应说“每处都很热闹”，不说“每处很都热闹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '400bcd78-6ca8-4447-b935-f285eb490bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "无名：没有名气，不为人所知，与“出名”的意思相反。"}, {"text": "安静", "is_correct": false, "explanation": "安静说声音小或没有动静，与“出名”的意思没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜说价钱低，是“贵”的反义词，与“出名”的意思无关。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚说明白、不模糊，与“出名”的意思无关。"}], "correct_answer": "无名", "explanations": {"无名": "无名：没有名气，不为人所知，与“出名”的意思相反。", "安静": "安静说声音小或没有动静，与“出名”的意思没有反义关系。", "便宜": "便宜说价钱低，是“贵”的反义词，与“出名”的意思无关。", "清楚": "清楚说明白、不模糊，与“出名”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "无名：没有名气，不为人所知，与“出名”的意思相反。"}, {"text": "昂贵", "is_correct": false, "explanation": "昂贵说价格高，与“出名”的意思无关。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮说外貌好看，与“出名”的意思无关。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙说表面不光滑，与“出名”的意思无关。"}], "correct_answer": "无名", "explanations": {"无名": "无名：没有名气，不为人所知，与“出名”的意思相反。", "昂贵": "昂贵说价格高，与“出名”的意思无关。", "漂亮": "漂亮说外貌好看，与“出名”的意思无关。", "粗糙": "粗糙说表面不光滑，与“出名”的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有名；为众人所知（多指人因才能或事迹而名声在外）。", "primary_collocate": null, "pronunciation": "chū míng", "ipa": "ʈʂʰu˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他唱歌很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师在我们学校很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年纪不大，却已经很出名了。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的书让他很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小男孩一夜之间就出名了。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想当歌星，也想出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生在城里很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踢球踢得好，所以很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不太出名，很少人认识他。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个演员在国外也很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出名了", "label": "体标"}], "register": "中性", "sense_fingerprint": "人因才能或事迹而被很多人知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9270201a-b63b-40e2-a626-90b783a78e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出名", "is_correct": true, "explanation": "正确：出名 chū míng，意思是很多人都知道某人或某物。"}, {"text": "书名", "is_correct": false, "explanation": "shū（第一声）与 chū（第一声）声母不同（sh 与 ch），意思是书的名字。"}, {"text": "出门", "is_correct": false, "explanation": "mén 与 míng 韵母不同（-en 与 -ing），意思是外出。"}, {"text": "除名", "is_correct": false, "explanation": "chú（第二声）与 chū（第一声）声调不同，意思是从名册上除去名字。"}], "explanations": {"出名": "正确：出名 chū míng，意思是很多人都知道某人或某物。", "书名": "shū（第一声）与 chū（第一声）声母不同（sh 与 ch），意思是书的名字。", "出门": "mén 与 míng 韵母不同（-en 与 -ing），意思是外出。", "除名": "chú（第二声）与 chū（第一声）声调不同，意思是从名册上除去名字。"}, "sentence_index": null, "correct_answer": "出名"}, "level_3": {"options": [{"text": "出名", "is_correct": true, "explanation": "出名：很多人都知道他，符合“他唱歌很出名”的句意。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：矮说身材的高低，不说唱歌的名气，与“唱歌”搭不上。"}, {"text": "饿", "is_correct": false, "explanation": "语义：饿说想吃东西的身体状态，与唱歌无关，句子不通。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：便宜说价钱低，不能用来说唱歌的水平或名气。"}], "explanations": {"出名": "出名：很多人都知道他，符合“他唱歌很出名”的句意。", "矮": "体貌：矮说身材的高低，不说唱歌的名气，与“唱歌”搭不上。", "饿": "语义：饿说想吃东西的身体状态，与唱歌无关，句子不通。", "便宜": "搭配：便宜说价钱低，不能用来说唱歌的水平或名气。"}, "sentence_index": 0, "correct_answer": "出名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次比赛的表现很出名。", "explanation": "这里应该用〈出色〉。出名指人或事物被大家所知，说表现的优劣要用出色。"}, {"text": "这种饼干的价格很出名。", "explanation": "这里应该用〈便宜〉。出名说的是为众人所知，价格的高低要用便宜、贵等。"}, {"text": "这次考试他的成绩很出名。", "explanation": "这里应该用〈出众〉。出名说的是为众人所知，成绩的超群要用出众。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出名", "is_correct": true, "explanation": "出名：很多人知道这位医生，符合句意。"}, {"text": "咸", "is_correct": false, "explanation": "语义：咸说味道，不能用来形容医生在城里的名声。"}, {"text": "远", "is_correct": false, "explanation": "搭配：远说距离，不能用来说人在城里是否有名。"}, {"text": "白", "is_correct": false, "explanation": "体貌：白说肤色，与医生在城里的名声无关。"}], "explanations": {"出名": "出名：很多人知道这位医生，符合句意。", "咸": "语义：咸说味道，不能用来形容医生在城里的名声。", "远": "搭配：远说距离，不能用来说人在城里是否有名。", "白": "体貌：白说肤色，与医生在城里的名声无关。"}, "sentence_index": 6, "correct_answer": "出名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出名地写字，一写就是几个小时。", "explanation": "这里误把“出名”当作程度副词（出名地、非常）。“出名地”只修饰有突出特点的性质或行为（如出名地抠门），“写字”是中性动作，不能这样用；“出名”的本义是为众人所知。"}, {"text": "我出名地喝水，一天只喝一口。", "explanation": "这里误把“出名”当作程度副词（出名地、非常）。“出名地”只修饰有突出特点的性质或行为，“喝水”是中性动作，不能这样用；“出名”的本义是为众人所知。"}, {"text": "妈妈出名地洗衣服，洗了一下午。", "explanation": "这里误把“出名”当作程度副词（出名地、非常）。“出名地”只修饰有突出特点的性质或行为，“洗衣服”是中性动作，不能这样用；“出名”的本义是为众人所知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一位很出名老师。", "corrected_sentence": "这是一位很出名的老师。", "error_description": "错误：“很出名老师”漏掉了“的”。正确：“很出名的老师”。“很”加形容词修饰名词时，形容词后通常要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96787, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位作家在国外很很出名。", "corrected_sentence": "那位作家在国外很出名。", "error_description": "错误：程度副词“很”重复出现，“很很出名”多了一个“很”。正确：“很出名”，只用一个“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96788, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无名", "is_correct": true, "explanation": "无名：没有名气，不为人所知，与“出名”的意思相反。"}, {"text": "安静", "is_correct": false, "explanation": "安静说环境清静、没有声音，与“出名”的意思没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "便宜说价钱低，是“贵”的反义词，与“出名”的意思无关。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚说明白、不模糊，与“出名”的意思无关。"}], "correct_answer": "无名", "explanations": {"无名": "无名：没有名气，不为人所知，与“出名”的意思相反。", "安静": "安静说环境清静、没有声音，与“出名”的意思没有反义关系。", "便宜": "便宜说价钱低，是“贵”的反义词，与“出名”的意思无关。", "清楚": "清楚说明白、不模糊，与“出名”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
