INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96788, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有名；为众人所知。", "primary_collocate": null, "pronunciation": "chū míng", "ipa": "ʈʂʰu˥ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这家饭店很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西湖是一个出名的地方。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶非常出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京烤鸭在世界上很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山因为风景美而出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街以小吃出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那是一家出名的老店。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的手机很出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的家乡以大米出名。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书出名以后，卖得很快。", "target_word": "出名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出名了", "label": "体标"}], "register": "中性", "sense_fingerprint": "地方、食物、物品等有名气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9270201a-b63b-40e2-a626-90b783a78e1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96788, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出名", "is_correct": true, "explanation": "正确：出名 chū míng，意思是地方或东西为很多人所知。"}, {"text": "书名", "is_correct": false, "explanation": "shū（第一声）与 chū（第一声）声母不同（sh 与 ch），意思是书的名字。"}, {"text": "出门", "is_correct": false, "explanation": "mén 与 míng 韵母不同（-en 与 -ing），意思是外出。"}, {"text": "除名", "is_correct": false, "explanation": "chú（第二声）与 chū（第一声）声调不同，意思是从名册上除去名字。"}], "explanations": {"出名": "正确：出名 chū míng，意思是地方或东西为很多人所知。", "书名": "shū（第一声）与 chū（第一声）声母不同（sh 与 ch），意思是书的名字。", "出门": "mén 与 míng 韵母不同（-en 与 -ing），意思是外出。", "除名": "chú（第二声）与 chū（第一声）声调不同，意思是从名册上除去名字。"}, "sentence_index": null, "correct_answer": "出名"}, "level_3": {"options": [{"text": "出名", "is_correct": true, "explanation": "出名：这家饭店为很多人所知，符合句意。"}, {"text": "饿", "is_correct": false, "explanation": "语义：饿是人想吃东西的状态，饭店不会饿，句子不通。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：胖说人或动物的身形，不用来说饭店。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：聪明说人的智力，饭店没有智力，句子不通。"}], "explanations": {"出名": "出名：这家饭店为很多人所知，符合句意。", "饿": "语义：饿是人想吃东西的状态，饭店不会饿，句子不通。", "胖": "体貌：胖说人或动物的身形，不用来说饭店。", "聪明": "语义：聪明说人的智力，饭店没有智力，句子不通。"}, "sentence_index": 0, "correct_answer": "出名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的服务员态度很出名。", "explanation": "这里应该用〈友好〉。出名说人或事物被众人所知，说态度的好坏要用友好。"}, {"text": "这家饭店的房价很出名。", "explanation": "这里应该用〈昂贵〉。出名说的是为众人所知，房价的高低要用昂贵、便宜等。"}, {"text": "这家饭店的环境很出名。", "explanation": "这里应该用〈安静〉。出名说的是为众人所知，环境的清静要用安静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出名", "is_correct": true, "explanation": "出名：这家老店为很多人所知，符合句意。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：年轻与“老店”矛盾，店铺不能既年轻又是老店。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：瘦说人的身形，不用来说店铺。"}, {"text": "长", "is_correct": false, "explanation": "搭配：长说长短，不能用来形容店铺的名气。"}], "explanations": {"出名": "出名：这家老店为很多人所知，符合句意。", "年轻": "语义：年轻与“老店”矛盾，店铺不能既年轻又是老店。", "瘦": "体貌：瘦说人的身形，不用来说店铺。", "长": "搭配：长说长短，不能用来形容店铺的名气。"}, "sentence_index": 6, "correct_answer": "出名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师出名地切菜，切了一下午。", "explanation": "这里误把“出名”当作程度副词（出名地、非常）。“出名地”只修饰有突出特点的性质或行为（如出名地好吃），“切菜”是中性动作，不能这样用；“出名”的本义是为众人所知。"}, {"text": "服务员出名地擦桌子，擦了两个小时。", "explanation": "这里误把“出名”当作程度副词（出名地、非常）。“出名地”只修饰有突出特点的性质或行为，“擦桌子”是中性动作，不能这样用；“出名”的本义是为众人所知。"}, {"text": "客人出名地吃饭，吃了一个多小时。", "explanation": "这里误把“出名”当作程度副词（出名地、非常）。“出名地”只修饰有突出特点的性质或行为，“吃饭”是中性动作，不能这样用；“出名”的本义是为众人所知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3112f35c-8d46-45e5-8fea-21f43a8b38ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
