INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96797, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用手机写给别人的几句话。", "primary_collocate": null, "pronunciation": "duǎn xìn", "ipa": "tuan˨˩˦ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈给我发了一条短信。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在手机上写了一条短信。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的短信只有两句话。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给朋友回一条短信。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看到我的短信了吗？", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我会给你发短信。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把短信写好了，没有发出去。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的短信让我很开心。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的时候，他看着短信笑了。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给哥哥写过一条短信。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "短信息", "label": "复合"}], "register": "口语", "sense_fingerprint": "短信：用手机写给别人的几句话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b4015d-40c0-445c-b8d9-0067753700f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96797, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短信", "is_correct": true, "explanation": "正确。“发”的对象是信息，“条”是短信的量词。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不能被“发”给人，句子说的是发送信息。"}, {"text": "狗", "is_correct": false, "explanation": "搭配：“发”用于信息和货物，不用于活的动物，应说“送”。"}, {"text": "船", "is_correct": false, "explanation": "语义：船是交通工具，不能被“发”给人，与“给我”的语境不符。"}], "explanations": {"短信": "正确。“发”的对象是信息，“条”是短信的量词。", "河": "语义：河不能被“发”给人，句子说的是发送信息。", "狗": "搭配：“发”用于信息和货物，不用于活的动物，应说“送”。", "船": "语义：船是交通工具，不能被“发”给人，与“给我”的语境不符。"}, "sentence_index": 0, "correct_answer": "短信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在邮局寄了一条短信。", "explanation": "这里误把〈短信〉当成〈信件〉来寄。“寄”用于信件、包裹，短信是通过手机发送的文字，不能寄。"}, {"text": "我用手机拍了一条短信。", "explanation": "这里应该用〈视频〉。“拍”搭配视频、照片，短信是文字，不能被拍。"}, {"text": "我昨天弹了一条短信。", "explanation": "这里应该用〈乐曲〉。“弹”搭配乐器，短信是文字，不能弹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96797, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短信", "is_correct": true, "explanation": "正确。“写”的对象是文字，短信是可以写好再发出去的文字。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“写”的对象是文字，饭不能被写。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“写”不搭配礼物，礼物是送出去的，不是写的。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能被写，句子说的是写好文字再发出去。"}], "explanations": {"短信": "正确。“写”的对象是文字，短信是可以写好再发出去的文字。", "饭": "语义：“写”的对象是文字，饭不能被写。", "礼物": "搭配：“写”不搭配礼物，礼物是送出去的，不是写的。", "桌子": "语义：桌子不能被写，句子说的是写好文字再发出去。"}, "sentence_index": 6, "correct_answer": "短信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在舞台上唱了一条短信。", "explanation": "这里应该用〈歌曲〉。“唱”搭配歌曲，短信是文字，不能唱。"}, {"text": "我昨天去照相馆洗了一条短信。", "explanation": "这里应该用〈照片〉。“洗”搭配照片，短信不能冲洗。"}, {"text": "我给哥哥写过一只短信。", "explanation": "这里误把短信当成〈动物〉那样用“只”计量。“只”用于动物等，短信是文字，应用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96797, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天给妈妈发了一块短信。", "corrected_sentence": "我昨天给妈妈发了一条短信。", "error_description": "量词错误：“短信”的量词用“条”，不用“块”（“块”用于块状的东西）。正确：我昨天给妈妈发了一条短信。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96797, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她给同事发了一张短信，说会议改期了。", "corrected_sentence": "她给同事发了一条短信，说会议改期了。", "error_description": "量词错误：“短信”的量词用“条”，不用“张”（“张”用于纸张、照片等扁平的东西）。正确：她给同事发了一条短信，说会议改期了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
