INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用手机发送的简短文字信息。", "primary_collocate": null, "pronunciation": "duǎn xìn", "ipa": "tuan˨˩˦ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "银行给我发来一条短信。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我收到一条短信，说快递到了。", "target_word": "短信", "complexity_tier": "T3", "furigana": "wǒ shōudào yì tiáo duǎnxìn, shuō kuàidì dào le.", "sentence_source": "generated"}, {"text": "我每天都收到好几条陌生人发来的短信。", "target_word": "短信", "complexity_tier": "T3", "furigana": "wǒ měitiān dōu shōudào hǎojǐ tiáo mòshēngrén fālái de duǎnxìn.", "sentence_source": "generated"}, {"text": "这条短信是公司发的通知。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员用短信告诉我取件地址。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机收不到短信了。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把那条短信给我看看。", "target_word": "短信", "complexity_tier": "T3", "furigana": "qǐng bǎ nà tiáo duǎnxìn gěi wǒ kànkan.", "sentence_source": "generated"}, {"text": "他删过很多旧短信。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短信里写着开会的时间。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机一响，我就看短信。", "target_word": "短信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "垃圾短信", "label": "复合"}], "register": "口语", "sense_fingerprint": "短信：手机发送的简短文字信息，如通知、验证码", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b4015d-40c0-445c-b8d9-0067753700f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短信", "is_correct": true, "explanation": "正确。“发来”的对象是信息，“条”是短信的量词。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不能由银行“发来”。"}, {"text": "蛇", "is_correct": false, "explanation": "搭配：“发来”用于信息和货物，不用于活的动物。"}, {"text": "船", "is_correct": false, "explanation": "语义：船不能被“发来”给人，句子说的是通知信息。"}], "explanations": {"短信": "正确。“发来”的对象是信息，“条”是短信的量词。", "河": "语义：河不能由银行“发来”。", "蛇": "搭配：“发来”用于信息和货物，不用于活的动物。", "船": "语义：船不能被“发来”给人，句子说的是通知信息。"}, "sentence_index": 0, "correct_answer": "短信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上都画短信。", "explanation": "这里应该用〈图画〉。“画”搭配图画，短信是文字，不能画。"}, {"text": "他用手机拍了一条短信。", "explanation": "这里应该用〈照片〉。“拍”搭配照片、视频，短信不能被拍。"}, {"text": "我昨天收到一只短信。", "explanation": "这里误把短信当成〈动物〉那样用“只”计量。“只”用于动物等，短信是文字，应用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短信", "is_correct": true, "explanation": "正确。“把……给我看看”的对象是可以拿来给人看的文字信息。"}, {"text": "命", "is_correct": false, "explanation": "语义：“命”指生命，不能拿来给我看。"}, {"text": "狗", "is_correct": false, "explanation": "搭配：“把……给我”不用于活的动物。"}, {"text": "溪", "is_correct": false, "explanation": "语义：溪不能被拿来给我看。"}], "explanations": {"短信": "正确。“把……给我看看”的对象是可以拿来给人看的文字信息。", "命": "语义：“命”指生命，不能拿来给我看。", "狗": "搭配：“把……给我”不用于活的动物。", "溪": "语义：溪不能被拿来给我看。"}, "sentence_index": 6, "correct_answer": "短信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天把一条短信装进了箱子。", "explanation": "这里误把短信当成〈物品〉来装。“装”搭配有形的物品，短信是文字，不能装进箱子。"}, {"text": "他在舞台上唱了一条短信。", "explanation": "这里应该用〈歌曲〉。“唱”搭配歌曲，短信是文字，不能唱。"}, {"text": "他每周末都下短信。", "explanation": "这里应该用〈棋〉。“下”搭配棋类，短信不能下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天收到一块短信，说包裹到了。", "corrected_sentence": "我昨天收到一条短信，说包裹到了。", "error_description": "“短信”的量词应用“条”，不能用“块”（“块”用于块状的东西）。正确：我昨天收到一条短信，说包裹到了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把那只短信转给我。", "corrected_sentence": "请把那条短信转给我。", "error_description": "量词错误：“短信”的量词用“条”，不用“只”（“只”用于动物等）。正确：请把那条短信转给我。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
