INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96833, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“自然历史”讲的是大自然里的动物、植物和地球，从很久以前到现在是怎么变化的。", "primary_collocate": null, "pronunciation": "zì rán lì shǐ", "ipa": "ts˥˩ ɻan˧˥ li˥˩ ʂʅ˨˩˦", "syllable_count": 4, "sentences": [{"text": "这本书讲的是地球的自然历史。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山和河也有它们自己的自然历史。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恐龙的自然历史很长。", "target_word": "自然历史", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看了这些石头，我们就知道这里的自然历史。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个展览讲了森林的自然历史。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想知道海洋的自然历史是怎样的。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一棵老树里藏着一段自然历史。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家从化石里读出了这片土地的自然历史。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟类的自然历史比人类长得多。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的自然历史有几百万年。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然歷史", "label": "繁体"}], "register": "书面", "sense_fingerprint": "自然事物发展变化的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d5af855-8d3e-4dea-9cbd-ca81272939c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96833, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然历史", "is_correct": true, "explanation": "正确。这里指自然事物从很久以前到现在的演变过程，可以作为一本书讲述的内容。"}, {"text": "价格", "is_correct": false, "explanation": "语义：地球不存在价格，价格不是一本书讲述地球的内容。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是人居住的房间，不属于地球的自然演变。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“地球的”后接工资说不通，工资属于人的劳动报酬。"}], "explanations": {"自然历史": "正确。这里指自然事物从很久以前到现在的演变过程，可以作为一本书讲述的内容。", "价格": "语义：地球不存在价格，价格不是一本书讲述地球的内容。", "厨房": "语义：厨房是人居住的房间，不属于地球的自然演变。", "工资": "搭配：“地球的”后接工资说不通，工资属于人的劳动报酬。"}, "sentence_index": 0, "correct_answer": "自然历史"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他年轻时的自然历史很丰富。", "explanation": "这里应该用〈经历〉。经历指个人亲身遇到的过程，自然历史讲的是自然事物的演变，不能用来形容个人的过去。"}, {"text": "他每天早上都要吃自然历史。", "explanation": "这里应该用〈早饭〉。早饭可以吃，自然历史是事物的演变过程，不能吃。"}, {"text": "这棵树的自然历史长得很高。", "explanation": "这里应该用〈树木〉。树木可以长高，自然历史指事物的演变过程，不能说“长得很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96833, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然历史", "is_correct": true, "explanation": "正确。“一段”计量的是事物的演变过程，藏在老树里的是树木和土地的变化历史。"}, {"text": "老鼠", "is_correct": false, "explanation": "搭配：“段”计量的是过程或片段，不能计量动物，不说“一段老鼠”。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不会藏在老树里。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：“段”不用于液体，“一段汽油”不成立。"}], "explanations": {"自然历史": "正确。“一段”计量的是事物的演变过程，藏在老树里的是树木和土地的变化历史。", "老鼠": "搭配：“段”计量的是过程或片段，不能计量动物，不说“一段老鼠”。", "钢琴": "语义：钢琴是乐器，不会藏在老树里。", "汽油": "搭配：“段”不用于液体，“一段汽油”不成立。"}, "sentence_index": 6, "correct_answer": "自然历史"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的自然历史已经六十岁了。", "explanation": "这里应该用〈年龄〉。年龄指一个人活了多少年，自然历史指事物演变的过程，不能表示人的年龄。"}, {"text": "他的童年自然历史很清楚。", "explanation": "这里应该用〈记忆〉。记忆是人对过去的印象，自然历史指自然事物的演变，不指个人的记忆。"}, {"text": "那个自然历史很便宜。", "explanation": "这里应该用〈商品〉。商品可以便宜，自然历史是事物的演变过程，不能用“便宜”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块岩石记录着它漫长的自然历史们。", "corrected_sentence": "这块岩石记录着它漫长的自然历史。", "error_description": "“自然历史”指事物的演变过程，是抽象名词，不能加“们”表示复数；应说“漫长的自然历史”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那片湖底藏着一颗自然历史。", "corrected_sentence": "那片湖底藏着一段自然历史。", "error_description": "“自然历史”指事物的演变过程，量词应用“段”，不能用“颗”（“颗”多用于圆粒状的东西）；应说“一段自然历史”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
