INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96834, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对自然界的生物、矿物和地球环境及其演变进行观察和描述的学问。", "primary_collocate": null, "pronunciation": "zì rán lì shǐ", "ipa": "ts˥˩ ɻan˧˥ li˥˩ ʂʅ˨˩˦", "syllable_count": 4, "sentences": [{"text": "他在大学里学习自然历史。", "target_word": "自然历史", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书是一本自然历史的入门书。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然历史研究动物、植物和矿物。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究自然历史的人常常要去野外观察。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然历史这门学问很早就有了。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小对自然历史有兴趣，常常看书。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了一课自然历史。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学自然历史要认识很多动物和植物。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "达尔文是一位研究自然历史的科学家。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然历史需要长期观察，不能只看书。", "target_word": "自然历史", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然歷史", "label": "繁体"}], "register": "书面", "sense_fingerprint": "研究自然界生物与地球的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d5af855-8d3e-4dea-9cbd-ca81272939c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然历史", "is_correct": true, "explanation": "正确。这里指研究自然界生物与地球的学问，是大学可以学习的学科。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“学习”的对象应是知识或学问，面包不能被学习。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场是运动的场地，不是可以学习的内容。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑的部件，与“学习”的对象无关。"}], "explanations": {"自然历史": "正确。这里指研究自然界生物与地球的学问，是大学可以学习的学科。", "面包": "搭配：“学习”的对象应是知识或学问，面包不能被学习。", "操场": "语义：操场是运动的场地，不是可以学习的内容。", "窗户": "语义：窗户是建筑的部件，与“学习”的对象无关。"}, "sentence_index": 0, "correct_answer": "自然历史"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片森林里自然历史很多。", "explanation": "这里应该用〈生物〉。自然历史指学问，不是可以数量很多的东西，“很多”应接〈生物〉。"}, {"text": "他把自然历史吃了。", "explanation": "这里应该用〈饭〉。饭可以吃，自然历史是学问，不能吃。"}, {"text": "他每周都要踢自然历史。", "explanation": "这里应该用〈足球〉。足球可以踢，自然历史是学问或过程，不能用“踢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然历史", "is_correct": true, "explanation": "正确。“讲一课”后接可以讲授的学科，自然历史指研究自然界的学问。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，不是可以讲授的内容。"}, {"text": "拖把", "is_correct": false, "explanation": "语义：拖把是清洁用具，不是课堂上可以讲授的内容。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“讲一课”要求讲授的是知识内容，心情不能说“讲一课”。"}], "explanations": {"自然历史": "正确。“讲一课”后接可以讲授的学科，自然历史指研究自然界的学问。", "钥匙": "语义：钥匙是开锁的工具，不是可以讲授的内容。", "拖把": "语义：拖把是清洁用具，不是课堂上可以讲授的内容。", "心情": "搭配：“讲一课”要求讲授的是知识内容，心情不能说“讲一课”。"}, "sentence_index": 6, "correct_answer": "自然历史"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家阳台上种满了自然历史。", "explanation": "这里应该用〈植物〉。植物可以种，自然历史是学问或演变过程，不能种。"}, {"text": "他一直喜欢养小自然历史。", "explanation": "这里应该用〈动物〉。动物可以饲养，自然历史是学问或过程，不能饲养。"}, {"text": "他每天早上都喝自然历史。", "explanation": "这里应该用〈牛奶〉。牛奶可以喝，自然历史是学问，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门自然历史们的讲座很有意思。", "corrected_sentence": "这门自然历史的讲座很有意思。", "error_description": "“自然历史”作学科时是无生命的名词，不能加“们”表示复数；应说“这门自然历史”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这学期他选了三张自然历史。", "corrected_sentence": "这学期他选了三门自然历史。", "error_description": "作课程讲时，量词应用“门”；“张”多用于纸张、桌子等平面的东西，不能用于课程；应说“三门自然历史”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
