INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96840, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在中国大陆发行销售的版本（多指电子产品）。", "primary_collocate": null, "pronunciation": "guó xíng", "ipa": "kuo˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "国行手机支持中国的网络。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国行版本只在大陆卖。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款电脑的国行版下个月上市。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国行平板的系统是中文的。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国行游戏机比海外版晚上市。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买的国行相机有中国保修。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国行版没有一些外国功能。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国行的电视机装了中文软件。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国行耳机的包装是中文的。", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要国行还是日版？", "target_word": "国行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國行", "label": "繁体"}, {"form": "国行手机", "label": "复合"}], "register": "口语", "sense_fingerprint": "国行：在中国大陆发行销售的版本，多指电子产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b4015d-40c0-445c-b8d9-0067753700f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国行", "is_correct": true, "explanation": "“国行”指在中国大陆发行的版本，能支持中国的网络，句意通顺。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不是能联网的设备，与“支持中国的网络”不符。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“厨房”不能用来修饰“手机”构成版本或类型。"}, {"text": "砖头", "is_correct": false, "explanation": "语义：砖头不能支持网络，句子无法成立。"}], "explanations": {"国行": "“国行”指在中国大陆发行的版本，能支持中国的网络，句意通顺。", "木头": "语义：木头不是能联网的设备，与“支持中国的网络”不符。", "厨房": "搭配：“厨房”不能用来修饰“手机”构成版本或类型。", "砖头": "语义：砖头不能支持网络，句子无法成立。"}, "sentence_index": 0, "correct_answer": "国行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台游戏机是国行的，只在韩国卖。", "explanation": "这里应该用〈韩版〉。国行指在中国大陆发行的版本，这句说只在韩国卖，应说韩版。"}, {"text": "这台平板是国行的，不能用中国大陆的网络。", "explanation": "这里应该用〈港版〉。国行就是在中国大陆发行的版本，不能说它不能用中国大陆的网络。"}, {"text": "这款电视是国行的，不在中国的商店卖。", "explanation": "这里应该用〈进口〉。国行指在中国大陆销售的版本，不能说它不在中国的商店卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国行", "is_correct": true, "explanation": "“国行”指在中国大陆发行的版本，与“版”组合成“国行版”，句意通顺。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不是可以发行版本的产品，“银行版”不能指电子产品。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是产品的版本，“空气版”无法成立。"}, {"text": "草地", "is_correct": false, "explanation": "搭配：“版”用于产品或出版物，不能修饰“草地”。"}], "explanations": {"国行": "“国行”指在中国大陆发行的版本，与“版”组合成“国行版”，句意通顺。", "银行": "语义：银行不是可以发行版本的产品，“银行版”不能指电子产品。", "空气": "语义：空气不是产品的版本，“空气版”无法成立。", "草地": "搭配：“版”用于产品或出版物，不能修饰“草地”。"}, "sentence_index": 6, "correct_answer": "国行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台相机是国行的，只在美国卖。", "explanation": "这里应该用〈美版〉。国行指在中国大陆发行的版本，这句说只在美国卖，应说美版。"}, {"text": "我在东京的商店买了一台国行的电视。", "explanation": "这里应该用〈日版〉。国行指在中国大陆发行的版本，在东京商店买到的应说日版。"}, {"text": "这块手表是国行的，是我在台湾买的。", "explanation": "这里应该用〈台版〉。国行指在中国大陆发行的版本，这句说是在台湾买的，应说台版。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他上周买了两只国行，都很好用。", "corrected_sentence": "他上周买了两台国行，都很好用。", "error_description": "量词错误：“国行”指某款设备的版本，应说“两台国行”；“只”用于动物等，不能用来数“国行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐买了一本国行，很喜欢。", "corrected_sentence": "我姐姐买了一台国行，很喜欢。", "error_description": "量词错误：“国行”指某款设备的版本，应说“一台国行”；“本”用于书册，不能用来数设备版本。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
