INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96855, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "从外面看东西是什么样子。", "primary_collocate": null, "pronunciation": "wài guān", "ipa": "wai˥˩ kuan˥", "syllable_count": 2, "sentences": [{"text": "这座房子的外观很漂亮。", "target_word": "外观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从外观看，这个盒子是新的。", "target_word": "外观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的外观很特别。", "target_word": "外观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼的外观像一艘大船。", "target_word": "外观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别只看外观，里面也很重要。", "target_word": "外观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的外观看上去很旧。", "target_word": "外观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先检查一下箱子的外观。", "target_word": "外观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的外观已经变了。", "target_word": "外观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从外观上很难看出里面有什么。", "target_word": "外观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子的外观让我想起小时候。", "target_word": "外观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外觀", "label": "繁体"}, {"form": "外观设计", "label": "复合"}], "register": "中性", "sense_fingerprint": "外观：从外面看到的东西的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0741d1e3-cd5c-4fae-91d1-65d37b98a78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96855, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外观", "is_correct": true, "explanation": "外观：房子从外面看到的样子，可以说很漂亮。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，房子的外表不是味道，不能说很漂亮。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“漂亮”形容外形，不能用来形容价格。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”只说大小，不说漂亮。"}], "explanations": {"外观": "外观：房子从外面看到的样子，可以说很漂亮。", "味道": "语义：“味道”指气味或滋味，房子的外表不是味道，不能说很漂亮。", "价格": "搭配：“漂亮”形容外形，不能用来形容价格。", "面积": "搭配：“面积”只说大小，不说漂亮。"}, "sentence_index": 0, "correct_answer": "外观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老人的外观很响亮。", "explanation": "这里应该用〈声音〉。外观指看到的样子，“响亮”形容听到的声音，要说声音很响亮。"}, {"text": "这台机器的外观很多。", "explanation": "这里应该用〈功能〉。外观指样子，不能用多少来形容，机器的功能才说很多。"}, {"text": "这辆车的外观很快。", "explanation": "这里应该用〈速度〉。外观指样子，不能用快慢来形容，速度才说很快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96855, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外观", "is_correct": true, "explanation": "外观：箱子从外面看到的样子，是检查的对象之一。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的心理特点，箱子不能有性格。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”指人的情绪，箱子没有心情可检查。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”多用于人或动物，箱子的重量要说重量。"}], "explanations": {"外观": "外观：箱子从外面看到的样子，是检查的对象之一。", "性格": "语义：“性格”指人的心理特点，箱子不能有性格。", "心情": "语义：“心情”指人的情绪，箱子没有心情可检查。", "体重": "搭配：“体重”多用于人或动物，箱子的重量要说重量。"}, "sentence_index": 6, "correct_answer": "外观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段音乐的外观很好听。", "explanation": "这里应该用〈旋律〉。外观指看到的样子，“好听”形容听觉，要说旋律好听。"}, {"text": "这瓶香水的外观很浓。", "explanation": "这里应该用〈气味〉。外观指样子，不能用浓淡来形容，气味才说很浓。"}, {"text": "这杯水的外观很烫。", "explanation": "这里应该用〈温度〉。外观指样子，不能用冷热来形容，温度才说很烫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96855, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款手机有一只很时尚的外观。", "corrected_sentence": "这款手机有一种很时尚的外观。", "error_description": "错误：量词“只”，应为“种”。“只”用于动物或成对的东西，外观是抽象的样式，要用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96855, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个包的外观看起很新。", "corrected_sentence": "这个包的外观看起来很新。", "error_description": "错误：漏掉补语“来”，应为“看起来”。“看起”不成词，表示从外表看上去要用“看起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c276a15-a703-4bf4-a676-a3aa6988fd00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
