INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96859, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很大的一块地方。", "primary_collocate": null, "pronunciation": "dà fàn wéi", "ipa": "ta˥˩ fan˥˩ weɪ˧˥", "syllable_count": 3, "sentences": [{"text": "警察在大范围内找那个孩子。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民在大范围内种了玉米。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要在大范围内检查水质。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山很高，他们在大范围内找了三天。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大范围里只有一家小店。", "target_word": "大范围", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在大范围内走过很多路。", "target_word": "大范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用飞机在大范围内拍照。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人在大范围内铺上了新草。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要找小狗，先在大范围内看一看，再慢慢缩小。", "target_word": "大范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在大范围内玩，妈妈有点儿担心。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指空间上很大的一块地方，常说“在大范围内”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b4015d-40c0-445c-b8d9-0067753700f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大范围", "is_correct": true, "explanation": "“大范围”指空间很大的一块地方，“在……内”后接这类空间，句意通顺。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”不是可以用来找人的空间，句子不成立。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“在……内”后要接空间或时间范围，不能接“心情”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”不是空间，“在作业内找孩子”说不通。"}], "explanations": {"大范围": "“大范围”指空间很大的一块地方，“在……内”后接这类空间，句意通顺。", "价格": "语义：“价格”不是可以用来找人的空间，句子不成立。", "心情": "搭配：“在……内”后要接空间或时间范围，不能接“心情”。", "作业": "语义：“作业”不是空间，“在作业内找孩子”说不通。"}, "sentence_index": 0, "correct_answer": "大范围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的大范围很温柔。", "explanation": "这里应该用〈性格〉。“大范围”指一块很大的地方，不能用来形容人，应说“他的性格很温柔”。"}, {"text": "这本书的大范围内容我都看过了。", "explanation": "这里应该用〈大部分〉。“大范围”指一块很大的地方，不能用来指内容的多数，应说“大部分内容”。"}, {"text": "妈妈昨天买了一个大范围，很漂亮。", "explanation": "这里应该用〈衣服〉。“大范围”指一块很大的地方，不能当作商品来买，应说“买了一件衣服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大范围", "is_correct": true, "explanation": "“大范围”指很大的一块地方，“在……内拍照”指在这片地方拍摄，句意通顺。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“在……内”后接的应是空间，“友谊”是抽象情感，不能作拍照的范围。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：“早饭”不是可以拍照的地方，句子不成立。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是可以在其中拍照的空间，句子说不通。"}], "explanations": {"大范围": "“大范围”指很大的一块地方，“在……内拍照”指在这片地方拍摄，句意通顺。", "友谊": "搭配：“在……内”后接的应是空间，“友谊”是抽象情感，不能作拍照的范围。", "早饭": "语义：“早饭”不是可以拍照的地方，句子不成立。", "钥匙": "语义：钥匙不是可以在其中拍照的空间，句子说不通。"}, "sentence_index": 6, "correct_answer": "大范围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的老师就是这个大范围。", "explanation": "这里应该用〈老师〉。“大范围”指一块很大的地方，不能指人，所以不能说“我的老师就是这个大范围”。"}, {"text": "他把大范围放进了书包。", "explanation": "这里应该用〈东西〉。“大范围”指一块很大的地方，不能装进书包，应说“那件东西”。"}, {"text": "她的大范围很好听。", "explanation": "这里应该用〈唱歌〉。“大范围”指一块很大的地方，不能用来形容声音，应说“她的唱歌很好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们在大范围的内检查，很仔细。", "corrected_sentence": "工人们在大范围内检查，很仔细。", "error_description": "多余的“的”：“内”前不能加“的”，应说“在大范围内检查”，不能说“在大范围的内检查”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "消防员大范围内搜救，很辛苦。", "corrected_sentence": "消防员在大范围内搜救，很辛苦。", "error_description": "介词缺失：“大范围内”作地点状语，前面要加“在”，应说“在大范围内搜救”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96860, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "时间", "is_correct": false, "explanation": "与“大范围”无反义关系，“时间”指时光的流逝或时段。"}, {"text": "小范围", "is_correct": true, "explanation": "“小范围”与“大范围”意义相反，指涉及的地域或影响面小，是这一义项的反义词。"}, {"text": "手机", "is_correct": false, "explanation": "与“大范围”无反义关系，“手机”是通讯工具，不涉及范围大小。"}, {"text": "河流", "is_correct": false, "explanation": "与“大范围”无反义关系，“河流”是水体，不是范围的对立面。"}], "correct_answer": "小范围", "explanations": {"时间": "与“大范围”无反义关系，“时间”指时光的流逝或时段。", "小范围": "“小范围”与“大范围”意义相反，指涉及的地域或影响面小，是这一义项的反义词。", "手机": "与“大范围”无反义关系，“手机”是通讯工具，不涉及范围大小。", "河流": "与“大范围”无反义关系，“河流”是水体，不是范围的对立面。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96860, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "课本", "is_correct": false, "explanation": "与“大范围”无反义关系，“课本”指学习用的书。"}, {"text": "小范围", "is_correct": true, "explanation": "“小范围”与“大范围”意义相反，指涉及的地域或影响面小，是这一义项的反义词。"}, {"text": "窗户", "is_correct": false, "explanation": "与“大范围”无反义关系，“窗户”是房屋的构件。"}, {"text": "钢笔", "is_correct": false, "explanation": "与“大范围”无反义关系，“钢笔”是书写工具。"}], "correct_answer": "小范围", "explanations": {"课本": "与“大范围”无反义关系，“课本”指学习用的书。", "小范围": "“小范围”与“大范围”意义相反，指涉及的地域或影响面小，是这一义项的反义词。", "窗户": "与“大范围”无反义关系，“窗户”是房屋的构件。", "钢笔": "与“大范围”无反义关系，“钢笔”是书写工具。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96860, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "广阔的区域；规模大的范围。", "primary_collocate": null, "pronunciation": "dà fàn wéi", "ipa": "ta˥˩ fan˥˩ weɪ˧˥", "syllable_count": 3, "sentences": [{"text": "昨天夜里，大范围停电让很多人没睡好。", "target_word": "大范围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天北方会有大范围的降雨。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场雪影响了大范围的交通。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想大范围推广新手机。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校做了一次大范围的检查。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大范围的雾让飞机不能起飞。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说这种病不会大范围传开。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府大范围组织了救援。", "target_word": "大范围", "complexity_tier": "T3", "furigana": "dà fànwéi", "sentence_source": "generated"}, {"text": "他们大范围地种树，希望天气变好。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个周末大范围下雨，比赛要改时间。", "target_word": "大范围", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指事情涉及的规模大、影响广，如大范围停电、降雨", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b4015d-40c0-445c-b8d9-0067753700f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大范围", "is_correct": true, "explanation": "“大范围”指规模大、涉及面广，修饰“停电”，句意通顺。"}, {"text": "语法", "is_correct": false, "explanation": "语义：“语法”不是可以停电的对象，句子说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“停电”的主语应是供电范围，不能说“钢琴停电”。"}, {"text": "孩子", "is_correct": false, "explanation": "搭配：“孩子停电”不成立，停电只能说电力或供电的范围。"}], "explanations": {"大范围": "“大范围”指规模大、涉及面广，修饰“停电”，句意通顺。", "语法": "语义：“语法”不是可以停电的对象，句子说不通。", "钢琴": "搭配：“停电”的主语应是供电范围，不能说“钢琴停电”。", "孩子": "搭配：“孩子停电”不成立，停电只能说电力或供电的范围。"}, "sentence_index": 0, "correct_answer": "大范围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把大范围装进了箱子。", "explanation": "这里应该用〈东西〉。“大范围”指广阔的区域或规模大的范围，不能装进箱子，应说“那件东西”。"}, {"text": "他一次性捐出了大范围的衣服。", "explanation": "这里应该用〈大量〉。“大范围”说涉及的范围广，不能用来修饰衣服的数量，应说“大量的衣服”。"}, {"text": "这家饭店的大范围很好吃。", "explanation": "这里应该用〈菜〉。“大范围”指广阔的区域或规模大的范围，不能用来评价食物的味道，应说“菜很好吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大范围", "is_correct": true, "explanation": "“大范围”指涉及面广，修饰“传开”，句意通顺。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是会传开的东西，句子说不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”不会“传开”，与句意不符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“传开”说的是消息、疾病等，不能用于颜色。"}], "explanations": {"大范围": "“大范围”指涉及面广，修饰“传开”，句意通顺。", "时间": "语义：“时间”不是会传开的东西，句子说不通。", "手机": "语义：“手机”不会“传开”，与句意不符。", "颜色": "搭配：“传开”说的是消息、疾病等，不能用于颜色。"}, "sentence_index": 6, "correct_answer": "大范围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对妈妈的大范围很深，从来不说。", "explanation": "这里应该用〈感情〉。“大范围”不能用来说感情的深浅，应说“他对妈妈的感情很深”。"}, {"text": "这种电池的大范围很长。", "explanation": "这里应该用〈寿命〉。“大范围”指广阔的区域或规模大的范围，不能用来说电池用得久不久，应说“寿命很长”。"}, {"text": "这个大范围很聪明，大家都很喜欢。", "explanation": "这里应该用〈孩子〉。“大范围”指广阔的区域或规模大的范围，不能用来形容人的聪明，应说“这个孩子很聪明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天晚上，一个大范围停电给我们带来很多麻烦。", "corrected_sentence": "昨天晚上，一场大范围停电给我们带来很多麻烦。", "error_description": "量词错误：“停电”是一次事件，应说“一场大范围停电”；“个”用于具体事物，不能用来数“停电”这类事件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们大范围的宣传了这次活动。", "corrected_sentence": "他们大范围地宣传了这次活动。", "error_description": "结构错误：“大范围”修饰动词“宣传”时要用“地”，不能用“的”，应说“大范围地宣传”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
