INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96872, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指妇女（口语，带有时代色彩）。", "primary_collocate": null, "pronunciation": "nǚ rén jiā", "ipa": "ny˨˩˦ ɻən˧˥ tɕia˥", "syllable_count": 3, "sentences": [{"text": "奶奶说，以前女人家很少上学。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个年代的女人家，都要在家做饭。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的女人家一起洗衣服，一起聊天。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷小时候，女人家很少坐火车。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那时候女人家一个人出远门很不容易。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外婆是个女人家，却养大了五个孩子。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在老房子里，女人家和孩子住在后面。", "target_word": "女人家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说，过去女人家结婚以后，就不再工作了。", "target_word": "女人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是个女人家，却一个人开着车去了西藏。", "target_word": "女人家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村口站着几个女人家，正在说笑。", "target_word": "女人家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "旧时口语中指妇女，带有年代感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b4015d-40c0-445c-b8d9-0067753700f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "女人家", "is_correct": true, "explanation": "正确。“女人家”指旧时的妇女，与“以前”“很少上学”的语境相合。"}, {"text": "女大学生", "is_correct": false, "explanation": "语义：大学生本身就在上学，与“很少上学”的句意矛盾。"}, {"text": "女司机", "is_correct": false, "explanation": "语义：“女司机”是现代职业，与“以前”的时代背景不符，句子说不通。"}, {"text": "女博士", "is_correct": false, "explanation": "语义：博士已接受长期教育，与“很少上学”的句意矛盾。"}], "explanations": {"女人家": "正确。“女人家”指旧时的妇女，与“以前”“很少上学”的语境相合。", "女大学生": "语义：大学生本身就在上学，与“很少上学”的句意矛盾。", "女司机": "语义：“女司机”是现代职业，与“以前”的时代背景不符，句子说不通。", "女博士": "语义：博士已接受长期教育，与“很少上学”的句意矛盾。"}, "sentence_index": 0, "correct_answer": "女人家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村口的老槐树下，坐着一个女人家，才七八岁。", "explanation": "这里应该用〈小女孩〉。女人家指成年妇女，不用来称呼七八岁的孩子。"}, {"text": "院子里有一个女人家，才三岁，正在玩泥巴。", "explanation": "这里应该用〈小女孩〉。女人家指成年妇女，不用来称呼三岁的孩子。"}, {"text": "那位老先生是个女人家，很会下棋。", "explanation": "这里应该用〈男人〉。女人家只指女性，不能用来指男性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "女人家", "is_correct": true, "explanation": "正确。“女人家”指旧时的妇女，与“在老房子里”“住在后面”的家庭语境相合。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不是人，不能和孩子住在老房子里。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，不能和孩子住在一起。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不是人，不能和孩子住在一起。"}], "explanations": {"女人家": "正确。“女人家”指旧时的妇女，与“在老房子里”“住在后面”的家庭语境相合。", "钢琴": "语义：钢琴不是人，不能和孩子住在老房子里。", "石头": "语义：石头不是人，不能和孩子住在一起。", "咖啡": "语义：咖啡不是人，不能和孩子住在一起。"}, "sentence_index": 6, "correct_answer": "女人家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个女人家，很高，常常帮大家搬东西。", "explanation": "这里应该用〈男人〉。女人家只指女性，不能用来指男性。"}, {"text": "幼儿园里有个女人家，才五岁，很爱笑。", "explanation": "这里应该用〈小朋友〉。女人家指成年妇女，不用来称呼五岁的孩子。"}, {"text": "那个小学生是个女人家，每天背着书包上学。", "explanation": "这里应该用〈小女孩〉。女人家指成年妇女，不用来称呼还在读小学的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里那只女人家每天都去河边洗衣服。", "corrected_sentence": "村里那个女人家每天都去河边洗衣服。", "error_description": "“女人家”指人，量词应用“个”。“只”用于动物，不能修饰人。正确形式为“那个女人家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老房子里那块女人家每天早上都做饭。", "corrected_sentence": "老房子里那些女人家每天早上都做饭。", "error_description": "量词错误：“块”用于成块的东西，不能修饰人。“那块女人家”应改为“那些女人家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
