INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96887, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学习一种工作需要的本领的教育。", "primary_collocate": null, "pronunciation": "zhuān yè jiào yù", "ipa": "ʈʂwan˥ jɛ˥˩ tɕjɑʊ˥˩ y˥˩", "syllable_count": 4, "sentences": [{"text": "这家学校给工人提供专业教育。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的新工人要先接受专业教育。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想当厨师，就要去参加专业教育。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专业教育教我们怎么做一份工作。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业后马上接受了专业教育。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个专业教育的时间不长，只有半年。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修车师傅是通过专业教育学会本领的。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她白天上班，晚上接受专业教育。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种专业教育让年轻人更快找到工作。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学做面包的专业教育一共有三个月。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "專業教育", "label": "繁体"}], "register": "书面", "sense_fingerprint": "学习某种工作所需本领的教育", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d5af855-8d3e-4dea-9cbd-ca81272939c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96887, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学前教育", "is_correct": false, "explanation": "语义：学前教育针对学龄前儿童，工人已经成年，不适用。"}, {"text": "专业教育", "is_correct": true, "explanation": "专业教育是学习某种工作本领的教育，与“给工人提供”相符。"}, {"text": "义务教育", "is_correct": false, "explanation": "语义：义务教育是面向适龄儿童的基础教育，不针对成年工人。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“提供”后接服务或产品，“天气”不能被学校提供。"}], "explanations": {"学前教育": "语义：学前教育针对学龄前儿童，工人已经成年，不适用。", "专业教育": "专业教育是学习某种工作本领的教育，与“给工人提供”相符。", "义务教育": "语义：义务教育是面向适龄儿童的基础教育，不针对成年工人。", "天气": "搭配：“提供”后接服务或产品，“天气”不能被学校提供。"}, "sentence_index": 0, "correct_answer": "专业教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在小学里学读写和算术，这属于专业教育。", "explanation": "这里应该用〈基础教育〉。专业教育是为某种工作学本领，小学学读写算术属于基础教育。"}, {"text": "专业教育要求每个孩子都读完九年。", "explanation": "这里应该用〈义务教育〉。专业教育只针对想学某种工作本领的人，不是每个孩子都必须读完的教育。"}, {"text": "父母在家里教孩子待人接物，这是专业教育的内容。", "explanation": "这里应该用〈家庭教育〉。专业教育是为某种工作学本领，待人接物属于家庭教育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96887, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡眠", "is_correct": false, "explanation": "语义：睡眠不是学习途径，不能让人学会修车的本领。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“通过”后接学习途径，“天气”不是学习途径。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：饥饿是身体的感受，不能使人学会修车的本领。"}, {"text": "专业教育", "is_correct": true, "explanation": "专业教育是学习某种工作本领的教育，与“通过……学会本领”相符。"}], "explanations": {"睡眠": "语义：睡眠不是学习途径，不能让人学会修车的本领。", "天气": "搭配：“通过”后接学习途径，“天气”不是学习途径。", "饥饿": "语义：饥饿是身体的感受，不能使人学会修车的本领。", "专业教育": "专业教育是学习某种工作本领的教育，与“通过……学会本领”相符。"}, "sentence_index": 6, "correct_answer": "专业教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专业教育从小培养孩子的兴趣。", "explanation": "这里应该用〈启蒙教育〉。专业教育针对想学某种工作本领的人，从小培养兴趣应说“启蒙教育”。"}, {"text": "专业教育让学生了解各门学科的基本知识，不限于一种工作。", "explanation": "这里应该用〈通识教育〉。专业教育是为某种工作学本领，学各门学科、不限于一种工作的属于通识教育。"}, {"text": "她每周末去社区画室画画，这是专业教育。", "explanation": "这里应该用〈业余爱好〉。专业教育是为某种工作学本领，周末画着玩只能说“业余爱好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想学修车，就去接受一条专业教育。", "corrected_sentence": "他想学修车，就去接受一种专业教育。", "error_description": "量词错误：“条”不能用来计量教育，应改为“种”，即“一种专业教育”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经接受了过专业教育。", "corrected_sentence": "他曾经接受过专业教育。", "error_description": "体标错误：“了”与“过”不能同时用在动词后。应去掉“了”，说“接受过专业教育”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
