INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96888, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "培养某一领域专门人才的教育。", "primary_collocate": null, "pronunciation": "zhuān yè jiào yù", "ipa": "ʈʂwan˥ jɛ˥˩ tɕjɑʊ˥˩ y˥˩", "syllable_count": 4, "sentences": [{"text": "大学里的专业教育培养各行各业的人才。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要先接受多年的专业教育。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校很重视专业教育。", "target_word": "专业教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专业教育和普通教育不一样。", "target_word": "专业教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家要办好专业教育，培养更多的工程师。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有受过专业教育，所以不能当律师。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的专业教育要有好老师。", "target_word": "专业教育", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的专业教育分成很多方向。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过四年的专业教育，她成了护士。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专业教育让学生在某个领域里更有能力。", "target_word": "专业教育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "專業教育", "label": "繁体"}], "register": "书面", "sense_fingerprint": "培养某一领域专门人才的教育", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d5af855-8d3e-4dea-9cbd-ca81272939c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学前教育", "is_correct": false, "explanation": "语义：学前教育面向学龄前儿童，与“大学里”的语境不符。"}, {"text": "专业教育", "is_correct": true, "explanation": "专业教育指培养某一领域专门人才的教育，与“培养各行各业的人才”相符。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“学历”指文凭资格，不能作“培养”的主语。"}, {"text": "义务教育", "is_correct": false, "explanation": "语义：义务教育是面向所有适龄儿童的基础教育，不以培养专门人才为目的。"}], "explanations": {"学前教育": "语义：学前教育面向学龄前儿童，与“大学里”的语境不符。", "专业教育": "专业教育指培养某一领域专门人才的教育，与“培养各行各业的人才”相符。", "学历": "搭配：“学历”指文凭资格，不能作“培养”的主语。", "义务教育": "语义：义务教育是面向所有适龄儿童的基础教育，不以培养专门人才为目的。"}, "sentence_index": 0, "correct_answer": "专业教育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "专业教育要让孩子打好知识的根基。", "explanation": "这里应该用〈基础教育〉。专业教育面向已确定职业方向的人，不用于为孩子打基础。"}, {"text": "专业教育是每个公民都要接受的。", "explanation": "这里应该用〈义务教育〉。专业教育只面向有特定职业需要的人，并非人人必须接受。"}, {"text": "她每周末去画室画画，这是专业教育。", "explanation": "这里应该用〈业余爱好〉。专业教育是为某个领域培养专门人才，周末画着玩只能说“业余爱好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气是自然环境，不是需要老师培养的内容。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不存在靠老师培养的问题。"}, {"text": "专业教育", "is_correct": true, "explanation": "专业教育需要教师指导，与“要有好老师”相符。"}, {"text": "交通", "is_correct": false, "explanation": "搭配：“好老师”指教书育人的人，不能与“交通”搭配。"}], "explanations": {"空气": "语义：空气是自然环境，不是需要老师培养的内容。", "天气": "语义：天气是自然现象，不存在靠老师培养的问题。", "专业教育": "专业教育需要教师指导，与“要有好老师”相符。", "交通": "搭配：“好老师”指教书育人的人，不能与“交通”搭配。"}, "sentence_index": 6, "correct_answer": "专业教育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专业教育让学生接触各个学科，不局限于一个方向。", "explanation": "这里应该用〈通识教育〉。专业教育集中在某一领域，与“接触各个学科，不局限于一个方向”相反。"}, {"text": "专业教育要以游戏为主，让孩子快乐成长。", "explanation": "这里应该用〈学前教育〉。专业教育面向已确定职业方向的人，不适用于以游戏为主的幼儿阶段。"}, {"text": "学校每周组织一次体育活动，这属于专业教育。", "explanation": "这里应该用〈素质教育〉。专业教育是为某个领域培养专门人才，体育活动属于素质教育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校提供一条专业教育。", "corrected_sentence": "学校提供一种专业教育。", "error_description": "量词错误：“条”用于线状、细长的东西，不能计量教育。应改为“种”，即“一种专业教育”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他毕业后又接受了过专业教育。", "corrected_sentence": "他毕业后又接受了专业教育。", "error_description": "体标错误：“了”与“过”不能同时用在同一个动词后。应去掉“过”，说“接受了专业教育”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
