INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96891, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手上最小的那根手指。", "primary_collocate": null, "pronunciation": "xiǎo zhǐ", "ipa": "ɕiau˨˩˦ ʈʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我的小指受伤了。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的小指比大拇指短得多。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用小指轻轻碰了一下我。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上最小的一根是小指。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的小指又小又软。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心夹到了小指。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把戒指戴在了小指上。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写字时，小指要放在纸上。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的小指上有一个小伤口。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸出小指，和我拉钩。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "左小指", "label": "复合"}], "register": "中性", "sense_fingerprint": "小指：手上最小的那根手指", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b4015d-40c0-445c-b8d9-0067753700f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96891, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小指", "is_correct": true, "explanation": "正确。小指指手上最小的那根手指。"}, {"text": "小枝", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是小的树枝。"}, {"text": "小职", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是小职位。"}, {"text": "小智", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是小聪明。"}], "explanations": {"小指": "正确。小指指手上最小的那根手指。", "小枝": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是小的树枝。", "小职": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是小职位。", "小智": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是小聪明。"}, "sentence_index": null, "correct_answer": "小指"}, "level_3": {"options": [{"text": "小指", "is_correct": true, "explanation": "正确。“受伤”的对象是身体部位，小指是手上的手指。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是身体部位，不会“受伤”。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不会受伤。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不会“受伤”。"}], "explanations": {"小指": "正确。“受伤”的对象是身体部位，小指是手上的手指。", "天气": "语义：天气不是身体部位，不会“受伤”。", "饭": "语义：饭不会受伤。", "作业": "语义：作业不会“受伤”。"}, "sentence_index": 0, "correct_answer": "小指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手上有五根小指。", "explanation": "这里应该用〈手指〉。“五根”数的是整只手的手指，小指只是其中一根。"}, {"text": "他有一只小指受伤了。", "explanation": "这里误把小指当成〈手〉那样用“只”计量。“只”用于手、脚等，手指应用“根”。"}, {"text": "他把小指戴上了。", "explanation": "这里应该用〈手套〉。“戴”搭配手套、戒指，小指是身体部位，不能被戴上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96891, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小指", "is_correct": true, "explanation": "正确。小指指手上最小的那根手指。"}, {"text": "小知", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是微小的见识。"}, {"text": "小史", "is_correct": false, "explanation": "shǐ（第三声）与 zhǐ（第三声）仅声母不同（sh／zh），意思是简略的史书。"}, {"text": "小智", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是小聪明。"}], "explanations": {"小指": "正确。小指指手上最小的那根手指。", "小知": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是微小的见识。", "小史": "shǐ（第三声）与 zhǐ（第三声）仅声母不同（sh／zh），意思是简略的史书。", "小智": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是小聪明。"}, "sentence_index": null, "correct_answer": "小指"}, "level_3": {"options": [{"text": "小指", "is_correct": true, "explanation": "正确。戒指戴在手指上，小指是手指。"}, {"text": "肩膀", "is_correct": false, "explanation": "搭配：戒指一般戴在手指上，不戴在肩膀上。"}, {"text": "嘴巴", "is_correct": false, "explanation": "语义：戒指不能戴在嘴上。"}, {"text": "膝盖", "is_correct": false, "explanation": "语义：戒指不能戴在膝盖上。"}], "explanations": {"小指": "正确。戒指戴在手指上，小指是手指。", "肩膀": "搭配：戒指一般戴在手指上，不戴在肩膀上。", "嘴巴": "语义：戒指不能戴在嘴上。", "膝盖": "语义：戒指不能戴在膝盖上。"}, "sentence_index": 6, "correct_answer": "小指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他穿上了小指，准备出门。", "explanation": "这里应该用〈鞋子〉。“穿”搭配鞋袜、衣服，小指不能被穿。"}, {"text": "他关上了小指，然后睡觉。", "explanation": "这里应该用〈门〉。“关”搭配门、窗，小指不能被关上。"}, {"text": "他闭上了小指，想了一会儿。", "explanation": "这里应该用〈眼睛〉。“闭”搭配眼睛、嘴，小指不能闭上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的一只小指受伤了。", "corrected_sentence": "他的一根小指受伤了。", "error_description": "“小指”的量词用“根”，不用“只”。正确：他的一根小指受伤了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我摔了一跤，右手的那块小指肿了。", "corrected_sentence": "我摔了一跤，右手的那根小指肿了。", "error_description": "量词错误：“小指”的量词用“根”，不用“块”（“块”用于块状的东西）。正确：我摔了一跤，右手的那根小指肿了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
