INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "手的第五指，最短最细的手指。", "primary_collocate": null, "pronunciation": "xiǎo zhǐ", "ipa": "ɕiau˨˩˦ ʈʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "五根手指中，小指最细。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小指是手上的第五根手指。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的小指比无名指短一点。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了我左手的小指。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹钢琴时，小指不太有力。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的左手小指戴着一枚戒指。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我摔了一跤，小指肿了。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手冷的时候，小指先发麻。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根小指又短又细。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的右手小指弯不了。", "target_word": "小指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "右小指", "label": "复合"}], "register": "中性", "sense_fingerprint": "小指：手的第五指，最短最细", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b4015d-40c0-445c-b8d9-0067753700f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96892, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小指", "is_correct": true, "explanation": "正确。小指是手的第五指，最短最细。"}, {"text": "小职", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是小职位。"}, {"text": "小智", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是小聪明。"}, {"text": "小枝", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是小的树枝。"}], "explanations": {"小指": "正确。小指是手的第五指，最短最细。", "小职": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是小职位。", "小智": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是小聪明。", "小枝": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是小的树枝。"}, "sentence_index": null, "correct_answer": "小指"}, "level_3": {"options": [{"text": "小指", "is_correct": true, "explanation": "正确。“五根手指”之中最细的是小指。"}, {"text": "手掌", "is_correct": false, "explanation": "语义：手掌不是“五根手指”之一。"}, {"text": "手腕", "is_correct": false, "explanation": "语义：手腕不是手指，不属于“五根手指”。"}, {"text": "指甲", "is_correct": false, "explanation": "搭配：“五根手指中”只与手指名称搭配，指甲不是手指。"}], "explanations": {"小指": "正确。“五根手指”之中最细的是小指。", "手掌": "语义：手掌不是“五根手指”之一。", "手腕": "语义：手腕不是手指，不属于“五根手指”。", "指甲": "搭配：“五根手指中”只与手指名称搭配，指甲不是手指。"}, "sentence_index": 0, "correct_answer": "小指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一双手有十根小指。", "explanation": "这里应该用〈手指〉。一只手有五根手指，小指只是其中一根，不能数作十根。"}, {"text": "医生检查了我左手的一只小指。", "explanation": "这里误把小指当成〈手〉那样用“只”计量。“只”用于手，单根手指应用“根”。"}, {"text": "我每天早上穿小指。", "explanation": "这里应该用〈袜子〉。“穿”搭配衣服、鞋袜，小指是身体部位，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
