INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的一只小指比别人的细得多。", "corrected_sentence": "我的一根小指比别人的细得多。", "error_description": "“小指”的量词用“根”，不用“只”。正确：我的一根小指比别人的细得多。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我摔了一跤，左手的那块小指有点红。", "corrected_sentence": "我摔了一跤，左手的那根小指有点红。", "error_description": "量词错误：“小指”的量词用“根”，不用“块”（“块”用于块状的东西）。正确：我摔了一跤，左手的那根小指有点红。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
