INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96901, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "黑黑的、甜甜的，小朋友爱吃的糖。", "primary_collocate": null, "pronunciation": "qiǎo kè lì", "ipa": "tɕʰiau˨˩˦ kʰɤ˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "小明爱吃巧克力。", "target_word": "巧克力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "巧克力黑黑的，甜甜的。", "target_word": "巧克力", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟吃完巧克力，嘴巴黑黑的。", "target_word": "巧克力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最爱那块又黑又甜的巧克力。", "target_word": "巧克力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生日会上，小朋友抢着吃黑黑的巧克力。", "target_word": "巧克力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巧克力在嘴里慢慢化开，真甜！", "target_word": "巧克力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹把最爱的巧克力藏在书包里，不给哥哥。", "target_word": "巧克力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的口袋里有一块黑黑的巧克力。", "target_word": "巧克力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，妹妹拿着巧克力，笑得很开心。", "target_word": "巧克力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圣诞节，小朋友在袜子里找到了巧克力。", "target_word": "巧克力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "盒", "label": "量词"}, {"form": "黑巧克力", "label": "复合"}], "register": "口语", "sense_fingerprint": "小朋友口中黑黑的、甜甜的、爱吃的糖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44b4015d-40c0-445c-b8d9-0067753700f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96901, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巧克力", "is_correct": true, "explanation": "正确。“爱吃”的对象是小朋友爱吃的甜食，“巧克力”与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能吃，“爱吃石头”与常识冲突。"}, {"text": "老师", "is_correct": false, "explanation": "配价：“吃”的宾语应是食物，“老师”是人，不能作为宾语。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花不是食物，小明不会“爱吃”棉花。"}], "explanations": {"巧克力": "正确。“爱吃”的对象是小朋友爱吃的甜食，“巧克力”与句意相符。", "石头": "语义：石头不能吃，“爱吃石头”与常识冲突。", "老师": "配价：“吃”的宾语应是食物，“老师”是人，不能作为宾语。", "棉花": "语义：棉花不是食物，小明不会“爱吃”棉花。"}, "sentence_index": 0, "correct_answer": "巧克力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上用巧克力刷牙。", "explanation": "这里应该用〈牙膏〉。巧克力是食品，不能用来刷牙。"}, {"text": "爷爷每天用巧克力擦皮鞋。", "explanation": "这里应该用〈鞋油〉。巧克力是食品，不能用来擦皮鞋。"}, {"text": "老师让我们用巧克力写作业。", "explanation": "这里应该用〈铅笔〉。巧克力是食品，不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巧克力", "is_correct": true, "explanation": "正确。“巧克力”是可以藏在书包里、又能给哥哥的小东西，与句意相合。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子太大，不可能藏在书包里。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴太大，装不进书包，与句意冲突。"}, {"text": "妈妈", "is_correct": false, "explanation": "配价：“藏在书包里”的对象不能是人，“妈妈”不能作为这里的宾语。"}], "explanations": {"巧克力": "正确。“巧克力”是可以藏在书包里、又能给哥哥的小东西，与句意相合。", "房子": "语义：房子太大，不可能藏在书包里。", "钢琴": "语义：钢琴太大，装不进书包，与句意冲突。", "妈妈": "配价：“藏在书包里”的对象不能是人，“妈妈”不能作为这里的宾语。"}, "sentence_index": 6, "correct_answer": "巧克力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把巧克力插进门锁里，想开门。", "explanation": "这里应该用〈钥匙〉。巧克力是食品，不能用来开门。"}, {"text": "妈妈把巧克力放进洗衣机里洗衣服。", "explanation": "这里应该用〈洗衣粉〉。巧克力是食品，不能用来洗衣服。"}, {"text": "他把巧克力挂在窗户上，遮挡阳光。", "explanation": "这里应该用〈窗帘〉。巧克力是食品，不能用来遮挡阳光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹偷偷吃了一只巧克力。", "corrected_sentence": "妹妹偷偷吃了一块巧克力。", "error_description": "“巧克力”是食品，量词应用“块”。“只”用于动物等，不能用来修饰巧克力，应说“一块巧克力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹手里拿着黑黑巧克力。", "corrected_sentence": "妹妹手里拿着黑黑的巧克力。", "error_description": "重叠形容词“黑黑”修饰名词时要加“的”，应说“黑黑的巧克力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0865ac11-2e8d-4f3e-ae47-68e72d86cac4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
