INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96903, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "长得很好看的男孩子或男人。", "primary_collocate": null, "pronunciation": "shuài gē", "ipa": "ʂuaɪ˥˩ kɤ˥", "syllable_count": 2, "sentences": [{"text": "他长得高高的，是个帅哥。", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们班有三个帅哥。", "target_word": "帅哥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个帅哥是我的大学同学。", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影里的帅哥穿着白衬衫。", "target_word": "帅哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就是学校里有名的帅哥。", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "走在前面的那个帅哥是谁？", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟长大后变成了一个帅哥。", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不但是帅哥，而且很会唱歌。", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "女孩们都想认识这位帅哥。", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片上的帅哥笑得很开心。", "target_word": "帅哥", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "帅哥们", "label": "复数"}, {"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "小帅哥", "label": "复合"}, {"form": "帥哥", "label": "繁体"}], "register": "口语", "sense_fingerprint": "指长得好看的年轻男子本人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4c0234-abf6-4c9d-be01-e4d86c3bd9fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96903, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "帅哥", "is_correct": true, "explanation": "正确。“帅哥”指长得英俊的男子，与“他”和“长得高高的”的描述相符。"}, {"text": "矮子", "is_correct": false, "explanation": "体貌：“长得高高的”与“矮子”的身高描述相矛盾。"}, {"text": "美女", "is_correct": false, "explanation": "语义：“他”是男子，“美女”指女子，不能用来指他。"}, {"text": "老太太", "is_correct": false, "explanation": "语义：“他”是男子，“老太太”指年长女性，不能指他。"}], "explanations": {"帅哥": "正确。“帅哥”指长得英俊的男子，与“他”和“长得高高的”的描述相符。", "矮子": "体貌：“长得高高的”与“矮子”的身高描述相矛盾。", "美女": "语义：“他”是男子，“美女”指女子，不能用来指他。", "老太太": "语义：“他”是男子，“老太太”指年长女性，不能指他。"}, "sentence_index": 0, "correct_answer": "帅哥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个女孩是我们班的帅哥。", "explanation": "这里应该用〈美女〉。“帅哥”指男子，指女子要用“美女”。"}, {"text": "我妈妈年轻时是村里有名的帅哥。", "explanation": "这里用“帅哥”形容一位女性。“帅哥”指长得英俊的男子，形容女性应用〈美女〉。"}, {"text": "那位女医生是医院的帅哥。", "explanation": "这里把“帅哥”用在女性身上。“帅哥”指男子，指女性应用〈美女〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "帅哥", "is_correct": true, "explanation": "正确。“一个帅哥”指长得英俊的男子，与“我弟弟”的语境相符。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：“长大后”说明已不再是小孩，“孩子”与此语境矛盾。"}, {"text": "女儿", "is_correct": false, "explanation": "语义：“我弟弟”是男性，“女儿”指女性子女，不能指他。"}, {"text": "小男孩", "is_correct": false, "explanation": "搭配：“长大后”后面不能接指幼年的“小男孩”，时间搭配冲突。"}], "explanations": {"帅哥": "正确。“一个帅哥”指长得英俊的男子，与“我弟弟”的语境相符。", "孩子": "语义：“长大后”说明已不再是小孩，“孩子”与此语境矛盾。", "女儿": "语义：“我弟弟”是男性，“女儿”指女性子女，不能指他。", "小男孩": "搭配：“长大后”后面不能接指幼年的“小男孩”，时间搭配冲突。"}, "sentence_index": 6, "correct_answer": "帅哥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是我们公司最有名的帅哥。", "explanation": "这里应该用〈美女〉。“她”指女性，“帅哥”只指男子。"}, {"text": "我表姐是我们学校出名的帅哥。", "explanation": "这里把“帅哥”用在女性身上。“帅哥”指长得英俊的男子，指女性应用〈美女〉。"}, {"text": "我舅妈是我们那一带出了名的帅哥。", "explanation": "这里用“帅哥”形容一位女性。“帅哥”指长得英俊的男子，形容女性应用〈美女〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只帅哥站在门口，很显眼。", "corrected_sentence": "那位帅哥站在门口，很显眼。", "error_description": "“帅哥”指人，量词应用“位”或“个”，不能用“只”。错误形式：那只帅哥；正确形式：那位帅哥。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他虽然是个一帅哥，但是脾气很好。", "corrected_sentence": "他虽然是一个帅哥，但是脾气很好。", "error_description": "数量短语语序颠倒：“一个”应放在“帅哥”前面，不能写成“个一”。错误形式：是个一帅哥；正确形式：是一个帅哥。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
