INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96915, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "紧靠着你家的那一家。", "primary_collocate": null, "pronunciation": "gé bì", "ipa": "kɤ˧˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "隔壁住着一对老夫妻。", "target_word": "隔壁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔壁常常送水果给我们。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家隔壁有一只大黑狗。", "target_word": "隔壁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "隔壁的孩子今年上大学了。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天隔壁搬来了新邻居。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "隔壁一家人都很热情。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "隔壁的王阿姨请我们吃饭。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "隔壁的男孩每天和我一起上学。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "隔壁家的孩子哭了一晚上，没人睡好。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们和隔壁一家的关系特别好。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "隔壁邻居", "label": "复合"}], "register": "口语", "sense_fingerprint": "紧挨着自己家的邻居人家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d5af855-8d3e-4dea-9cbd-ca81272939c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96915, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "语义：花园是种花草的地方，不住人。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是家具，不是住所，不能住着人家。"}, {"text": "隔壁", "is_correct": true, "explanation": "隔壁指紧挨着自己家的人家，与“住着一对老夫妻”相符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不是住所。"}], "explanations": {"花园": "语义：花园是种花草的地方，不住人。", "书桌": "语义：书桌是家具，不是住所，不能住着人家。", "隔壁": "隔壁指紧挨着自己家的人家，与“住着一对老夫妻”相符。", "教室": "语义：教室是上课的地方，不是住所。"}, "sentence_index": 0, "correct_answer": "隔壁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的隔壁住在附近的街区，我们平时很少来往。", "explanation": "这里应该用〈邻居〉。“隔壁”要求紧靠着你家，住在附近的街区应说“邻居”。"}, {"text": "隔壁一家住在十里以外，我们要坐车才能见面。", "explanation": "这里应该用〈远邻〉。“隔壁”指紧靠着你家的人家，住在十里以外只能说“远邻”。"}, {"text": "我家的隔壁住在楼上，我们经常在楼梯上碰面。", "explanation": "这里应该用〈上层邻居〉。“隔壁”指同一层紧靠着的人家，住在楼上应说“上层邻居”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96915, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水果", "is_correct": false, "explanation": "搭配：「水果」是食物，不能修饰人物「王阿姨」。"}, {"text": "地下", "is_correct": false, "explanation": "语义：“地下”指地面以下，王阿姨不会住在那里请我们吃饭。"}, {"text": "隔壁", "is_correct": true, "explanation": "隔壁指紧挨着我家的人家，与“请我们吃饭”的亲近关系相符。"}, {"text": "荒岛", "is_correct": false, "explanation": "搭配：“荒岛”没有居民，不能与“王阿姨”组合。"}], "explanations": {"水果": "搭配：「水果」是食物，不能修饰人物「王阿姨」。", "地下": "语义：“地下”指地面以下，王阿姨不会住在那里请我们吃饭。", "隔壁": "隔壁指紧挨着我家的人家，与“请我们吃饭”的亲近关系相符。", "荒岛": "搭配：“荒岛”没有居民，不能与“王阿姨”组合。"}, "sentence_index": 6, "correct_answer": "隔壁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "隔壁一家在国外生活，我们却每天一起吃饭。", "explanation": "这里应该用〈远方的朋友〉。“隔壁”要求紧靠着你家，住在国外的人不能称为隔壁。"}, {"text": "我们和隔壁一家隔着山，每年只见一次面。", "explanation": "这里应该用〈远亲〉。“隔壁”要求紧靠着你家，隔着山的人家只能说“远亲”。"}, {"text": "隔壁一家住在我们楼下，我们却每天在楼道里碰面。", "explanation": "这里应该用〈下层邻居〉。“隔壁”指同一层紧靠着的人家，住在楼下应说“下层邻居”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96915, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "隔壁住在一位年轻的画家。", "corrected_sentence": "隔壁住着一位年轻的画家。", "error_description": "体标错误：存在句中表示持续状态应用“着”，应说“隔壁住着一位画家”，不能说“住在一位画家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96915, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们和隔壁一只人成了好朋友。", "corrected_sentence": "我们和隔壁一家人成了好朋友。", "error_description": "量词错误：“一家人”中的“家”不能换成“只”。“只”用于动物等，不能计量人，应说“一家人”，即“我们和隔壁一家人成了好朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
