INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96916, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "紧挨着的另一间房间或屋子。", "primary_collocate": null, "pronunciation": "gé bì", "ipa": "kɤ˧˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "隔壁是一间小教室。", "target_word": "隔壁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的房间在你的隔壁。", "target_word": "隔壁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "隔壁的房间很安静。", "target_word": "隔壁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会议室的隔壁就是办公室。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "隔壁房间里有人在唱歌。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你去隔壁拿一把椅子。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们住的酒店，隔壁房间住着一个小孩。", "target_word": "隔壁", "complexity_tier": "T3", "furigana": "wǒmen zhù de jiǔdiàn, gébì fángjiān zhùzhe yí ge xiǎohái.", "sentence_source": "generated"}, {"text": "隔壁的教室今天没有人上课。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为隔壁在装修，所以白天很吵。", "target_word": "隔壁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把桌子搬到了隔壁的房间。", "target_word": "隔壁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隔壁房间", "label": "复合"}], "register": "口语", "sense_fingerprint": "相邻的房间或屋子，指紧挨着的另一间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d5af855-8d3e-4dea-9cbd-ca81272939c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96916, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是教室。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：卧室用于睡觉，与“小教室”相矛盾。"}, {"text": "隔壁", "is_correct": true, "explanation": "隔壁指紧挨着的房间，“是一间小教室”指这个房间，相符。"}, {"text": "走廊", "is_correct": false, "explanation": "搭配：“一间”用于房间，不能用来计量走廊。"}], "explanations": {"厨房": "语义：厨房是做饭的地方，不是教室。", "卧室": "语义：卧室用于睡觉，与“小教室”相矛盾。", "隔壁": "隔壁指紧挨着的房间，“是一间小教室”指这个房间，相符。", "走廊": "搭配：“一间”用于房间，不能用来计量走廊。"}, "sentence_index": 0, "correct_answer": "隔壁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的隔壁在十公里外的小区，我们坐车过去要半个小时。", "explanation": "这里应该用〈远处〉。“隔壁”要求紧挨着，相隔十公里的小区只能说“远处”，不能说隔壁。"}, {"text": "学校在我家隔壁，中间隔着一条河。", "explanation": "这里应该用〈附近〉。学校与我家中间隔着河，只能说“附近”，“隔壁”指紧挨着的房间或人家。"}, {"text": "教学楼和图书馆之间隔着一个操场，图书馆在教学楼的隔壁。", "explanation": "这里应该用〈旁边〉。两处之间隔着操场时，只能说“旁边”，不能说“隔壁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是住宿的房间，不住人。"}, {"text": "仓库", "is_correct": false, "explanation": "语义：仓库是存放货物的地方，不是住人的房间。"}, {"text": "隔壁", "is_correct": true, "explanation": "隔壁指紧挨着的房间，与“我们住的酒店”的语境相符。"}, {"text": "大堂", "is_correct": false, "explanation": "搭配：“大堂”是公共空间，不能与“房间”组合成住宿的处所。"}], "explanations": {"厨房": "语义：厨房不是住宿的房间，不住人。", "仓库": "语义：仓库是存放货物的地方，不是住人的房间。", "隔壁": "隔壁指紧挨着的房间，与“我们住的酒店”的语境相符。", "大堂": "搭配：“大堂”是公共空间，不能与“房间”组合成住宿的处所。"}, "sentence_index": 6, "correct_answer": "隔壁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的房间是我的隔壁，中间隔着一层地板。", "explanation": "这里应该用〈楼下〉。“隔壁”指同一层并排的房间，房间在楼下、中间隔着楼板时应说“楼下”。"}, {"text": "我的房间是你的隔壁，我们的门正对着，中间隔着一条走廊。", "explanation": "这里应该用〈对门〉。“隔壁”指共用墙壁的房间，门对着门、隔着走廊时应说“对门”。"}, {"text": "他家就在我家的上一层，我们两家是隔壁。", "explanation": "这里应该用〈楼上〉。“隔壁”指同一层紧靠着的房间，房间在上层时应说“楼上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "隔壁在一间空房间。", "corrected_sentence": "隔壁有一间空房间。", "error_description": "动词错误：“在”表示位于，不能引出存在的物；表示存在应用“有”，应说“隔壁有一间空房间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的书房就在在隔壁。", "corrected_sentence": "他的书房就在隔壁。", "error_description": "重复错误：“在”不能叠用，应只说“在隔壁”。多出的第二个“在”应删去，即“他的书房就在隔壁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
