INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96917, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情做好以后，还留下来的办法。", "primary_collocate": null, "pronunciation": "hòu shǒu", "ipa": "xoʊ˥˩ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "事情办好了，他还留着一个后手。", "target_word": "后手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同签好了，我们还有后手。", "target_word": "后手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "计划成功了，可是他还是留了后手。", "target_word": "后手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事做完以后，你还有什么后手？", "target_word": "后手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "方案定好以后，经理还留着一个后手。", "target_word": "后手", "complexity_tier": "T3", "furigana": "fāng àn dìng hǎo yǐ hòu, jīng lǐ hái liú zhe yí ge hòu shǒu", "sentence_source": "generated"}, {"text": "项目验收通过后，团队还留着一个后手。", "target_word": "后手", "complexity_tier": "T3", "furigana": "xiàng mù yàn shōu tōng guò hòu, tuán duì hái liú zhe yí ge hòu shǒu", "sentence_source": "generated"}, {"text": "他赢了比赛，但没有忘记准备后手。", "target_word": "后手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，教练还藏着一个后手。", "target_word": "后手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情都安排好了，我们还留有后手。", "target_word": "后手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司做完这个项目，仍然有后手。", "target_word": "后手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "後手", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情办完之后仍然留着的备用办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4c0234-abf6-4c9d-be01-e4d86c3bd9fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96917, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后手", "is_correct": true, "explanation": "正确。“留着一个后手”指事情办完后仍保留的备用办法，与“事情办好了”相符。"}, {"text": "噩梦", "is_correct": false, "explanation": "语义：“噩梦”不是可以留着备用的办法，与“事情办好了”的语境不合。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“留着”不搭配“性格”，应说“保持性格”。"}, {"text": "同学", "is_correct": false, "explanation": "语义：“同学”是人，不能作为留着的东西，这句话的语境说不通。"}], "explanations": {"后手": "正确。“留着一个后手”指事情办完后仍保留的备用办法，与“事情办好了”相符。", "噩梦": "语义：“噩梦”不是可以留着备用的办法，与“事情办好了”的语境不合。", "性格": "搭配：“留着”不搭配“性格”，应说“保持性格”。", "同学": "语义：“同学”是人，不能作为留着的东西，这句话的语境说不通。"}, "sentence_index": 0, "correct_answer": "后手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事做完以后，他送给了朋友一个后手。", "explanation": "这里应该用〈礼物〉。“后手”指留作后用的办法，不是可以送给别人的东西。"}, {"text": "这件事做完以后，两家公司爆发了后手。", "explanation": "这里应该用〈纠纷〉。“后手”指事情做完以后留下的办法，不指双方的争执。"}, {"text": "这件事做完以后，他赢得了很高的后手。", "explanation": "这里应该用〈赞誉〉。“后手”指事情做完以后留下的办法，不是可以赢得的荣誉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后手", "is_correct": true, "explanation": "正确。“没有忘记准备后手”指事情办完后仍留作后用的办法，与“赢了比赛”的语境相符。"}, {"text": "冠军", "is_correct": false, "explanation": "搭配：“准备”不搭配“冠军”，“冠军”是已取得的名次，不能预先准备。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：赢了比赛的语境中“准备眼泪”与事实和语义都不合。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不能被准备，放在这里语义说不通。"}], "explanations": {"后手": "正确。“没有忘记准备后手”指事情办完后仍留作后用的办法，与“赢了比赛”的语境相符。", "冠军": "搭配：“准备”不搭配“冠军”，“冠军”是已取得的名次，不能预先准备。", "眼泪": "语义：赢了比赛的语境中“准备眼泪”与事实和语义都不合。", "月亮": "语义：“月亮”不能被准备，放在这里语义说不通。"}, "sentence_index": 6, "correct_answer": "后手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "项目做完后，公司收获了很多后手。", "explanation": "这里应该用〈成果〉。“后手”指留作后用的办法，不能被“收获”。"}, {"text": "项目做完后，公司举行了一个后手。", "explanation": "这里应该用〈庆典〉。“后手”指留作后用的办法，不是可以举行的活动。"}, {"text": "项目做完后，公司陷入了财务后手。", "explanation": "这里应该用〈危机〉。“后手”指事情做完后留下的办法，不指困境或危险的状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工作结束后，他还留着个一后手。", "corrected_sentence": "工作结束后，他还留着一个后手。", "error_description": "数量短语语序颠倒：“一个”应放在名词“后手”前面，不能写成“个一”。错误形式：留着个一后手；正确形式：留着一个后手。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "项目结束后，经理还留着一颗后手，以防万一。", "corrected_sentence": "项目结束后，经理还留着一个后手，以防万一。", "error_description": "“后手”的量词应用“个”，不能用“颗”（“颗”用于粒状的小东西）。错误形式：一颗后手；正确形式：一个后手。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
