INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96937, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "买的人和卖的人说好了，东西卖出去了。", "primary_collocate": null, "pronunciation": "chéng jiāo", "ipa": "tʂʰɤŋ˧˥ tɕjɑʊ˥", "syllable_count": 2, "sentences": [{"text": "我跟他讲了半天价，终于成交了。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部旧手机五百块成交。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说：“八十块，成交！”", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买那辆自行车，可是价钱没谈好，没成交。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说两百块，我说：“成交！”", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天早上市场里成交了不少水果。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把价钱谈好了，马上就成交了。", "target_word": "成交", "complexity_tier": "T3", "furigana": "chéngjiāo", "sentence_source": "generated"}, {"text": "那幅画昨天终于成交了。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧书卖给我，十块钱成交。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱太高，买的人不愿意，所以没有成交。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成交了", "label": "体标（了）"}, {"form": "成交过", "label": "体标（过）"}, {"form": "成交量", "label": "复合词"}, {"form": "成交价", "label": "复合词"}], "register": "中性", "sense_fingerprint": "讲好价钱，东西卖出去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882879db-4624-43a3-aabb-0b34d7693f04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96937, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与讲价无关，“我跟他讲了半天价，终于结婚了”说不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”后要带宾语，句中没有交代送什么，单独说“终于送了”不完整。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”与讲价没有关系，句子说不通。"}, {"text": "成交", "is_correct": true, "explanation": "“成交”表示讲好价钱、东西卖出去，正好接“讲了半天价”之后的结果。"}], "explanations": {"结婚": "语义：“结婚”与讲价无关，“我跟他讲了半天价，终于结婚了”说不通。", "送": "配价：“送”后要带宾语，句中没有交代送什么，单独说“终于送了”不完整。", "下雨": "语义：“下雨”与讲价没有关系，句子说不通。", "成交": "“成交”表示讲好价钱、东西卖出去，正好接“讲了半天价”之后的结果。"}, "sentence_index": 0, "correct_answer": "成交"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这本书送给我，我们很快就成交了。", "explanation": "这里应该用〈赠送〉。“成交”指买卖双方谈妥、东西卖出去了，赠送不涉及买卖、没有讲价，不能说“成交”。"}, {"text": "这个果子已经成交了，可以吃了。", "explanation": "这里应该用〈成熟〉。“成熟”指果实长成，“成交”指买卖达成，说果子“成交了”不通。"}, {"text": "我们只是随便聊聊，就已经成交了。", "explanation": "这里应该用〈闲聊〉。“成交”指买卖双方谈妥，随便闲聊不涉及买卖，不能说“成交”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96937, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡", "is_correct": false, "explanation": "语义：“睡”与谈好价钱没有关系，“我们把价钱谈好了，马上就睡了”说不通。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”与谈价钱无关，句子说不通。"}, {"text": "颁布", "is_correct": false, "explanation": "语域：“颁布”是正式的公文用语，用在这句口语叙述里很不协调，而且与“谈好价钱”也不合逻辑。"}, {"text": "成交", "is_correct": true, "explanation": "“成交”表示讲好价钱、东西卖出去，正好接“把价钱谈好了”之后的结果。"}], "explanations": {"睡": "语义：“睡”与谈好价钱没有关系，“我们把价钱谈好了，马上就睡了”说不通。", "感冒": "语义：“感冒”与谈价钱无关，句子说不通。", "颁布": "语域：“颁布”是正式的公文用语，用在这句口语叙述里很不协调，而且与“谈好价钱”也不合逻辑。", "成交": "“成交”表示讲好价钱、东西卖出去，正好接“把价钱谈好了”之后的结果。"}, "sentence_index": 6, "correct_answer": "成交"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次讲座很精彩，今天终于成交了。", "explanation": "这里应该用〈结束〉。“成交”只用于买卖达成，讲座结束不能说“成交”。"}, {"text": "他跑完马拉松，一到终点就成交了。", "explanation": "这里应该用〈到达〉。比赛跑到终点不是买卖，不能说“成交”。"}, {"text": "我们努力了三个月，这个项目终于成交了。", "explanation": "这里应该用〈成功〉。“成交”只用于买卖达成，项目取得成功要说“成功”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那台旧电脑以两千块被成交了。", "corrected_sentence": "那台旧电脑以两千块成交了。", "error_description": "错误：“被成交”；正确：“成交”。“成交”表示买卖双方谈妥、东西卖出去，句中不能在它前面加“被”表示被动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台冰箱我们谈妥了，当天就成交着。", "corrected_sentence": "这台冰箱我们谈妥了，当天就成交了。", "error_description": "错误：“成交着”；正确：“成交了”。“成交”表示一次性达成的结果，不能用“着”表示持续状态，应该用“了”表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96938, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96938, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96938, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "买卖双方达成交易。", "primary_collocate": null, "pronunciation": "chéng jiāo", "ipa": "tʂʰɤŋ˧˥ tɕjɑʊ˥", "syllable_count": 2, "sentences": [{"text": "双方谈了一个小时，终于成交了。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子昨天以三百万成交。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过几次谈判，这笔生意成交了。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格谈不拢，这笔买卖没有成交。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆二手车上个月成交了。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司商量好价格，当天就成交了。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要价格合适，我们马上成交。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货上周五成交，一共卖了五百箱。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方都同意这个价钱，生意很快成交。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中介说，这个月已经成交了十套房子。", "target_word": "成交", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成交了", "label": "体标（了）"}, {"form": "成交过", "label": "体标（过）"}, {"form": "成交量", "label": "复合词"}, {"form": "成交价", "label": "复合词"}], "register": "中性", "sense_fingerprint": "买卖双方谈妥，交易达成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882879db-4624-43a3-aabb-0b34d7693f04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与谈判无关，“双方谈了一个小时，终于结婚了”说不通。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”后要带宾语，句中“终于擦了”没有交代擦什么，且与谈判无关。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”与双方谈判没有关系，句子说不通。"}, {"text": "成交", "is_correct": true, "explanation": "“成交”表示买卖双方谈妥、交易达成，正好接“谈了一个小时”之后的结果。"}], "explanations": {"结婚": "语义：“结婚”与谈判无关，“双方谈了一个小时，终于结婚了”说不通。", "擦": "搭配：“擦”后要带宾语，句中“终于擦了”没有交代擦什么，且与谈判无关。", "下雨": "语义：“下雨”与双方谈判没有关系，句子说不通。", "成交": "“成交”表示买卖双方谈妥、交易达成，正好接“谈了一个小时”之后的结果。"}, "sentence_index": 0, "correct_answer": "成交"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告我们终于成交了。", "explanation": "这里应该用〈完成〉。“成交”只用于买卖双方谈妥交易，写完的报告要说“完成”。"}, {"text": "这笔买卖还没开始谈，我们就已经成交了。", "explanation": "这里不能用“成交”。“成交”表示买卖双方已经谈妥，而句中说“还没开始谈”，前后矛盾，所以不能说“成交”。"}, {"text": "他在大学里成交了很多朋友。", "explanation": "这里应该用〈结交〉。“成交”只用于买卖，交朋友要用“结交”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分手", "is_correct": false, "explanation": "语义：“分手”是断绝关系，与“价格合适就做成生意”的意思不合。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与买卖无关，“只要价格合适，我们马上唱歌”说不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与价格、买卖无关，“只要价格合适，我们马上睡觉”说不通。"}, {"text": "成交", "is_correct": true, "explanation": "“成交”表示价格谈妥、买卖达成，正好与“只要价格合适”的条件衔接。"}], "explanations": {"分手": "语义：“分手”是断绝关系，与“价格合适就做成生意”的意思不合。", "唱歌": "语义：“唱歌”与买卖无关，“只要价格合适，我们马上唱歌”说不通。", "睡觉": "语义：“睡觉”与价格、买卖无关，“只要价格合适，我们马上睡觉”说不通。", "成交": "“成交”表示价格谈妥、买卖达成，正好与“只要价格合适”的条件衔接。"}, "sentence_index": 6, "correct_answer": "成交"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他二十八岁那年成交了，现在孩子都三岁了。", "explanation": "这里应该用〈成家〉。“成交”指买卖达成交易，结婚组建家庭要说“成家”，二者读音相近，容易混淆。"}, {"text": "我们把旧书免费送给同学，很快就成交了。", "explanation": "免费赠送没有买卖双方讨价还价，不能说“成交”，这里应该说“送出”。"}, {"text": "他经过多年努力，终于成交了。", "explanation": "这里应该用〈成功〉。“成交”只用于买卖，人经过努力取得成果要说“成功”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔买卖成交的很顺利。", "corrected_sentence": "这笔买卖成交得很顺利。", "error_description": "错误：“成交的很顺利”；正确：“成交得很顺利”。“成交”后面表示情况的补语要用“得”连接，“的”用于修饰名词，这里用错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台二手电脑昨天就被成交了。", "corrected_sentence": "这台二手电脑昨天就成交了。", "error_description": "错误：“被成交”；正确：“成交”。“成交”表示买卖达成，句中不能在它前面加“被”构成被动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96939, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放下", "is_correct": true, "explanation": "反义：“放下”与“拿起”相对，指把手中的东西放到别处。"}, {"text": "洗澡", "is_correct": false, "explanation": "无关：“洗澡”指清洁身体，与用手取物没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "无关：“读书”指看书学习，不涉及用手抓起东西。"}, {"text": "跑步", "is_correct": false, "explanation": "无关：“跑步”指快速奔跑，与“拿起”没有对立关系。"}], "correct_answer": "放下", "explanations": {"放下": "反义：“放下”与“拿起”相对，指把手中的东西放到别处。", "洗澡": "无关：“洗澡”指清洁身体，与用手取物没有反义关系。", "读书": "无关：“读书”指看书学习，不涉及用手抓起东西。", "跑步": "无关：“跑步”指快速奔跑，与“拿起”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96939, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放下", "is_correct": true, "explanation": "反义：“放下”与“拿起”相对，指把手中的东西放到别处。"}, {"text": "画画", "is_correct": false, "explanation": "无关：“画画”指用笔作画，与用手取物没有反义关系。"}, {"text": "下棋", "is_correct": false, "explanation": "无关：“下棋”指对弈游戏，不涉及用手取物的反向动作。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”指躺下休息，与“拿起”没有对立关系。"}], "correct_answer": "放下", "explanations": {"放下": "反义：“放下”与“拿起”相对，指把手中的东西放到别处。", "画画": "无关：“画画”指用笔作画，与用手取物没有反义关系。", "下棋": "无关：“下棋”指对弈游戏，不涉及用手取物的反向动作。", "睡觉": "无关：“睡觉”指躺下休息，与“拿起”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96939, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手把东西抓起来。", "primary_collocate": null, "pronunciation": "ná qǐ", "ipa": "na˧˥ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "他拿起手机看时间。", "target_word": "拿起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她拿起外套就出门了。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸拿起锤子敲了敲墙。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我拿起一块饼干吃了。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿起伞跑了出去。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明拿起球扔给了朋友。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿起包包，头也不回地走了。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板拿起电话，马上打给了客人。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把筷子拿起又放下了。", "target_word": "拿起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟拿起玩具车，高兴地跑来跑去。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "拿起了", "label": "体标"}, {"form": "拿起过", "label": "体标"}], "register": "中性", "sense_fingerprint": "顺手抓起东西，接着去做别的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d5af855-8d3e-4dea-9cbd-ca81272939c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96939, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拿起", "is_correct": true, "explanation": "正确：“拿起”指顺手用手抓起手机，然后去看时间，与句意相符。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：手机不能嚼，“嚼”只用于食物。"}, {"text": "咬", "is_correct": false, "explanation": "语义：手机不能咬，句意不通。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于眼镜、帽子等，不说戴手机。"}], "explanations": {"拿起": "正确：“拿起”指顺手用手抓起手机，然后去看时间，与句意相符。", "嚼": "语义：手机不能嚼，“嚼”只用于食物。", "咬": "语义：手机不能咬，句意不通。", "戴": "搭配：“戴”用于眼镜、帽子等，不说戴手机。"}, "sentence_index": 0, "correct_answer": "拿起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿起手臂，拥抱了妈妈。", "explanation": "这里应该用〈张开〉。手臂不能被拿起，拥抱时要说“张开手臂”。“拿起”指用手取物。"}, {"text": "她拿起嘴角，笑了。", "explanation": "这里应该用〈扬起〉。嘴角不能被拿起，露出笑容时要说“扬起嘴角”。"}, {"text": "他拿起了一场运动。", "explanation": "这里应该用〈发起〉。“拿起”指用手取物，开始组织一场活动要用“发起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96939, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿起", "is_correct": true, "explanation": "正确：“拿起”指顺手抓起包包，然后头也不回地走了，与句意相符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：包包不能咬，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：包包不会唱，“唱包包”不通。"}, {"text": "吞", "is_correct": false, "explanation": "语义：包包不能吞，句意不通。"}], "explanations": {"拿起": "正确：“拿起”指顺手抓起包包，然后头也不回地走了，与句意相符。", "咬": "语义：包包不能咬，句意不通。", "唱": "语义：包包不会唱，“唱包包”不通。", "吞": "语义：包包不能吞，句意不通。"}, "sentence_index": 6, "correct_answer": "拿起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿起大拇指，向大家表示赞赏。", "explanation": "这里应该用〈竖起〉。大拇指不能被拿起，表示赞赏时要说“竖起大拇指”。"}, {"text": "这首老歌拿起了我的回忆。", "explanation": "这里应该用〈唤起〉。“拿起”指用手取物，回忆不能被拿起，应说“唤起回忆”。"}, {"text": "工人们拿起了一座舞台。", "explanation": "这里应该用〈搭起〉。舞台是搭建出来的，不能用手拿起，应说“搭起舞台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把拿起遥控器，换了一个台。", "corrected_sentence": "妈妈拿起遥控器，换了一个台。", "error_description": "“把”字句中“把”后应接名词性宾语，而“拿起”是动词，不能充当“把”的宾语；“拿起”本身可以直接带宾语，应说“妈妈拿起遥控器”，错误在多出“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师拿起着一支粉笔，在黑板上写字。", "corrected_sentence": "老师拿起了一支粉笔，在黑板上写字。", "error_description": "“拿起”表示一次性的取物动作，完成后应接“了”；“着”表示持续状态，与“拿起”搭配不自然（“拿着”才是常见说法）。正确说法是“拿起了一支粉笔”，错误在把“了”换成了“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
