INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96940, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手把物体取起。", "primary_collocate": null, "pronunciation": "ná qǐ", "ipa": "na˧˥ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "他拿起桌上的书。", "target_word": "拿起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我拿起笔写下了名字。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈拿起杯子喝了一口水。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你拿起那本红色的书。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从地上拿起一张纸。", "target_word": "拿起", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师拿起粉笔写了一个字。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿起钥匙，打开了门。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子拿起勺子，开始吃饭。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿起地图看了很久，还是不懂。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我拿起行李，走出了车站。", "target_word": "拿起", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "拿起了", "label": "体标"}, {"form": "拿起过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用手把桌上、地上的物体取起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d5af855-8d3e-4dea-9cbd-ca81272939c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拿起", "is_correct": true, "explanation": "正确：“拿起”指用手把桌上的书取起来，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：书不能吃，“吃”的对象应是食物。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指动笔写出文字，桌上已经印好的书不能用“写”。"}, {"text": "端起", "is_correct": false, "explanation": "搭配：“端”多用于托着碗盘，不说端书。"}], "explanations": {"拿起": "正确：“拿起”指用手把桌上的书取起来，与句意相符。", "吃": "语义：书不能吃，“吃”的对象应是食物。", "写": "语义：“写”指动笔写出文字，桌上已经印好的书不能用“写”。", "端起": "搭配：“端”多用于托着碗盘，不说端书。"}, "sentence_index": 0, "correct_answer": "拿起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿起右手，向大家打了个招呼。", "explanation": "这里应该用〈举起〉。“拿起”是用手握住物体取起来，手本身不能被拿起；举手打招呼要说“举起右手”。"}, {"text": "一阵风拿起了路上的落叶。", "explanation": "这里应该用〈卷起〉。“拿起”需要有人用手握住物体，风把落叶卷上半空要说“卷起”。"}, {"text": "她拿起脚，轻轻走进了房间。", "explanation": "这里应该用〈抬起〉。脚不能用手拿，抬起脚要用“抬起”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿起", "is_correct": true, "explanation": "正确：“拿起”指用手握住钥匙取起来，与句意相符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：钥匙不能咬，“咬”的对象一般是食物。"}, {"text": "亲", "is_correct": false, "explanation": "搭配：“亲”指亲吻或贴近，不说亲钥匙。"}, {"text": "嚼", "is_correct": false, "explanation": "语义：钥匙不能嚼，“嚼”只用于食物。"}], "explanations": {"拿起": "正确：“拿起”指用手握住钥匙取起来，与句意相符。", "咬": "语义：钥匙不能咬，“咬”的对象一般是食物。", "亲": "搭配：“亲”指亲吻或贴近，不说亲钥匙。", "嚼": "语义：钥匙不能嚼，“嚼”只用于食物。"}, "sentence_index": 6, "correct_answer": "拿起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿起拳头，冲向对手。", "explanation": "这里应该用〈挥起〉。拳头不能被拿起取走，挥动拳头要用“挥起”。"}, {"text": "这本书拿起了我的注意。", "explanation": "这里应该用〈引起〉。“拿起”用于握住有形的东西，注意力不能被拿起，应说“引起注意”。"}, {"text": "台风拿起了屋顶的瓦片。", "explanation": "这里应该用〈掀起〉。台风把瓦片揭起来要说“掀起”，“拿起”需要有人用手握住物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把拿起一支笔，在纸上画了一个圈。", "corrected_sentence": "她拿起一支笔，在纸上画了一个圈。", "error_description": "“把”字句中“把”后应接名词性宾语，而“拿起”是动词，不能充当“把”的宾语；“拿起”本身可以直接带宾语，应说“她拿起一支笔”，错误在多出“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈拿起着一部手机，给爸爸打了个电话。", "corrected_sentence": "妈妈拿起了一部手机，给爸爸打了个电话。", "error_description": "“拿起”表示一次性的取物动作，完成后应接“了”；“着”表示持续状态，与“拿起”搭配不自然。正确说法是“拿起了一部手机”，错误在把“了”换成了“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1e983d-5850-4069-871a-9e59dd8bfa66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利于", "is_correct": true, "explanation": "正确。“不利于”与“有利于”意思相反，都表示对事物产生的影响方向。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”是动词，表示加入某活动，与“有利于”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”表示互相交换意见，与“有利于”的好处或坏处没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”表示深入探讨，与“有利于”没有反义关系。"}], "correct_answer": "不利于", "explanations": {"不利于": "正确。“不利于”与“有利于”意思相反，都表示对事物产生的影响方向。", "参加": "“参加”是动词，表示加入某活动，与“有利于”没有反义关系。", "讨论": "“讨论”表示互相交换意见，与“有利于”的好处或坏处没有反义关系。", "研究": "“研究”表示深入探讨，与“有利于”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利于", "is_correct": true, "explanation": "正确。“不利于”与“有利于”意思相反，表示对事物产生坏的影响。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是动词，表示慢慢行走，与“有利于”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”表示仔细看，与“有利于”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”表示到外地游览，与“有利于”没有反义关系。"}], "correct_answer": "不利于", "explanations": {"不利于": "正确。“不利于”与“有利于”意思相反，表示对事物产生坏的影响。", "散步": "“散步”是动词，表示慢慢行走，与“有利于”没有反义关系。", "观察": "“观察”表示仔细看，与“有利于”没有反义关系。", "旅行": "“旅行”表示到外地游览，与“有利于”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "对某件事有好处。", "primary_collocate": null, "pronunciation": "yǒu lì yú", "ipa": "joʊ˨˩˦ li˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "早睡早起有利于身体健康。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多喝水有利于皮肤。", "target_word": "有利于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "运动有利于我们的身体。", "target_word": "有利于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "多读书有利于提高写作水平。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的睡眠有利于学习。", "target_word": "有利于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "吃早饭有利于一天的工作。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "安静的环境有利于孩子写作业。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多笑笑有利于身体和心情。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天散步有利于睡个好觉。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跟朋友聊天有利于放松心情。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有利於", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对身体、学习、生活等某方面有好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4c0234-abf6-4c9d-be01-e4d86c3bd9fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有利于", "is_correct": true, "explanation": "正确。“有利于身体健康”是常用搭配，表示对身体有好处。"}, {"text": "有害于", "is_correct": false, "explanation": "语义：“有害”与“有利”意思相反，句子会变成早睡早起对身体有害，与句意相悖。"}, {"text": "损害", "is_correct": false, "explanation": "语义：“损害”指使受到损伤，与“早睡早起”这一好习惯的语境相反，不合句意。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说的是数量，不能说“增加身体健康”。"}], "explanations": {"有利于": "正确。“有利于身体健康”是常用搭配，表示对身体有好处。", "有害于": "语义：“有害”与“有利”意思相反，句子会变成早睡早起对身体有害，与句意相悖。", "损害": "语义：“损害”指使受到损伤，与“早睡早起”这一好习惯的语境相反，不合句意。", "增加": "搭配：“增加”说的是数量，不能说“增加身体健康”。"}, "sentence_index": 0, "correct_answer": "有利于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有利于这个方案。", "explanation": "这里应该用〈赞成〉。“有利于”表示对事情有好处，不表示同意或支持某个方案；表示同意要说“赞成”。"}, {"text": "我们要有利于这次机会。", "explanation": "这里应该用〈利用〉。“有利于”表示对事物有好处，不能表示把机会用来做事；把机会用上要说“利用”。"}, {"text": "这项规定有利于浪费。", "explanation": "这里应该用〈阻止〉。“有利于”表示对事情有好处，不能说规定“有利于浪费”；这里要表达的是规定能阻止浪费，应说“阻止”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有利于", "is_correct": true, "explanation": "正确。“安静的环境有利于孩子写作业”表示安静对写作业有好处。"}, {"text": "阻碍", "is_correct": false, "explanation": "语义：“阻碍”表示妨碍，与“安静的环境”这一有利条件相反，句子会显得矛盾。"}, {"text": "增添", "is_correct": false, "explanation": "搭配：“增添”后面接的是乐趣、色彩等，不能直接接“孩子写作业”。"}, {"text": "拖累", "is_correct": false, "explanation": "语义：“拖累”指使人受牵累，与“安静”这一有利条件相反，不合句意。"}], "explanations": {"有利于": "正确。“安静的环境有利于孩子写作业”表示安静对写作业有好处。", "阻碍": "语义：“阻碍”表示妨碍，与“安静的环境”这一有利条件相反，句子会显得矛盾。", "增添": "搭配：“增添”后面接的是乐趣、色彩等，不能直接接“孩子写作业”。", "拖累": "语义：“拖累”指使人受牵累，与“安静”这一有利条件相反，不合句意。"}, "sentence_index": 6, "correct_answer": "有利于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们正在有利于一张地图。", "explanation": "这里应该用〈画〉。“有利于”表示对事物有好处，不能表示动手绘制；画地图要说“画”。"}, {"text": "我正在有利于答案。", "explanation": "这里应该用〈寻找〉。“有利于”表示对事情有好处，不能表示去找东西；“寻找答案”才是这里要表达的意思。"}, {"text": "这家工厂有利于大量废气。", "explanation": "这里应该用〈产生〉。“有利于”表示对事情有好处，不能表示产生某种东西；“产生大量废气”才是这里要表达的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这样锻炼有利于了健康。", "corrected_sentence": "这样锻炼有利于健康。", "error_description": "错误：“有利于”和宾语“健康”之间多了“了”。正确形式是“这样锻炼有利于健康。”“了”不能插在“有利于”与宾语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "安静的书房有利于对孩子专心学习。", "corrected_sentence": "安静的书房有利于孩子专心学习。", "error_description": "错误：“有利于”后面多加了介词“对”。正确形式是“有利于孩子专心学习”，“有利于”后直接接宾语，不需要“对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利于", "is_correct": true, "explanation": "正确。“不利于”与“有利于”意思相反，表示对事物的发展起阻碍作用。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”是动词，表示加入某活动，与“有利于”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”表示互相交换意见，与“有利于”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”表示深入探讨，与“有利于”没有反义关系。"}], "correct_answer": "不利于", "explanations": {"不利于": "正确。“不利于”与“有利于”意思相反，表示对事物的发展起阻碍作用。", "参加": "“参加”是动词，表示加入某活动，与“有利于”没有反义关系。", "讨论": "“讨论”表示互相交换意见，与“有利于”没有反义关系。", "研究": "“研究”表示深入探讨，与“有利于”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不利于", "is_correct": true, "explanation": "正确。“不利于”与“有利于”意思相反，表示对事物产生阻碍作用。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是动词，表示慢慢行走，与“有利于”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”表示仔细看，与“有利于”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”表示到外地游览，与“有利于”没有反义关系。"}], "correct_answer": "不利于", "explanations": {"不利于": "正确。“不利于”与“有利于”意思相反，表示对事物产生阻碍作用。", "散步": "“散步”是动词，表示慢慢行走，与“有利于”没有反义关系。", "观察": "“观察”表示仔细看，与“有利于”没有反义关系。", "旅行": "“旅行”表示到外地游览，与“有利于”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "对某事物有好处，起促进作用。", "primary_collocate": null, "pronunciation": "yǒu lì yú", "ipa": "joʊ˨˩˦ li˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "这项政策有利于经济发展。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的交通规划有利于城市发展。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和平有利于各国的合作。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "减少污染有利于保护环境。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公平的竞争有利于市场发展。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样做有利于团队合作。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "良好的教育有利于社会进步。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开放的政策有利于吸引更多游客。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多种树有利于改善空气质量。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "互相理解有利于解决问题。", "target_word": "有利于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有利於", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对发展、进步等事物起促进作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4c0234-abf6-4c9d-be01-e4d86c3bd9fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有利于", "is_correct": true, "explanation": "正确。“有利于经济发展”表示对经济的发展起促进作用。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说的是数量，不能说“增加经济发展”。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”表示使受损，与政策的促进作用相反，句子不合常理。"}, {"text": "拖累", "is_correct": false, "explanation": "语义：“拖累”指使事物受牵累、受阻碍，与“政策”的积极作用相反，不合句意。"}], "explanations": {"有利于": "正确。“有利于经济发展”表示对经济的发展起促进作用。", "增加": "搭配：“增加”说的是数量，不能说“增加经济发展”。", "破坏": "语义：“破坏”表示使受损，与政策的促进作用相反，句子不合常理。", "拖累": "语义：“拖累”指使事物受牵累、受阻碍，与“政策”的积极作用相反，不合句意。"}, "sentence_index": 0, "correct_answer": "有利于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有利于这项政策。", "explanation": "这里应该用〈赞成〉。“有利于”表示对事情有好处，不表示同意或支持某项政策；表示同意要说“赞成”。"}, {"text": "我们要有利于这些资源。", "explanation": "这里应该用〈利用〉。“有利于”表示对事物有好处，不能表示把资源用起来；这里应说“利用”。"}, {"text": "孩子们在有利于房间。", "explanation": "这里应该用〈打扫〉。“有利于”表示对事情有好处，不能表示动手清理房间；这里应说“打扫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有利于", "is_correct": true, "explanation": "正确。“良好的教育有利于社会进步”表示教育对社会的进步起促进作用。"}, {"text": "增添", "is_correct": false, "explanation": "搭配：“增添”后面接的是乐趣、色彩等，不能说“增添社会进步”。"}, {"text": "限制", "is_correct": false, "explanation": "语义：“限制”表示约束、阻止，与“良好的教育”的积极作用相反，不合句意。"}, {"text": "削弱", "is_correct": false, "explanation": "语义：“削弱”表示使力量变弱，与“良好的教育”促进进步的作用相反，句子矛盾。"}], "explanations": {"有利于": "正确。“良好的教育有利于社会进步”表示教育对社会的进步起促进作用。", "增添": "搭配：“增添”后面接的是乐趣、色彩等，不能说“增添社会进步”。", "限制": "语义：“限制”表示约束、阻止，与“良好的教育”的积极作用相反，不合句意。", "削弱": "语义：“削弱”表示使力量变弱，与“良好的教育”促进进步的作用相反，句子矛盾。"}, "sentence_index": 6, "correct_answer": "有利于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "互相理解之后，我们有利于一顿晚饭。", "explanation": "这里应该用〈做〉。“有利于”表示对事物有好处，不能表示动手做饭；做饭要说“做”。"}, {"text": "互相理解之后，我们有利于一首歌。", "explanation": "这里应该用〈唱〉。“有利于”表示对事物有好处，不能表示演唱；唱歌要说“唱”。"}, {"text": "互相理解之后，我们有利于一封信。", "explanation": "这里应该用〈写〉。“有利于”表示对事物有好处，不能表示动笔；写信要说“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项政策有利于了经济增长。", "corrected_sentence": "这项政策有利于经济增长。", "error_description": "错误：“有利于”和宾语“经济增长”之间多了“了”。正确形式是“这项政策有利于经济增长。”“了”不能插在“有利于”与宾语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "良好的教育有利于的人才培养。", "corrected_sentence": "良好的教育有利于人才培养。", "error_description": "错误：“有利于”和宾语“人才培养”之间多了“的”。“有利于”是动词，后面直接接宾语，应说“良好的教育有利于人才培养。”“的”不能插在它和宾语之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
