INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96965, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "想做却不能做，没有别的办法。", "primary_collocate": null, "pronunciation": "wú nài", "ipa": "u˧˥ nai˥˩", "syllable_count": 2, "sentences": [{"text": "我想帮他，可是没有钱，真无奈。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想去看电影，作业却没写完，只好无奈地留在家里。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很想回家过年，可是票卖完了，心里很无奈。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想早点睡，可是邻居吵得厉害，我很无奈。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想帮学生，却没有时间，只能无奈地摇头。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想参加比赛，但是腿受伤了，感到很无奈。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想继续读书，家里却没钱，这让她很无奈。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想说清楚，他却不听，我只好无奈地走了。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸想去爬山，下雨了，他无奈地看着窗外。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明明想买那本书，可是书店已经关门了，他很无奈。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无奈地", "label": "状语形式"}, {"form": "无奈的", "label": "定语形式"}, {"form": "無奈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "想做某事却做不到，心里不得已", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882879db-4624-43a3-aabb-0b34d7693f04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96965, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”指钱多，与句中“没有钱”正好相反，句子说不通。"}, {"text": "无奈", "is_correct": true, "explanation": "“无奈”表示想做却做不到、没有别的办法，正好对应“想帮他却没有钱”的处境。"}, {"text": "满意", "is_correct": false, "explanation": "语义：“满意”表示称心，句中说的是帮不上忙的为难，二者不合。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”只形容人或物的高矮，不能用来形容处境或心情。"}], "explanations": {"富裕": "语义：“富裕”指钱多，与句中“没有钱”正好相反，句子说不通。", "无奈": "“无奈”表示想做却做不到、没有别的办法，正好对应“想帮他却没有钱”的处境。", "满意": "语义：“满意”表示称心，句中说的是帮不上忙的为难，二者不合。", "高": "体貌：“高”只形容人或物的高矮，不能用来形容处境或心情。"}, "sentence_index": 0, "correct_answer": "无奈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一家人去海边玩，天气特别好，大家都很无奈。", "explanation": "这里应该用〈开心〉。“无奈”表示没有办法、只能接受，玩得正好时说“无奈”不合语境。"}, {"text": "我主动辞了工作，去国外读书，心里很无奈。", "explanation": "这里应该用〈甘心〉。“无奈”表示没有选择、身不由己，是被迫接受的心情；这件事是我自己主动决定的，心情应是〈甘心〉，不能说“无奈”。"}, {"text": "他认真复习了一个月，终于拿到第一名，他很无奈地笑了。", "explanation": "“无奈”表示没有办法的心情，拿到第一名是值得高兴的事，这里应该用〈高兴〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96965, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得意", "is_correct": false, "explanation": "语义：“得意”指因成功而洋洋自得，与“家里没钱、读不成书”的处境相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来形容心理状态或处境。"}, {"text": "无奈", "is_correct": true, "explanation": "“无奈”表示没有办法、不得已，正好说明她想读书却因为没钱而无法实现的心情。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：“幸福”表示满足快乐，与“想读书却没钱”的情况矛盾。"}], "explanations": {"得意": "语义：“得意”指因成功而洋洋自得，与“家里没钱、读不成书”的处境相反。", "漂亮": "体貌：“漂亮”形容外貌，不能用来形容心理状态或处境。", "无奈": "“无奈”表示没有办法、不得已，正好说明她想读书却因为没钱而无法实现的心情。", "幸福": "语义：“幸福”表示满足快乐，与“想读书却没钱”的情况矛盾。"}, "sentence_index": 6, "correct_answer": "无奈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人很无奈，常常耍赖、不讲道理。", "explanation": "这里应该用〈无赖〉。“无奈”形容没有办法的心情，不用来形容人的品性；指耍横、不讲理的人要用〈无赖〉。"}, {"text": "我主动选择了这个城市，心里很无奈。", "explanation": "这里应该用〈甘心〉。“无奈”表示没有选择、身不由己；自己主动做出的选择，心情应是〈甘心〉，不能用“无奈”。"}, {"text": "他见到喜欢的女孩，很无奈地红了脸。", "explanation": "这里不是〈无奈〉的意思。“无奈”表示没有办法，不表示害羞；害羞、脸红应说〈害羞〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想去看病，可是医院的号已经挂完了，我无奈。", "corrected_sentence": "我想去看病，可是医院的号已经挂完了，我很无奈。", "error_description": "错误：“我无奈”；正确：“我很无奈”。“无奈”作谓语时，前面通常要加“很”等程度副词，直接说“我无奈”不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈只能无奈的叹了一口气。", "corrected_sentence": "妈妈只能无奈地叹了一口气。", "error_description": "错误：“无奈的叹了一口气”；正确：“无奈地叹了一口气”。“无奈”后面修饰动词“叹”时要用“地”，“的”用于修饰名词，这里用“的”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96966, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96966, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96966, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有办法；无可奈何。", "primary_collocate": null, "pronunciation": "wú nài", "ipa": "u˧˥ nai˥˩", "syllable_count": 2, "sentences": [{"text": "面对堵车，司机们只能无奈地等着。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无奈地笑了笑，没有再说什么。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个很无奈的决定，谁也没有别的选择。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭个不停，妈妈没办法，只能无奈地叹气。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说不加工资，大家听了都很无奈。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个坏消息，她脸上露出无奈的表情。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无奈之下，他只好把旧车卖了。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活就是这样，有时候真的很无奈。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下个不停，我们无奈地取消了旅行。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着越来越高的房价，年轻人觉得很无奈。", "target_word": "无奈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无奈地", "label": "状语形式"}, {"form": "无奈的", "label": "定语形式"}, {"form": "無奈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "面对现实毫无办法，只能接受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882879db-4624-43a3-aabb-0b34d7693f04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兴奋", "is_correct": false, "explanation": "语义：“兴奋”表示情绪激动，与“只能”表示的被迫、无奈语气不合。"}, {"text": "无奈", "is_correct": true, "explanation": "“无奈”表示没有办法只能接受，正好符合堵车时只能等待的处境。"}, {"text": "迅速", "is_correct": false, "explanation": "搭配：“迅速”形容动作快，不能修饰“等”这种持续的状态。"}, {"text": "欣喜", "is_correct": false, "explanation": "语义：“欣喜”是高兴的心情，与堵车时的为难不相符。"}], "explanations": {"兴奋": "语义：“兴奋”表示情绪激动，与“只能”表示的被迫、无奈语气不合。", "无奈": "“无奈”表示没有办法只能接受，正好符合堵车时只能等待的处境。", "迅速": "搭配：“迅速”形容动作快，不能修饰“等”这种持续的状态。", "欣喜": "语义：“欣喜”是高兴的心情，与堵车时的为难不相符。"}, "sentence_index": 0, "correct_answer": "无奈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于考上了理想的大学，无奈地笑了起来。", "explanation": "这里应该用〈高兴〉。“无奈”表示没有办法的心情，考上理想的大学是好事，不能用“无奈”。"}, {"text": "星期天全家去游乐场，大家玩得特别开心，真无奈。", "explanation": "这里应该用〈开心〉。“无奈”表示没有办法、只能接受，玩得高兴时说“无奈”不合语境。"}, {"text": "他的办法很多，遇到问题总能很无奈地解决。", "explanation": "这里应该用〈轻松〉。“无奈”表示没有办法、无可奈何，与“办法很多”矛盾；能顺利解决问题要说〈轻松〉，不能说“无奈”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高兴", "is_correct": false, "explanation": "语义：“高兴之下”表示因为高兴，与“只好把旧车卖了”的为难不相合。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”表示不费力、没有压力，与“只好卖车”的被迫情况矛盾。"}, {"text": "无奈", "is_correct": true, "explanation": "“无奈之下”表示没有别的办法，正好接下句“他只好把旧车卖了”。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”指家境好，与“只好卖车”这种需要为钱发愁的处境矛盾。"}], "explanations": {"高兴": "语义：“高兴之下”表示因为高兴，与“只好把旧车卖了”的为难不相合。", "轻松": "语义：“轻松”表示不费力、没有压力，与“只好卖车”的被迫情况矛盾。", "无奈": "“无奈之下”表示没有别的办法，正好接下句“他只好把旧车卖了”。", "富裕": "语义：“富裕”指家境好，与“只好卖车”这种需要为钱发愁的处境矛盾。"}, "sentence_index": 6, "correct_answer": "无奈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人很无奈，常常耍赖、不讲道理。", "explanation": "这里应该用〈无赖〉。“无奈”形容没有办法的心情，不用来形容人的品性；指耍横、不讲理的人要用〈无赖〉。"}, {"text": "我主动选择了这个城市，心里很无奈。", "explanation": "这里应该用〈甘心〉。“无奈”表示没有办法、身不由己；自己主动选择的城市，心情应是〈甘心〉，不能用“无奈”。"}, {"text": "他见到喜欢的女孩，很无奈地红了脸。", "explanation": "这里不是〈无奈〉的意思。“无奈”表示没有办法，不表示害羞；害羞、脸红应说〈害羞〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这个结果无奈，只好接受了。", "corrected_sentence": "他对这个结果很无奈，只好接受了。", "error_description": "错误：“对这个结果无奈”；正确：“对这个结果很无奈”。“无奈”作谓语时前面一般要加“很”等程度副词，漏掉“很”就不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面对这次失败，他无奈的接受了现实。", "corrected_sentence": "面对这次失败，他无奈地接受了现实。", "error_description": "错误：“无奈的接受”；正确：“无奈地接受”。修饰动词要用“地”，“的”用来修饰名词，不能用来修饰“接受”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96967, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有意", "is_correct": true, "explanation": "正确。“有意”表示故意、有意图，与“无意”表示不是故意的意思相反。"}, {"text": "幽默", "is_correct": false, "explanation": "“幽默”形容风趣、善于说笑，与“无意”的意思没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”形容态度认真、庄重，与“无意”的意思没有反义关系。"}, {"text": "友好", "is_correct": false, "explanation": "“友好”形容态度亲切，与“无意”的意思没有反义关系。"}], "correct_answer": "有意", "explanations": {"有意": "正确。“有意”表示故意、有意图，与“无意”表示不是故意的意思相反。", "幽默": "“幽默”形容风趣、善于说笑，与“无意”的意思没有反义关系。", "严肃": "“严肃”形容态度认真、庄重，与“无意”的意思没有反义关系。", "友好": "“友好”形容态度亲切，与“无意”的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96967, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有意", "is_correct": true, "explanation": "正确。“有意”表示故意、有意图，与“无意”表示不是故意的意思相反。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”形容态度专注、不马虎，与“无意”的意思没有反义关系。"}, {"text": "善良", "is_correct": false, "explanation": "“善良”形容心地好，与“无意”的意思没有反义关系。"}, {"text": "急躁", "is_correct": false, "explanation": "“急躁”形容性格不耐烦，与“无意”的意思没有反义关系。"}], "correct_answer": "有意", "explanations": {"有意": "正确。“有意”表示故意、有意图，与“无意”表示不是故意的意思相反。", "认真": "“认真”形容态度专注、不马虎，与“无意”的意思没有反义关系。", "善良": "“善良”形容心地好，与“无意”的意思没有反义关系。", "急躁": "“急躁”形容性格不耐烦，与“无意”的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96967, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不是特意的，是不小心做的。", "primary_collocate": null, "pronunciation": "wú yì", "ipa": "u˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "对不起，我是无意的，不是故意踩你。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错误是无意的，请你原谅他。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无意的一句话，让她哭了。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是无意的玩笑，你别生气。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的无意之举，帮了大忙。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我说的话是无意的，没想伤害你。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子无意的动作，打碎了花瓶。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封邮件是无意发出去的，请删除。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管有意还是无意，他都应该道歉。", "target_word": "无意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把你的书弄湿了，是无意的，请原谅。", "target_word": "无意", "complexity_tier": "T3", "furigana": "wǒ bǎ nǐ de shū nòng shī le, shì wú yì de, qǐng yuán liàng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "无意中", "label": "复合"}, {"form": "无意间", "label": "复合"}], "register": "中性", "sense_fingerprint": "无意：不是故意的，不小心做的，常说“是无意的”“无意的话”，与有意相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4c0234-abf6-4c9d-be01-e4d86c3bd9fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96967, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无意", "is_correct": true, "explanation": "正确。“我是无意的，不是故意踩你”表示踩到你并非有意，与“不是故意”相呼应。"}, {"text": "有意", "is_correct": false, "explanation": "语义：“有意”表示故意，与后半句“不是故意踩你”的意思相互矛盾。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“我是故意的”与“不是故意踩你”前后矛盾，句子无法成立。"}, {"text": "蓄意", "is_correct": false, "explanation": "语域：“蓄意”是书面语，表示预先计划好的，与口语道歉的语境不合。"}], "explanations": {"无意": "正确。“我是无意的，不是故意踩你”表示踩到你并非有意，与“不是故意”相呼应。", "有意": "语义：“有意”表示故意，与后半句“不是故意踩你”的意思相互矛盾。", "故意": "语义：“我是故意的”与“不是故意踩你”前后矛盾，句子无法成立。", "蓄意": "语域：“蓄意”是书面语，表示预先计划好的，与口语道歉的语境不合。"}, "sentence_index": 0, "correct_answer": "无意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个方案无意，建议重写。", "explanation": "这里应该用〈无意义〉。“无意”表示不是故意的，不表示没有价值；形容方案没有价值要说“无意义”。"}, {"text": "他无意地决定辞职，考虑了好几年。", "explanation": "这里应该用〈有意〉。“无意地”表示不是特意做的，与“考虑了好几年”矛盾；经过考虑的决定要说“有意”。"}, {"text": "他无意地报名参加比赛，这是他精心挑选的项目。", "explanation": "这里应该用〈有意〉。“精心挑选”本身是有意的，与“无意地”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无意", "is_correct": true, "explanation": "正确。“孩子无意的动作”表示孩子不是故意做的，与“打碎了花瓶”的结果相符。"}, {"text": "有心", "is_correct": false, "explanation": "语义：“有心”表示有意图，与“孩子的动作”造成打碎花瓶的意外结果不相符。"}, {"text": "刻意", "is_correct": false, "explanation": "语义：“刻意”表示特意、有意去做，与“打碎了花瓶”的意外结果相矛盾。"}, {"text": "精心", "is_correct": false, "explanation": "搭配：“精心”形容用心细致，不能用来修饰“动作”后导致打碎花瓶的结果。"}], "explanations": {"无意": "正确。“孩子无意的动作”表示孩子不是故意做的，与“打碎了花瓶”的结果相符。", "有心": "语义：“有心”表示有意图，与“孩子的动作”造成打碎花瓶的意外结果不相符。", "刻意": "语义：“刻意”表示特意、有意去做，与“打碎了花瓶”的意外结果相矛盾。", "精心": "搭配：“精心”形容用心细致，不能用来修饰“动作”后导致打碎花瓶的结果。"}, "sentence_index": 6, "correct_answer": "无意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我特意为你准备了这份礼物，是无意的。", "explanation": "这里应该用〈有意〉。“特意”表示有意为之，与“无意”矛盾。"}, {"text": "这是一个无意的决定，我深思熟虑过。", "explanation": "这里应该删去“无意”。“无意”表示不是特意做的，用来修饰“决定”会与“深思熟虑过”矛盾；决定本身就是有意的。"}, {"text": "这次比赛的胜利是他精心计划的，却是无意的。", "explanation": "这里应该用〈有意〉。“精心计划”本身是有意的，与“无意”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对不起，我很无意踩你，不是故意的。", "corrected_sentence": "对不起，我无意踩你，不是故意的。", "error_description": "错误：“无意”前面多了“很”。正确形式是“对不起，我无意踩你，不是故意的。”“无意”不能用程度副词修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条消息是无意了发出去的，请忽略。", "corrected_sentence": "这条消息是无意发出去的，请忽略。", "error_description": "错误：“了”放在“无意”和“发”之间，位置不对。正确形式是“这条消息是无意发出去的，请忽略。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
