INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96975, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装水或饮料的容器，口小肚子大。", "primary_collocate": null, "pronunciation": "píng", "ipa": "pʰiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "这个瓶里有水，你喝吧。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的瓶忘在教室了，没有水喝。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶很轻，可以带去学校。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从包里拿出一个瓶，喝了几口水。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶是塑料做的，不会碎。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝完饮料后，请把瓶放进回收箱。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶里的果汁是冰的，很好喝。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶太小了，装不下一升水。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友用瓶装满了水，去浇花。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶在瓶里，放进冰箱就不会坏。", "target_word": "瓶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓶子", "label": "复合"}, {"form": "水瓶", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "瓶：装水、果汁等饮料的容器，口小肚子大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4c0234-abf6-4c9d-be01-e4d86c3bd9fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96975, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "瓶", "is_correct": true, "explanation": "正确。瓶 píng 指装水、饮料的容器，口小肚子大。"}, {"text": "迎", "is_correct": false, "explanation": "yíng（第二声）与 píng 声母不同（y/p），意思是迎接。"}, {"text": "形", "is_correct": false, "explanation": "xíng（第二声）与 píng 声母不同（x/p），意思是形状。"}, {"text": "宁", "is_correct": false, "explanation": "níng（第二声）与 píng 声母不同（n/p），意思是安宁。"}, {"text": "频", "is_correct": false, "explanation": "pín（第二声）与 píng 韵母不同（n/ng），意思是频繁。"}], "explanations": {"瓶": "正确。瓶 píng 指装水、饮料的容器，口小肚子大。", "迎": "yíng（第二声）与 píng 声母不同（y/p），意思是迎接。", "形": "xíng（第二声）与 píng 声母不同（x/p），意思是形状。", "宁": "níng（第二声）与 píng 声母不同（n/p），意思是安宁。", "频": "pín（第二声）与 píng 韵母不同（n/ng），意思是频繁。"}, "sentence_index": null, "correct_answer": "瓶"}, "level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本不是容器，里面不会有水，“这个课本里有水”说不通。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不是能装水让人喝的容器，“房间里有水”说不通。"}, {"text": "瓶", "is_correct": true, "explanation": "正确。“瓶”是装水的容器，“这个瓶里有水，你喝吧”成立。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不是容器，里面不会有水。"}], "explanations": {"课本": "语义：课本不是容器，里面不会有水，“这个课本里有水”说不通。", "房间": "语义：房间不是能装水让人喝的容器，“房间里有水”说不通。", "瓶": "正确。“瓶”是装水的容器，“这个瓶里有水，你喝吧”成立。", "黑板": "语义：黑板不是容器，里面不会有水。"}, "sentence_index": 0, "correct_answer": "瓶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用瓶切菜。", "explanation": "这里应该用〈菜刀〉。瓶是装水或饮料的容器，不能用来切菜。"}, {"text": "妈妈把衣服放进瓶里洗。", "explanation": "这里应该用〈盆〉。瓶口小，不能用来洗衣服。"}, {"text": "他去超市买了一瓶纸巾。", "explanation": "这里应该用〈包〉。瓶用来装水或饮料，纸巾要用包装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96975, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "瓶", "is_correct": true, "explanation": "正确。瓶 píng 指装水、饮料的容器，口小肚子大。"}, {"text": "明", "is_correct": false, "explanation": "míng（第二声）与 píng 声母不同（m/p），意思是明亮。"}, {"text": "零", "is_correct": false, "explanation": "líng（第二声）与 píng 声母不同（l/p），意思是零。"}, {"text": "停", "is_correct": false, "explanation": "tíng（第二声）与 píng 声母不同（t/p），意思是停止。"}, {"text": "情", "is_correct": false, "explanation": "qíng（第二声）与 píng 声母不同（q/p），意思是感情。"}], "explanations": {"瓶": "正确。瓶 píng 指装水、饮料的容器，口小肚子大。", "明": "míng（第二声）与 píng 声母不同（m/p），意思是明亮。", "零": "líng（第二声）与 píng 声母不同（l/p），意思是零。", "停": "tíng（第二声）与 píng 声母不同（t/p），意思是停止。", "情": "qíng（第二声）与 píng 声母不同（q/p），意思是感情。"}, "sentence_index": null, "correct_answer": "瓶"}, "level_3": {"options": [{"text": "河", "is_correct": false, "explanation": "语义：河里不能装果汁给人喝，“河里的果汁”说不通。"}, {"text": "盆", "is_correct": false, "explanation": "搭配：盆多用于种花或洗东西，不说“盆里的果汁”。"}, {"text": "瓶", "is_correct": true, "explanation": "正确。“瓶里的果汁是冰的，很好喝”，“瓶”指装饮料的容器。"}, {"text": "池子", "is_correct": false, "explanation": "语义：池子是大型的水池，不是盛饮料的容器，“池子里的果汁”说不通。"}], "explanations": {"河": "语义：河里不能装果汁给人喝，“河里的果汁”说不通。", "盆": "搭配：盆多用于种花或洗东西，不说“盆里的果汁”。", "瓶": "正确。“瓶里的果汁是冰的，很好喝”，“瓶”指装饮料的容器。", "池子": "语义：池子是大型的水池，不是盛饮料的容器，“池子里的果汁”说不通。"}, "sentence_index": 6, "correct_answer": "瓶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用瓶煮粥。", "explanation": "这里应该用〈锅〉。瓶口小、不能加热，煮粥要用锅。"}, {"text": "他用瓶擦桌子。", "explanation": "这里应该用〈抹布〉。瓶是盛放液体的容器，不能用来擦东西。"}, {"text": "她提着一瓶水果去买菜。", "explanation": "这里应该用〈篮子〉。瓶用来装液体，装水果和买菜要用篮子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96975, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我买了一根瓶，装满了果汁。", "corrected_sentence": "妈妈给我买了一个瓶，装满了果汁。", "error_description": "量词错误：“瓶”应用量词“个”，说“一个瓶”；“根”用于细长的东西，不能用于瓶。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96975, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不小心把瓶摔了碎。", "corrected_sentence": "他不小心把瓶摔碎了。", "error_description": "补语错误：“摔碎”是动补结构，“碎”要紧跟“摔”，“了”放在最后，应说“摔碎了”，不能说“摔了碎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
