INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96991, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变得比原来小。", "primary_collocate": null, "pronunciation": "suō xiǎo", "ipa": "swo˥ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "冰块在太阳下慢慢缩小了。", "target_word": "缩小", "complexity_tier": "T3", "furigana": "bīngkuài zài tàiyáng xià mànmàn suō xiǎo le.", "sentence_source": "generated"}, {"text": "中午太阳升高，影子慢慢缩小了。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家的差距正在缩小。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个苹果放了几天，明显缩小了。", "target_word": "缩小", "complexity_tier": "T3", "furigana": "zhè ge píngguǒ fàng le jǐ tiān, míngxiǎn suō xiǎo le.", "sentence_source": "generated"}, {"text": "气球漏气后，慢慢缩小了。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天一到，池塘的面积就缩小了。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜡烛燃烧以后，长度缩小了一半。", "target_word": "缩小", "complexity_tier": "T3", "furigana": "làzhú ránshāo yǐhòu, chángdù suō xiǎo le yí bàn.", "sentence_source": "generated"}, {"text": "湖水变少，湖面缩小了一半。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的伤口慢慢缩小了。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贫富差距没有缩小。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缩小了", "label": "体标"}, {"form": "缩小过", "label": "体标"}], "register": "中性", "sense_fingerprint": "事物自己变小（不及物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882879db-4624-43a3-aabb-0b34d7693f04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96991, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缩小", "is_correct": true, "explanation": "缩小：冰块受热慢慢变小，符合语境。"}, {"text": "增大", "is_correct": false, "explanation": "语义：“增大”指变大，与“太阳下慢慢”导致冰块变小的语境相反。"}, {"text": "长大", "is_correct": false, "explanation": "搭配：“长大”多用于人和生物，冰块不能长大。"}, {"text": "变胖", "is_correct": false, "explanation": "体貌：“变胖”形容人的体型，冰块不能说变胖。"}], "explanations": {"缩小": "缩小：冰块受热慢慢变小，符合语境。", "增大": "语义：“增大”指变大，与“太阳下慢慢”导致冰块变小的语境相反。", "长大": "搭配：“长大”多用于人和生物，冰块不能长大。", "变胖": "体貌：“变胖”形容人的体型，冰块不能说变胖。"}, "sentence_index": 0, "correct_answer": "缩小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把搜索的范围缩小到了城西。", "explanation": "这里的〈缩小〉是及物用法，表示〈使范围变小〉，与本条“变得比原来小”的意思不同。"}, {"text": "台风过后，风力明显缩小了。", "explanation": "这里应该用〈减弱〉。缩小指体积或范围变小，风力、力量的下降要用减弱。"}, {"text": "吃了药以后，病人的疼痛缩小了不少。", "explanation": "这里应该用〈减轻〉。缩小指体积或范围变小，疼痛、负担的减少要用减轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96991, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缩小", "is_correct": true, "explanation": "缩小：蜡烛燃烧后长度变短了一半，符合语境。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”指变多或变长，与“燃烧以后”长度变短的语境相反。"}, {"text": "延长", "is_correct": false, "explanation": "语义：“延长”指时间或长度变长，与燃烧后变短的语境相反。"}, {"text": "变窄", "is_correct": false, "explanation": "搭配：“变窄”说的是宽度，不能用于长度。"}], "explanations": {"缩小": "缩小：蜡烛燃烧后长度变短了一半，符合语境。", "增加": "语义：“增加”指变多或变长，与“燃烧以后”长度变短的语境相反。", "延长": "语义：“延长”指时间或长度变长，与燃烧后变短的语境相反。", "变窄": "搭配：“变窄”说的是宽度，不能用于长度。"}, "sentence_index": 6, "correct_answer": "缩小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的物价缩小了不少。", "explanation": "这里应该用〈降低〉。缩小指体积或范围变小，物价、价格的下降要用降低。"}, {"text": "这次会议的时间缩小了一个小时。", "explanation": "这里应该用〈缩短〉。时间的减少要用缩短；缩小多指体积或范围变小。"}, {"text": "夜里气温缩小了好几度。", "explanation": "这里应该用〈下降〉。缩小指体积或范围变小，气温的下降要用下降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
