INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96992, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使变小；减小范围。", "primary_collocate": null, "pronunciation": "suō xiǎo", "ipa": "swo˥ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "请把这张照片缩小一点。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察缩小了搜索范围。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想缩小两个部门的差距。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以用手指缩小屏幕上的字。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要缩小范围，再找一找。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把考试范围缩小到前五课。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生想用药缩小病人的肿块。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店为了省钱，缩小了店面。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把地图缩小后打印出来。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂缩小了生产规模。", "target_word": "缩小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缩小了", "label": "体标"}, {"form": "缩小过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人有意把事物或范围变小（及物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882879db-4624-43a3-aabb-0b34d7693f04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_erro