INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缩小", "is_correct": true, "explanation": "缩小：请对方把照片变小，符合语境。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是破坏纸张，与“把这张照片……一点”的修改语境不合。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是用牙齿夹断，与照片的修改语境不合。"}, {"text": "染", "is_correct": false, "explanation": "搭配：“染”多接头发、布料等，不能用于照片。"}], "explanations": {"缩小": "缩小：请对方把照片变小，符合语境。", "撕": "语义：“撕”是破坏纸张，与“把这张照片……一点”的修改语境不合。", "咬": "语义：“咬”是用牙齿夹断，与照片的修改语境不合。", "染": "搭配：“染”多接头发、布料等，不能用于照片。"}, "sentence_index": 0, "correct_answer": "缩小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府把房租缩小了一些。", "explanation": "这里应该用〈降低〉。缩小指使物体或范围变小，房租、价格的下降要用降低。"}, {"text": "请把视频缩小到三分钟以内。", "explanation": "这里应该用〈缩短〉。缩小用于空间或范围，视频的时长要用缩短。"}, {"text": "医生缩小了病人的痛苦。", "explanation": "这里应该用〈减轻〉。缩小用于体积或范围，痛苦、负担的减轻要用减轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缩小", "is_correct": true, "explanation": "缩小：用药使肿块变小，符合治疗语境。"}, {"text": "扩散", "is_correct": false, "explanation": "语义：“扩散”指向四周蔓延，与用药缩小肿块的目的相反。"}, {"text": "增大", "is_correct": false, "explanation": "语义：“增大”指变大，医生用药不会让肿块变大。"}, {"text": "加重", "is_correct": false, "explanation": "语义：“加重”指病情更严重，与治疗的目的相反。"}], "explanations": {"缩小": "缩小：用药使肿块变小，符合治疗语境。", "扩散": "语义：“扩散”指向四周蔓延，与用药缩小肿块的目的相反。", "增大": "语义：“增大”指变大，医生用药不会让肿块变大。", "加重": "语义：“加重”指病情更严重，与治疗的目的相反。"}, "sentence_index": 6, "correct_answer": "缩小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校把暑假缩小了一周。", "explanation": "这里应该用〈缩短〉。缩小用于空间或范围，暑假这类时间的减少要用缩短。"}, {"text": "公司缩小了一百名员工。", "explanation": "这里应该用〈裁减〉。缩小用于规模或范围，人员的减少要用裁减。"}, {"text": "政府缩小了利率。", "explanation": "这里应该用〈下调〉。缩小用于尺寸或范围，利率、价格的降低要用下调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这份文件缩小着后再发给我。", "corrected_sentence": "他把这份文件缩小后再发给我。", "error_description": "错误：“缩小着后”；正确：“缩小后”。“着”表示持续状态，不能接在“缩小”后表示先后关系，正确为“缩小后再发给我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (96992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这张海报缩小在原来的一半再贴在墙上。", "corrected_sentence": "他把这张海报缩小到原来的一半再贴在墙上。", "error_description": "错误：“缩小在”；正确：“缩小到”。“到”引出缩小后的结果，“在”表示处所，不能接在“缩小”后表示结果。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f12c4a-368d-414f-bc27-099c5f8d3566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
