INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97006, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示程度相当高；很。", "primary_collocate": null, "pronunciation": "mán", "ipa": "man˧˥", "syllable_count": 1, "sentences": [{"text": "他看起来蛮年轻的，其实已经四十岁了。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这儿到公司蛮远的，要坐一个小时车。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试我考得蛮不错，爸爸很满意。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住的地方蛮安静的，晚上很好睡。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友蛮好的，常常帮别人的忙。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路蛮长的，走到家要半小时。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王唱歌蛮好听的，你听过吗？", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天蛮累的，想早点睡觉。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做的蛋糕蛮甜的，小孩子都爱吃。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子蛮聪明的，一学就会。", "target_word": "蛮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蠻", "label": "繁体"}], "register": "口语", "sense_fingerprint": "蛮：副词，表示程度相当高，用在形容词或心理动词前，口语色彩强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ae4c0234-abf6-4c9d-be01-e4d86c3bd9fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97006, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蛮", "is_correct": true, "explanation": "正确。蛮 mán 是口语副词，表示程度相当高。"}, {"text": "满", "is_correct": false, "explanation": "mǎn（第三声）与 mán（第二声）声调不同，意思是满。"}, {"text": "忙", "is_correct": false, "explanation": "máng（第二声）与 mán 韵母不同（an/ang），意思是忙。"}, {"text": "男", "is_correct": false, "explanation": "nán（第二声）与 mán 声母不同（n/m），意思是男人。"}, {"text": "蓝", "is_correct": false, "explanation": "lán（第二声）与 mán 声母不同（l/m），意思是蓝色。"}], "explanations": {"蛮": "正确。蛮 mán 是口语副词，表示程度相当高。", "满": "mǎn（第三声）与 mán（第二声）声调不同，意思是满。", "忙": "máng（第二声）与 mán 韵母不同（an/ang），意思是忙。", "男": "nán（第二声）与 mán 声母不同（n/m），意思是男人。", "蓝": "lán（第二声）与 mán 声母不同（l/m），意思是蓝色。"}, "sentence_index": null, "correct_answer": "蛮"}, "level_3": {"options": [{"text": "才", "is_correct": false, "explanation": "语义：“才”表示刚好或仅仅，与程度无关，“他看起来才年轻的”说不通。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示时间，不表示程度，“已经年轻的”说不通。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示恰好或刚刚，“刚年轻的”说不通。"}, {"text": "蛮", "is_correct": true, "explanation": "正确。“他看起来蛮年轻的”表示程度相当高，口语中常用。"}], "explanations": {"才": "语义：“才”表示刚好或仅仅，与程度无关，“他看起来才年轻的”说不通。", "已经": "语义：“已经”表示时间，不表示程度，“已经年轻的”说不通。", "刚": "语义：“刚”表示恰好或刚刚，“刚年轻的”说不通。", "蛮": "正确。“他看起来蛮年轻的”表示程度相当高，口语中常用。"}, "sentence_index": 0, "correct_answer": "蛮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他比从前蛮胖。", "explanation": "这里应该用〈有点儿〉。“蛮”表示程度高，不能用于“比从前”这种比较句表示略微的变化，应说“有点儿”。"}, {"text": "我蛮在睡觉，别吵我。", "explanation": "这里应该用〈正在〉。“蛮”是程度副词，不能用于表示进行的“在”结构。"}, {"text": "他蛮把书放回了书架。", "explanation": "这里应该用〈随手〉。“蛮”不能修饰“把”字句中的处置动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03b13cbf-25fe-47eb-a04d-dd3255adcba4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
